from heapq import heappop, heappush


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    is_station = [False] * n
    for st in stations:
        is_station[st] = True

    best_c = [[-1] * (max_swaps + 1) for _ in range(n)]

    # Group roads by origin and prune dominated parallel roads / useless self-loops
    raw_adj = [[] for _ in range(n)]
    for u, v, w, e in roads:
        if u == v and e >= 0:
            continue
        raw_adj[u].append((v, w, e))

    adj = [[] for _ in range(n)]
    for u in range(n):
        edges = raw_adj[u]
        if not edges:
            continue
        edges.sort()  # (v, w, e)
        kept = []
        prev_v = -1
        min_e = capacity + 1
        for v, w, e in edges:
            if v != prev_v:
                prev_v = v
                min_e = e
                kept.append((best_c[v], v << 6, w, e))
            elif e < min_e:
                min_e = e
                kept.append((best_c[v], v << 6, w, e))
        # Sort by energy ascending so traversal can break once c < e
        kept.sort(key=lambda item: item[3])
        adj[u] = kept

    # Bit-packed state index: (k << 14) | (u << 6) | (63 - c)
    # Bit-packed heap entry:  (minutes << 17) | idx
    # Encoding (63 - c) pops higher charge states first on ties in (minutes, k).
    INF = 1 << 60
    dist = [INF] * ((max_swaps + 1) << 14)

    start_idx = (s << 6) | (63 - capacity)
    dist[start_idx] = 0
    heap = [start_idx]

    while heap:
        entry = heappop(heap)
        m = entry >> 17
        idx = entry & 0x1FFFF
        if m > dist[idx]:
            continue

        k = idx >> 14
        u = (idx >> 6) & 255
        if u == t:
            return (m, k)

        c = 63 - (idx & 63)
        bc_u = best_c[u]
        if bc_u[k] >= c:
            continue
        for kk in range(k, max_swaps + 1):
            if c > bc_u[kk]:
                bc_u[kk] = c
            else:
                break

        k_shift = k << 14
        for bc_v, v_shift, w, e in adj[u]:
            if c < e:
                break
            nc = c - e
            if nc > capacity:
                nc = capacity
            if bc_v[k] < nc:
                nm = m + w
                nidx = k_shift | v_shift | (63 - nc)
                if nm < dist[nidx]:
                    dist[nidx] = nm
                    heappush(heap, (nm << 17) | nidx)

        if is_station[u] and k < max_swaps and c < capacity:
            nk = k + 1
            if bc_u[nk] < capacity:
                nm = m + swap_time
                nidx = (nk << 14) | (u << 6) | (63 - capacity)
                if nm < dist[nidx]:
                    dist[nidx] = nm
                    heappush(heap, (nm << 17) | nidx)

    return None

package main

import "math"

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type roadEdge struct {
	to     int
	mins   int
	energy int
}

type pqItem struct {
	state int
	mins  int
	swaps int
}

type minHeap []pqItem

func (h minHeap) less(i, j int) bool {
	if h[i].mins != h[j].mins {
		return h[i].mins < h[j].mins
	}
	return h[i].swaps < h[j].swaps
}

func (h *minHeap) push(x pqItem) {
	*h = append(*h, x)
	i := len(*h) - 1
	for i > 0 {
		p := (i - 1) >> 1
		if !h.less(i, p) {
			break
		}
		(*h)[i], (*h)[p] = (*h)[p], (*h)[i]
		i = p
	}
}

func (h *minHeap) pop() pqItem {
	n := len(*h)
	top := (*h)[0]
	(*h)[0] = (*h)[n-1]
	*h = (*h)[:n-1]
	n--
	i := 0
	for {
		l := 2*i + 1
		if l >= n {
			break
		}
		best := l
		r := l + 1
		if r < n && h.less(r, l) {
			best = r
		}
		if !h.less(best, i) {
			break
		}
		(*h)[i], (*h)[best] = (*h)[best], (*h)[i]
		i = best
	}
	return top
}

func FastestDelivery(n int, roads []Tuple1, stations []int, capacity int, swap_time int, max_swaps int, s int, t int) *Tuple2 {
	if s == t {
		return &Tuple2{F0: 0, F1: 0}
	}

	adj := make([][]roadEdge, n)
	for _, r := range roads {
		adj[r.F0] = append(adj[r.F0], roadEdge{
			to:     r.F1,
			mins:   r.F2,
			energy: r.F3,
		})
	}

	isStation := make([]bool, n)
	for _, st := range stations {
		isStation[st] = true
	}

	numCharges := capacity + 1
	numSwaps := max_swaps + 1
	totalStates := n * numCharges * numSwaps

	distMins := make([]int, totalStates)
	distSwaps := make([]int, totalStates)
	for i := range distMins {
		distMins[i] = math.MaxInt
	}

	start := (s*numCharges + capacity) * numSwaps
	distMins[start] = 0
	distSwaps[start] = 0

	var pq minHeap
	pq.push(pqItem{state: start, mins: 0, swaps: 0})

	for len(pq) > 0 {
		cur := pq.pop()
		if cur.mins > distMins[cur.state] || (cur.mins == distMins[cur.state] && cur.swaps > distSwaps[cur.state]) {
			continue
		}

		k := cur.state % numSwaps
		tmp := cur.state / numSwaps
		c := tmp % numCharges
		u := tmp / numCharges

		if u == t {
			return &Tuple2{F0: cur.mins, F1: cur.swaps}
		}

		for _, e := range adj[u] {
			if c < e.energy {
				continue
			}
			nc := c - e.energy
			if nc > capacity {
				nc = capacity
			}
			ns := (e.to*numCharges+nc)*numSwaps + k
			nm := cur.mins + e.mins
			nw := cur.swaps
			if nm < distMins[ns] || (nm == distMins[ns] && nw < distSwaps[ns]) {
				distMins[ns] = nm
				distSwaps[ns] = nw
				pq.push(pqItem{state: ns, mins: nm, swaps: nw})
			}
		}

		if isStation[u] && k < max_swaps && c < capacity {
			ns := (u*numCharges+capacity)*numSwaps + (k + 1)
			nm := cur.mins + swap_time
			nw := cur.swaps + 1
			if nm < distMins[ns] || (nm == distMins[ns] && nw < distSwaps[ns]) {
				distMins[ns] = nm
				distSwaps[ns] = nw
				pq.push(pqItem{state: ns, mins: nm, swaps: nw})
			}
		}
	}

	return nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3) {}

    public record Tuple2(long f0, long f1) {}

    private static final long INF = Long.MAX_VALUE / 4;

    private static final class MinHeap {
        final long[] dist;
        final int[] heap;
        final int[] pos;
        int size;

        MinHeap(int numStates) {
            this.dist = new long[numStates];
            Arrays.fill(this.dist, INF);
            this.heap = new int[numStates];
            this.pos = new int[numStates];
            Arrays.fill(this.pos, -1);
            this.size = 0;
        }

        void pushOrDecrease(int state, long newDist) {
            if (newDist >= dist[state]) {
                return;
            }
            dist[state] = newDist;
            int idx = pos[state];
            if (idx == -1) {
                idx = size++;
            }
            while (idx > 0) {
                int parent = (idx - 1) >>> 1;
                int pState = heap[parent];
                if (dist[pState] <= newDist) {
                    break;
                }
                heap[idx] = pState;
                pos[pState] = idx;
                idx = parent;
            }
            heap[idx] = state;
            pos[state] = idx;
        }

        int popMin() {
            int minState = heap[0];
            pos[minState] = -1;
            int last = heap[--size];
            if (size > 0) {
                int idx = 0;
                long lastDist = dist[last];
                int half = size >>> 1;
                while (idx < half) {
                    int child = (idx << 1) + 1;
                    int cState = heap[child];
                    long cDist = dist[cState];
                    int right = child + 1;
                    if (right < size) {
                        int rState = heap[right];
                        if (dist[rState] < cDist) {
                            child = right;
                            cState = rState;
                            cDist = dist[rState];
                        }
                    }
                    if (lastDist <= cDist) {
                        break;
                    }
                    heap[idx] = cState;
                    pos[cState] = idx;
                    idx = child;
                }
                heap[idx] = last;
                pos[last] = idx;
            }
            return minState;
        }

        boolean isEmpty() {
            return size == 0;
        }
    }

    public static Tuple2 fastestDelivery(long n, List<Tuple1> roads, List<Long> stations, long capacity, long swap_time, long max_swaps, long s, long t) {
        if (s == t) {
            return new Tuple2(0L, 0L);
        }

        int numNodes = (int) n;
        int cap = (int) capacity;
        int maxSwaps = (int) max_swaps;
        int start = (int) s;
        int target = (int) t;

        int m = roads.size();
        int[] head = new int[numNodes];
        Arrays.fill(head, -1);
        int[] to = new int[m];
        int[] next = new int[m];
        long[] edgeMin = new long[m];
        int[] edgeEnergy = new int[m];

        for (int i = 0; i < m; i++) {
            Tuple1 r = roads.get(i);
            int u = (int) r.f0();
            to[i] = (int) r.f1();
            edgeMin[i] = r.f2();
            edgeEnergy[i] = (int) r.f3();
            next[i] = head[u];
            head[u] = i;
        }

        boolean[] isStation = new boolean[numNodes];
        for (long st : stations) {
            if (st >= 0 && st < numNodes) {
                isStation[(int) st] = true;
            }
        }

        int cap1 = cap + 1;
        int sw1 = maxSwaps + 1;
        int totalStates = numNodes * cap1 * sw1;

        MinHeap pq = new MinHeap(totalStates);
        int startState = (start * cap1 + cap) * sw1;
        pq.pushOrDecrease(startState, 0L);

        long bestMinutes = INF;
        long bestSwaps = INF;

        while (!pq.isEmpty()) {
            int state = pq.popMin();
            long d = pq.dist[state];
            if (d > bestMinutes) {
                break;
            }

            int swaps = state % sw1;
            int tmp = state / sw1;
            int charge = tmp % cap1;
            int u = tmp / cap1;

            if (u == target) {
                if (d < bestMinutes || (d == bestMinutes && swaps < bestSwaps)) {
                    bestMinutes = d;
                    bestSwaps = swaps;
                }
            }

            for (int e = head[u]; e != -1; e = next[e]) {
                int en = edgeEnergy[e];
                if (charge >= en) {
                    int nc = charge - en;
                    if (nc > cap) {
                        nc = cap;
                    }
                    int nState = (to[e] * cap1 + nc) * sw1 + swaps;
                    pq.pushOrDecrease(nState, d + edgeMin[e]);
                }
            }

            if (isStation[u] && swaps < maxSwaps && charge < cap) {
                int nState = (u * cap1 + cap) * sw1 + (swaps + 1);
                pq.pushOrDecrease(nState, d + swap_time);
            }
        }

        if (bestMinutes == INF) {
            return null;
        }
        return new Tuple2(bestMinutes, bestSwaps);
    }
}

#include <algorithm>
#include <functional>
#include <limits>
#include <optional>
#include <queue>
#include <tuple>
#include <utility>
#include <vector>

std::optional<std::tuple<long long, long long>> fastest_delivery(
    long long n,
    const std::vector<std::tuple<long long, long long, long long, long long>>& roads,
    const std::vector<long long>& stations,
    long long capacity,
    long long swap_time,
    long long max_swaps,
    long long s,
    long long t) {
    if (s == t) {
        return std::make_tuple(0LL, 0LL);
    }

    const int N = static_cast<int>(n);
    const int cap = static_cast<int>(capacity);
    const int C = cap + 1;
    const int total_states = N * C;
    const long long INF = std::numeric_limits<long long>::max() / 4;

    struct Edge {
        int to;
        long long minutes;
        int energy;
    };

    std::vector<std::vector<Edge>> adj(N);
    for (const auto& [u, v, minutes, energy] : roads) {
        adj[static_cast<int>(u)].push_back({static_cast<int>(v), minutes, static_cast<int>(energy)});
    }

    std::vector<char> is_station(N, 0);
    for (long long st : stations) {
        is_station[static_cast<int>(st)] = 1;
    }
    std::vector<int> station_list;
    for (int u = 0; u < N; ++u) {
        if (is_station[u]) {
            station_list.push_back(u);
        }
    }

    using P = std::pair<long long, int>;
    std::vector<long long> dist(total_states, INF);
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

    auto run_dijkstra = [&]() {
        while (!pq.empty()) {
            auto [d, state] = pq.top();
            pq.pop();
            if (d > dist[state]) continue;

            int u = state / C;
            int c = state % C;

            for (const auto& e : adj[u]) {
                if (c < e.energy) continue;
                int nc = std::min(cap, c - e.energy);
                int nstate = e.to * C + nc;
                long long nd = d + e.minutes;
                if (nd < dist[nstate]) {
                    dist[nstate] = nd;
                    pq.emplace(nd, nstate);
                }
            }
        }
    };

    long long best_time = INF;
    long long best_swaps = -1;

    int start_state = static_cast<int>(s) * C + cap;
    dist[start_state] = 0;
    pq.emplace(0LL, start_state);

    for (long long k = 0; k <= max_swaps; ++k) {
        run_dijkstra();

        long long layer_best = INF;
        int t_base = static_cast<int>(t) * C;
        for (int c = 0; c <= cap; ++c) {
            if (dist[t_base + c] < layer_best) {
                layer_best = dist[t_base + c];
            }
        }
        if (layer_best < best_time) {
            best_time = layer_best;
            best_swaps = k;
        }

        if (k == max_swaps) break;

        std::vector<long long> next_dist(total_states, INF);
        for (int u : station_list) {
            long long min_u = INF;
            int u_base = u * C;
            for (int c = 0; c <= cap; ++c) {
                if (dist[u_base + c] < min_u) {
                    min_u = dist[u_base + c];
                }
            }
            if (min_u < INF) {
                int target_state = u_base + cap;
                long long nd = min_u + swap_time;
                next_dist[target_state] = nd;
                pq.emplace(nd, target_state);
            }
        }
        dist = std::move(next_dist);
    }

    if (best_time == INF) {
        return std::nullopt;
    }
    return std::make_tuple(best_time, best_swaps);
}

export function fastestDelivery(
  n: number,
  roads: [number, number, number, number][],
  stations: number[],
  capacity: number,
  swap_time: number,
  max_swaps: number,
  s: number,
  t: number
): [number, number] | null {
  if (s === t) {
    return [0, 0];
  }

  const isStation = new Uint8Array(n);
  for (let i = 0; i < stations.length; i++) {
    isStation[stations[i]] = 1;
  }

  const m = roads.length;
  const head = new Int32Array(n);
  head.fill(-1);
  const to = new Int32Array(m);
  const next = new Int32Array(m);
  const edgeMin = new Int32Array(m);
  const edgeEng = new Int32Array(m);

  for (let i = 0; i < m; i++) {
    const road = roads[i];
    const u = road[0];
    to[i] = road[1];
    edgeMin[i] = road[2];
    edgeEng[i] = road[3];
    next[i] = head[u];
    head[u] = i;
  }

  const C = capacity + 1;
  const K = max_swaps + 1;
  const totalStates = n * C * K;

  const dist = new Float64Array(totalStates);
  dist.fill(Infinity);

  let heapSize = 0;
  let heapCap = 1024;
  let heapDist = new Float64Array(heapCap);
  let heapNode = new Int32Array(heapCap);

  const push = (d: number, node: number): void => {
    if (heapSize === heapCap) {
      heapCap *= 2;
      const nd = new Float64Array(heapCap);
      nd.set(heapDist);
      heapDist = nd;
      const nn = new Int32Array(heapCap);
      nn.set(heapNode);
      heapNode = nn;
    }
    let i = heapSize++;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heapDist[p] <= d) break;
      heapDist[i] = heapDist[p];
      heapNode[i] = heapNode[p];
      i = p;
    }
    heapDist[i] = d;
    heapNode[i] = node;
  };

  const startIdx = (s * C + capacity) * K;
  dist[startIdx] = 0;
  push(0, startIdx);

  const swapCost = swap_time * 8 + 1;

  while (heapSize > 0) {
    const d = heapDist[0];
    const idx = heapNode[0];
    heapSize--;
    if (heapSize > 0) {
      const lastD = heapDist[heapSize];
      const lastN = heapNode[heapSize];
      let i = 0;
      const half = heapSize >> 1;
      while (i < half) {
        let child = (i << 1) + 1;
        const right = child + 1;
        if (right < heapSize && heapDist[right] < heapDist[child]) {
          child = right;
        }
        if (lastD <= heapDist[child]) break;
        heapDist[i] = heapDist[child];
        heapNode[i] = heapNode[child];
        i = child;
      }
      heapDist[i] = lastD;
      heapNode[i] = lastN;
    }

    if (d !== dist[idx]) continue;

    const k = idx % K;
    const uc = (idx - k) / K;
    const c = uc % C;
    const u = (uc - c) / C;

    if (u === t) {
      const swaps = d % 8;
      const minutes = (d - swaps) / 8;
      return [minutes, swaps];
    }

    for (let e = head[u]; e !== -1; e = next[e]) {
      const eng = edgeEng[e];
      if (c >= eng) {
        let nc = c - eng;
        if (nc > capacity) nc = capacity;
        const nidx = (to[e] * C + nc) * K + k;
        const nd = d + edgeMin[e] * 8;
        if (nd < dist[nidx]) {
          dist[nidx] = nd;
          push(nd, nidx);
        }
      }
    }

    if (isStation[u] && k < max_swaps) {
      const nidx = (u * C + capacity) * K + (k + 1);
      const nd = d + swapCost;
      if (nd < dist[nidx]) {
        dist[nidx] = nd;
        push(nd, nidx);
      }
    }
  }

  return null;
}

from collections import deque


def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    NEG_INF = -10**18
    UNREACHABLE = -10**15

    # dp[0..n-1] for each kept message; dp[-1] (i.e. dp[n]) represents virtual index -1
    dp = [[NEG_INF] * (budget + 1) for _ in range(n + 1)]
    dp[-1][0] = 0

    dqs = [deque() for _ in range(budget + 1)]
    last_pinned = -1

    for i in range(n):
        li, vi, pinned = messages[i]
        dp_prev = dp[i - 1]
        dp_cur = dp[i]

        if li <= budget:
            L = i - max_gap - 1
            if last_pinned > L:
                L = last_pinned
            if -1 > L:
                L = -1

            cur_bonus = bonus if i > 0 else 0
            max_w = budget - li

            for w_prev in range(max_w + 1):
                best = dp_prev[w_prev] + cur_bonus
                dq_w = dqs[w_prev]
                while dq_w and dq_w[0] < L:
                    dq_w.popleft()
                if dq_w:
                    cand = dp[dq_w[0]][w_prev]
                    if cand > best:
                        best = cand
                if best > UNREACHABLE:
                    dp_cur[w_prev + li] = best + vi

        if i < n - 1:
            idx_to_push = i - 1
            for w in range(budget + 1):
                val_prev = dp_prev[w]
                if val_prev > UNREACHABLE:
                    dq_w = dqs[w]
                    while dq_w and dp[dq_w[-1]][w] <= val_prev:
                        dq_w.pop()
                    dq_w.append(idx_to_push)

        if pinned:
            last_pinned = i

    ans = 0 if (last_pinned == -1 and n <= max_gap) else None
    start_end = n - 1 - max_gap
    if last_pinned > start_end:
        start_end = last_pinned
    if 0 > start_end:
        start_end = 0

    for i in range(start_end, n):
        row = dp[i]
        for w in range(budget + 1):
            v = row[w]
            if v > UNREACHABLE:
                if ans is None or v > ans:
                    ans = v

    return ans

package main

import "errors"

type Tuple1 struct {
	F0 int
	F1 int
	F2 bool
}

func BestContext(messages []Tuple1, budget int, max_gap int, bonus int) (*int, error) {
	if budget < 0 || max_gap < 0 {
		return nil, errors.New("budget and max_gap must be non-negative")
	}

	n := len(messages)
	if n == 0 {
		ans := 0
		return &ans, nil
	}

	maxG := max_gap
	if maxG > n {
		maxG = n
	}

	effBudget := 0
	for _, m := range messages {
		if m.F0 <= budget {
			effBudget += m.F0
			if effBudget >= budget {
				effBudget = budget
				break
			}
		}
	}

	const negInf = -1 << 60
	stride := effBudget + 1
	size := (maxG + 1) * stride

	dp := make([]int, size)
	next := make([]int, size)
	for i := range dp {
		dp[i] = negInf
	}
	dp[0] = 0

	for i, m := range messages {
		length, val, pinned := m.F0, m.F1, m.F2
		for idx := range next {
			next[idx] = negInf
		}

		for g := 0; g <= maxG; g++ {
			row := g * stride
			canDrop := !pinned && g+1 <= maxG
			nextDropRow := (g + 1) * stride

			bonusAdd := 0
			if i > 0 && g == 0 {
				bonusAdd = bonus
			}

			for w := 0; w <= effBudget; w++ {
				cur := dp[row+w]
				if cur == negInf {
					continue
				}

				if w+length <= effBudget {
					cand := cur + val + bonusAdd
					if cand > next[w+length] {
						next[w+length] = cand
					}
				}

				if canDrop {
					if cur > next[nextDropRow+w] {
						next[nextDropRow+w] = cur
					}
				}
			}
		}

		dp, next = next, dp
	}

	best := negInf
	for _, v := range dp {
		if v > best {
			best = v
		}
	}

	if best == negInf {
		return nil, nil
	}
	return &best, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, boolean f2) {}

    public static Long bestContext(List<Tuple1> messages, long budget, long max_gap, long bonus) {
        if (budget < 0 || max_gap < 0) {
            throw new IllegalArgumentException("budget and max_gap must be non-negative");
        }

        int n = messages.size();
        if (n == 0) {
            return 0L;
        }

        long sumPickable = 0;
        boolean anyPinned = false;
        for (Tuple1 msg : messages) {
            if (msg.f0() <= budget) {
                sumPickable += msg.f0();
            }
            if (msg.f2()) {
                anyPinned = true;
            }
        }

        int b = (int) Math.min(budget, sumPickable);
        final long negInf = Long.MIN_VALUE / 4;

        // dp[i][w] = max score for prefix 0..i keeping message i with total kept length w
        long[][] dp = new long[n][b + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], negInf);
        }

        for (int i = 0; i < n; i++) {
            Tuple1 curMsg = messages.get(i);
            long lenLong = curMsg.f0();
            if (lenLong > b) {
                continue;
            }
            int len = (int) lenLong;
            long val = curMsg.f1();
            long[] curDp = dp[i];

            boolean noPinnedBefore = true;
            int minJ = (int) Math.max(0L, (long) i - max_gap - 1L);
            for (int j = i - 1; j >= minJ; j--) {
                long[] prevDp = dp[j];
                long add = val + (j == i - 1 ? bonus : 0L);
                for (int w = len; w <= b; w++) {
                    long prev = prevDp[w - len];
                    if (prev != negInf) {
                        long cand = prev + add;
                        if (cand > curDp[w]) {
                            curDp[w] = cand;
                        }
                    }
                }
                if (messages.get(j).f2()) {
                    noPinnedBefore = false;
                    break;
                }
            }

            if (noPinnedBefore && i <= max_gap) {
                if (val > curDp[len]) {
                    curDp[len] = val;
                }
            }
        }

        long best = negInf;
        if (!anyPinned && n <= max_gap) {
            best = 0L;
        }

        int minLast = (int) Math.max(0L, (long) n - 1L - max_gap);
        for (int i = n - 1; i >= minLast; i--) {
            long[] row = dp[i];
            for (int w = 0; w <= b; w++) {
                if (row[w] > best) {
                    best = row[w];
                }
            }
            if (messages.get(i).f2()) {
                break;
            }
        }

        return best == negInf ? null : best;
    }
}

#include <algorithm>
#include <limits>
