std::optional<long long> best_context(
    const std::vector<std::tuple<long long, long long, bool>>& messages,
    long long budget,
    long long max_gap,
    long long bonus) {
    if (budget < 0 || max_gap < 0) {
        throw std::invalid_argument("budget and max_gap must be non-negative");
    }

    const long long n = static_cast<long long>(messages.size());
    const long long NEG_INF = std::numeric_limits<long long>::min() / 4;

    std::vector<std::vector<long long>> dp(
        static_cast<std::size_t>(n),
        std::vector<long long>(static_cast<std::size_t>(budget + 1), NEG_INF));

    long long last_pinned = -1;

    for (long long i = 0; i < n; ++i) {
        const auto [len, val, pinned] = messages[static_cast<std::size_t>(i)];

        if (len <= budget) {
            if (last_pinned == -1 && i <= max_gap) {
                dp[static_cast<std::size_t>(i)][static_cast<std::size_t>(len)] =
                    std::max(dp[static_cast<std::size_t>(i)][static_cast<std::size_t>(len)], val);
            }

            const long long j_start = std::max({0LL, last_pinned, i - max_gap - 1});
            for (long long j = j_start; j < i; ++j) {
                const long long extra = val + (j == i - 1 ? bonus : 0LL);
                const auto& prev = dp[static_cast<std::size_t>(j)];
                auto& curr = dp[static_cast<std::size_t>(i)];
                for (long long w = len; w <= budget; ++w) {
                    const long long prev_score = prev[static_cast<std::size_t>(w - len)];
                    if (prev_score != NEG_INF) {
                        curr[static_cast<std::size_t>(w)] =
                            std::max(curr[static_cast<std::size_t>(w)], prev_score + extra);
                    }
                }
            }
        }

        if (pinned) {
            last_pinned = i;
        }
    }

    std::optional<long long> best;

    if (last_pinned == -1 && n <= max_gap) {
        best = 0;
    }

    const long long last_start = std::max({0LL, last_pinned, n - 1 - max_gap});
    for (long long i = last_start; i < n; ++i) {
        for (long long w = 0; w <= budget; ++w) {
            const long long score = dp[static_cast<std::size_t>(i)][static_cast<std::size_t>(w)];
            if (score != NEG_INF) {
                if (!best.has_value() || score > *best) {
                    best = score;
                }
            }
        }
    }

    return best;
}

export function bestContext(
  messages: [number, number, boolean][],
  budget: number,
  max_gap: number,
  bonus: number,
): number | null {
  if (budget < 0 || max_gap < 0) {
    throw new Error("budget and max_gap must be non-negative");
  }

  const n = messages.length;
  if (n === 0) {
    return 0;
  }

  const dp: Float64Array[] = new Array(n);
  for (let i = 0; i < n; i++) {
    dp[i] = new Float64Array(budget + 1).fill(-Infinity);
  }

  let lastPinned = -1;
  for (let i = 0; i < n; i++) {
    const [len, val, pinned] = messages[i];
    if (len <= budget) {
      const cur = dp[i];
      if (lastPinned === -1 && i <= max_gap) {
        cur[len] = val;
      }

      const minP = Math.max(0, i - max_gap - 1, lastPinned);
      const limit = budget - len;
      for (let p = minP; p < i; p++) {
        const prev = dp[p];
        const add = val + (p === i - 1 ? bonus : 0);
        for (let w = 0; w <= limit; w++) {
          const prevVal = prev[w];
          if (prevVal !== -Infinity) {
            const nextVal = prevVal + add;
            if (nextVal > cur[w + len]) {
              cur[w + len] = nextVal;
            }
          }
        }
      }
    }

    if (pinned) {
      lastPinned = i;
    }
  }

  let best = -Infinity;
  if (lastPinned === -1 && n <= max_gap) {
    best = 0;
  }

  const minLast = Math.max(0, n - 1 - max_gap, lastPinned);
  for (let i = minLast; i < n; i++) {
    const cur = dp[i];
    for (let w = 0; w <= budget; w++) {
      if (cur[w] > best) {
        best = cur[w];
      }
    }
  }

  if (best === -Infinity) {
    return null;
  }
  return best === 0 ? 0 : best;
}

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Compute bottom-up post-order iteratively to avoid recursion limits.
    order = []
    stack = [0]
    while stack:
        u = stack.pop()
        order.append(u)
        for v in children[u]:
            stack.append(v)
    order.reverse()

    INF = 10**18
    subtree_demand = [0] * n
    has_critical = [False] * n
    cut_subtree_cost = [0] * n
    dp = [None] * n

    for u in order:
        sd = demand[u]
        hc = critical[u]
        for v in children[u]:
            sd += subtree_demand[v]
            if has_critical[v]:
                hc = True
        subtree_demand[u] = sd
        has_critical[u] = hc
        if u >= 1:
            cut_subtree_cost[u] = cut_cost[u] + penalty * sd

        cap_u = root_cap if u == 0 else cap[u]
        if demand[u] > cap_u:
            if u == 0 or hc:
                return None
            dp[u] = None
            continue

        valid_u = [(demand[u], 0)]
        for v in children[u]:
            valid_v = dp[v]
            crit_v = has_critical[v]

            if valid_v is None:
                if crit_v:
                    valid_u = None
                    break
                cut_v = cut_subtree_cost[v]
                valid_u = [(i, c + cut_v) for i, c in valid_u]
                continue

            min_i = valid_u[0][0]
            max_i = valid_u[-1][0]
            max_j = valid_v[-1][0]
            new_l = cap_u if cap_u < max_i + max_j else max_i + max_j

            new_dp = [INF] * (new_l + 1)
            if not crit_v:
                cut_v = cut_subtree_cost[v]
                for i, c_u in valid_u:
                    new_dp[i] = c_u + cut_v

            max_j_allowed = new_l - min_i
            for j, c_v in valid_v:
                if j > max_j_allowed:
                    break
                limit = new_l - j
                for i, c_u in valid_u:
                    if i > limit:
                        break
                    s = i + j
                    cand = c_u + c_v
                    if cand < new_dp[s]:
                        new_dp[s] = cand

            valid_u = [(i, c) for i, c in enumerate(new_dp) if c < INF]
            if not valid_u:
                valid_u = None
                break

        if valid_u is None and (u == 0 or hc):
            return None
        dp[u] = valid_u

    return min(c for _, c in dp[0])

package main

func MinPruningCost(parent []int, demand []int, cap []int, cut_cost []int, critical []bool, root_cap int, penalty int) *int {
	n := len(parent)
	children := make([][]int, n)
	for v := 1; v < n; v++ {
		p := parent[v]
		children[p] = append(children[p], v)
	}

	order := make([]int, 0, n)
	order = append(order, 0)
	for head := 0; head < len(order); head++ {
		u := order[head]
		for _, c := range children[u] {
			order = append(order, c)
		}
	}

	const inf = 1 << 60

	subtreeDemand := make([]int, n)
	hasCrit := make([]bool, n)
	dp := make([][]int, n)

	for i := n - 1; i >= 0; i-- {
		v := order[i]
		sd := demand[v]
		hc := critical[v]
		for _, c := range children[v] {
			sd += subtreeDemand[c]
			if hasCrit[c] {
				hc = true
			}
		}
		subtreeDemand[v] = sd
		hasCrit[v] = hc

		effCap := cap[v]
		if v == 0 {
			effCap = root_cap
		}

		if demand[v] > effCap {
			dp[v] = nil
			continue
		}

		curLimit := demand[v]
		cur := make([]int, curLimit+1)
		for l := 0; l < curLimit; l++ {
			cur[l] = inf
		}
		cur[demand[v]] = 0

		for _, c := range children[v] {
			cMaxLoad := 0
			if len(dp[c]) > 0 {
				cMaxLoad = len(dp[c]) - 1
			}
			nextLimit := curLimit + cMaxLoad
			if nextLimit > effCap {
				nextLimit = effCap
			}
			next := make([]int, nextLimit+1)
			for l := 0; l <= nextLimit; l++ {
				next[l] = inf
			}

			if !hasCrit[c] {
				cutCost := cut_cost[c] + penalty*subtreeDemand[c]
				limitB := curLimit
				if limitB > nextLimit {
					limitB = nextLimit
				}
				for l := 0; l <= limitB; l++ {
					if cur[l] < inf {
						cost := cur[l] + cutCost
						if cost < next[l] {
							next[l] = cost
						}
					}
				}
			}

			if len(dp[c]) > 0 {
				dc := dp[c]
				for l1 := 0; l1 <= curLimit; l1++ {
					c1 := cur[l1]
					if c1 >= inf {
						continue
					}
					maxL2 := nextLimit - l1
					if maxL2 > cMaxLoad {
						maxL2 = cMaxLoad
					}
					for l2 := 0; l2 <= maxL2; l2++ {
						c2 := dc[l2]
						if c2 < inf {
							cost := c1 + c2
							if cost < next[l1+l2] {
								next[l1+l2] = cost
							}
						}
					}
				}
			}

			lastValid := -1
			for l := nextLimit; l >= 0; l-- {
				if next[l] < inf {
					lastValid = l
					break
				}
			}
			if lastValid == -1 {
				cur = nil
				break
			}
			cur = next[:lastValid+1]
			curLimit = lastValid
		}

		dp[v] = cur
		for _, c := range children[v] {
			dp[c] = nil
		}
	}

	if len(dp[0]) == 0 {
		return nil
	}

	ans := inf
	for _, cost := range dp[0] {
		if cost < ans {
			ans = cost
		}
	}
	if ans >= inf {
		return nil
	}
	return &ans
}

import java.util.*;

public final class Solution {
    private static final long INF = Long.MAX_VALUE / 4;

    public static Long minPruningCost(List<Long> parent, List<Long> demand, List<Long> cap, List<Long> cut_cost, List<Boolean> critical, long root_cap, long penalty) {
        int n = parent.size();
        @SuppressWarnings("unchecked")
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int v = 1; v < n; v++) {
            int p = parent.get(v).intValue();
            children[p].add(v);
        }

        int[] order = new int[n];
        int head = 0, tail = 0;
        order[tail++] = 0;
        while (head < tail) {
            int u = order[head++];
            for (int c : children[u]) {
                order[tail++] = c;
            }
        }

        long[] subtreeDemand = new long[n];
        boolean[] hasCritical = new boolean[n];
        long[][] dp = new long[n][];

        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            long subDem = demand.get(v);
            boolean hasCrit = critical.get(v);
            for (int c : children[v]) {
                subDem += subtreeDemand[c];
                if (hasCritical[c]) {
                    hasCrit = true;
                }
            }
            subtreeDemand[v] = subDem;
            hasCritical[v] = hasCrit;

            long rawCap = (v == 0) ? root_cap : cap.get(v);
            int capV = (int) Math.min(rawCap, subDem);
            int demV = demand.get(v).intValue();

            if (demV > capV) {
                dp[v] = new long[0];
                continue;
            }

            int curMax = demV;
            long[] cur = new long[curMax + 1];
            Arrays.fill(cur, INF);
            cur[curMax] = 0;

            boolean possible = true;
            for (int c : children[v]) {
                long[] cDp = dp[c];
                long cutOpt = hasCritical[c] ? INF : (cut_cost.get(c) + penalty * subtreeDemand[c]);
                if (cDp.length == 0 && cutOpt >= INF) {
                    possible = false;
                    break;
                }

                int cMax = cDp.length > 0 ? cDp.length - 1 : 0;
                int nextMax = Math.min(capV, curMax + cMax);
                long[] next = new long[nextMax + 1];
                Arrays.fill(next, INF);

                if (cutOpt < INF) {
                    for (int l = 0; l <= curMax; l++) {
                        if (cur[l] < INF) {
                            long val = cur[l] + cutOpt;
                            if (val < next[l]) {
                                next[l] = val;
                            }
                        }
                    }
                }

                if (cDp.length > 0) {
                    for (int l = 0; l <= curMax; l++) {
                        long base = cur[l];
                        if (base >= INF) {
                            continue;
                        }
                        int maxLc = Math.min(cMax, nextMax - l);
                        for (int lc = 0; lc <= maxLc; lc++) {
                            long cVal = cDp[lc];
                            if (cVal < INF) {
                                long val = base + cVal;
                                if (val < next[l + lc]) {
                                    next[l + lc] = val;
                                }
                            }
                        }
                    }
                }

                cur = next;
                curMax = nextMax;
            }

            dp[v] = possible ? cur : new long[0];
        }

        long ans = INF;
        for (long val : dp[0]) {
            if (val < ans) {
                ans = val;
            }
        }
        return ans >= INF ? null : ans;
    }
}

#include <algorithm>
#include <cstddef>
#include <limits>
#include <optional>
#include <vector>

std::optional<long long> min_pruning_cost(
    const std::vector<long long>& parent,
    const std::vector<long long>& demand,
    const std::vector<long long>& cap,
    const std::vector<long long>& cut_cost,
    const std::vector<bool>& critical,
    long long root_cap,
    long long penalty) {
    const int n = static_cast<int>(parent.size());
    if (n == 0) {
        return 0LL;
    }

    std::vector<std::vector<int>> children(n);
    for (int v = 1; v < n; ++v) {
        children[static_cast<int>(parent[v])].push_back(v);
    }

    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> subtree_demand(n, 0);
    std::vector<char> has_critical(n, 0);

    auto dfs = [&](auto& self, int u) -> std::vector<long long> {
        subtree_demand[u] = demand[u];
        has_critical[u] = critical[u] ? 1 : 0;

        std::vector<std::vector<long long>> child_dps;
        child_dps.reserve(children[u].size());
        for (int c : children[u]) {
            child_dps.push_back(self(self, c));
            subtree_demand[u] += subtree_demand[c];
            if (has_critical[c]) {
                has_critical[u] = 1;
            }
        }

        const long long cap_u = (u == 0) ? root_cap : cap[u];
        if (demand[u] > cap_u) {
            return {};
        }

        long long cur_max = demand[u];
        std::vector<long long> cur_dp(static_cast<std::size_t>(cur_max) + 1, INF);
        cur_dp[static_cast<std::size_t>(demand[u])] = 0;

        for (std::size_t idx = 0; idx < children[u].size(); ++idx) {
            const int c = children[u][idx];
            const auto& c_dp = child_dps[idx];
            const long long cut_val = has_critical[c]
                ? INF
                : (cut_cost[c] + penalty * subtree_demand[c]);

            const long long c_max = static_cast<long long>(c_dp.size()) - 1;
            const long long new_max = std::min(cap_u, cur_max + std::max(0LL, c_max));
            std::vector<long long> next_dp(static_cast<std::size_t>(new_max) + 1, INF);

            for (long long w = 0; w <= cur_max; ++w) {
                const long long base = cur_dp[static_cast<std::size_t>(w)];
                if (base >= INF) {
                    continue;
                }
                if (cut_val < INF) {
                    auto& target = next_dp[static_cast<std::size_t>(w)];
                    target = std::min(target, base + cut_val);
                }
                const long long limit = std::min(c_max, new_max - w);
                for (long long wc = 0; wc <= limit; ++wc) {
                    const long long child_cost = c_dp[static_cast<std::size_t>(wc)];
                    if (child_cost < INF) {
                        auto& target = next_dp[static_cast<std::size_t>(w + wc)];
                        target = std::min(target, base + child_cost);
                    }
                }
            }

            cur_dp = std::move(next_dp);
            cur_max = new_max;
        }

        return cur_dp;
    };

    const std::vector<long long> root_dp = dfs(dfs, 0);
    long long ans = INF;
    for (long long val : root_dp) {
        ans = std::min(ans, val);
    }
    if (ans >= INF) {
        return std::nullopt;
    }
    return ans;
}

export function minPruningCost(
  parent: number[],
  demand: number[],
  cap: number[],
  cut_cost: number[],
  critical: boolean[],
  root_cap: number,
  penalty: number,
): number | null {
  const n = parent.length;
  const children: number[][] = Array.from({ length: n }, () => []);
  for (let v = 1; v < n; v++) {
    children[parent[v]].push(v);
  }

  // BFS to produce a topological order (parents before children)
  const order = new Int32Array(n);
  let head = 0;
  let tail = 0;
  order[tail++] = 0;
  while (head < tail) {
    const u = order[head++];
    const ch = children[u];
    for (let i = 0; i < ch.length; i++) {
      order[tail++] = ch[i];
    }
  }

  const INF = 1e15;
  const subtreeDemand = new Int32Array(n);
  const hasCritical = new Uint8Array(n);
  const dp: (Float64Array | null)[] = new Array(n).fill(null);

  for (let idx = n - 1; idx >= 0; idx--) {
    const v = order[idx];
    const ch = children[v];

    let subDem = demand[v];
    let hasCrit = critical[v] ? 1 : 0;
    for (let i = 0; i < ch.length; i++) {
      const c = ch[i];
      subDem += subtreeDemand[c];
      if (hasCritical[c]) {
        hasCrit = 1;
      }
    }
    subtreeDemand[v] = subDem;
    hasCritical[v] = hasCrit;

    const capV = v === 0 ? root_cap : cap[v];
    if (demand[v] > capV) {
      dp[v] = null;
      continue;
    }

    const maxPossible = Math.min(capV, subDem);
    let curDp = new Float64Array(maxPossible + 1);
    let nextDp = new Float64Array(maxPossible + 1);
    let curMax = demand[v];
    curDp.fill(INF, 0, curMax + 1);
    curDp[curMax] = 0;

    let feasible = true;
    for (let i = 0; i < ch.length; i++) {
      const c = ch[i];
      const cDp = dp[c];
      const maxLoadC = cDp === null ? -1 : cDp.length - 1;
      const nextMax = Math.min(capV, curMax + (maxLoadC >= 0 ? maxLoadC : 0));
      nextDp.fill(INF, 0, nextMax + 1);

      // Option 1: cut the line between c and v (only if c's subtree has no critical nodes)
      if (!hasCritical[c]) {
        const cutCost = cut_cost[c] + penalty * subtreeDemand[c];
        for (let l = 0; l <= curMax; l++) {
          const val = curDp[l];
          if (val < INF) {
            const cand = val + cutCost;
            if (cand < nextDp[l]) {
              nextDp[l] = cand;
            }
          }
        }
      }

      // Option 2: retain c
      if (cDp !== null) {
        for (let lc = 0; lc <= maxLoadC; lc++) {
          const costC = cDp[lc];
          if (costC >= INF) {
            continue;
          }
          const limitL = Math.min(curMax, capV - lc);
          for (let l = 0; l <= limitL; l++) {
            const val = curDp[l];
            if (val < INF) {
              const cand = val + costC;
              if (cand < nextDp[l + lc]) {
                nextDp[l + lc] = cand;
              }
            }
          }
        }
        dp[c] = null;
      }

      let actualMax = -1;
      for (let l = nextMax; l >= 0; l--) {
        if (nextDp[l] < INF) {
          actualMax = l;
          break;
        }
      }
      if (actualMax === -1) {
        feasible = false;
        break;
      }
      curMax = actualMax;
      const tmp = curDp;
      curDp = nextDp;
      nextDp = tmp;
    }

    dp[v] = feasible ? curDp.subarray(0, curMax + 1) : null;
  }

  const rootDp = dp[0];
  if (rootDp === null) {
    return null;
  }

  let ans = INF;
  for (let l = 0; l < rootDp.length; l++) {
    if (rootDp[l] < ans) {
      ans = rootDp[l];
    }
  }
  return ans < INF ? ans : null;
}

from heapq import heappop, heappush
from operator import itemgetter


def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings <= 0 or not connections:
        return None

    n = len(transfer)
    inf_b = max_boardings + 1
    min_boardings_ready = [inf_b] * n
    trip_boardings = {}

    ready_heap = [(start_time, source, 0)]
    best_target = float("inf")

    for trip_id, u, v, dep, arr in sorted(connections, key=itemgetter(3)):
        if dep < start_time:
            continue
        if dep >= best_target:
            break

        while ready_heap and ready_heap[0][0] <= dep:
            _, st, b = heappop(ready_heap)
            if b < min_boardings_ready[st]:
                min_boardings_ready[st] = b

        on_trip = trip_boardings.get(trip_id, inf_b)
        at_station = min_boardings_ready[u] + 1
        b = on_trip if on_trip < at_station else at_station

        if b <= max_boardings:
            if b < on_trip:
                trip_boardings[trip_id] = b
            if v == target:
                if arr < best_target:
                    best_target = arr
            elif b < min_boardings_ready[v]:
                rt = arr + transfer[v]
                if rt < best_target:
                    heappush(ready_heap, (rt, v, b))

    return None if best_target == float("inf") else best_target

package main

import (
	"math"
	"sort"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
	F4 int
}

type conn struct {
	trip int
	from int
	to   int
	dep  int
	arr  int
}

type readyEvent struct {
	time      int
	station   int
	boardings int
}

func EarliestArrival(connections []Tuple1, transfer []int, source int, target int, start_time int, max_boardings int) *int {
	if source == target {
		ans := start_time
		return &ans
	}
	if max_boardings <= 0 || len(connections) == 0 {
		return nil
	}

	const infBoardings = math.MaxInt64 / 4
	if max_boardings >= infBoardings {
		max_boardings = infBoardings - 1
	}

	tripMap := make(map[int]int)
	conns := make([]conn, 0, len(connections))
	for _, c := range connections {
		if c.F3 < start_time {
			continue
		}
		tid, ok := tripMap[c.F0]
		if !ok {
			tid = len(tripMap)
			tripMap[c.F0] = tid
		}
		conns = append(conns, conn{
			trip: tid,
			from: c.F1,
			to:   c.F2,
			dep:  c.F3,
			arr:  c.F4,
		})
	}

	if len(conns) == 0 {
		return nil
	}

	sort.Slice(conns, func(i, j int) bool {
		return conns[i].dep < conns[j].dep
	})

	numStations := len(transfer)
	minBoardings := make([]int, numStations)
	for i := range minBoardings {
		minBoardings[i] = infBoardings
	}
	minBoardings[source] = 0

	tripMinBoardings := make([]int, len(tripMap))
	for i := range tripMinBoardings {
		tripMinBoardings[i] = infBoardings
	}

	const infTime = math.MaxInt64
	bestArrival := infTime

	heap := make([]readyEvent, 0)

	for _, c := range conns {
		if c.dep >= bestArrival {
			break
		}

		for len(heap) > 0 && heap[0].time <= c.dep {
			top := heap[0]
			last := heap[len(heap)-1]
			heap = heap[:len(heap)-1]
			if len(heap) > 0 {
				heap[0] = last
				idx := 0
				n := len(heap)
				for {
					l := (idx << 1) + 1
					if l >= n {
						break
					}
					best := l
					r := l + 1
					if r < n && heap[r].time < heap[l].time {
						best = r
					}
					if heap[idx].time <= heap[best].time {
						break
					}
					heap[idx], heap[best] = heap[best], heap[idx]
					idx = best
				}
			}
			if top.boardings < minBoardings[top.station] {
				minBoardings[top.station] = top.boardings
			}
		}

		b := tripMinBoardings[c.trip]
		if cand := minBoardings[c.from] + 1; cand < b {
			b = cand
		}
		if b > max_boardings {
			continue
		}

		tripMinBoardings[c.trip] = b
		if c.to == target {
			if c.arr < bestArrival {
				bestArrival = c.arr
			}
		} else {
			readyTime := c.arr + transfer[c.to]
			if readyTime < bestArrival && b < minBoardings[c.to] {
				heap = append(heap, readyEvent{
					time:      readyTime,
					station:   c.to,
					boardings: b,
				})
				idx := len(heap) - 1
				for idx > 0 {
					p := (idx - 1) >> 1
					if heap[p].time <= heap[idx].time {
						break
					}
					heap[p], heap[idx] = heap[idx], heap[p]
					idx = p
				}
			}
		}
	}

	if bestArrival == infTime {
		return nil
	}
	return &bestArrival
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3, long f4) {}

    public static Long earliestArrival(List<Tuple1> connections, List<Long> transfer, long source, long target, long start_time, long max_boardings) {
        int src = (int) source;
        int tgt = (int) target;
        if (src == tgt) {
            return start_time;
        }
        int m = connections.size();
        if (m == 0 || max_boardings <= 0) {
            return null;
        }

        int n = transfer.size();
        long[] trans = new long[n];
        for (int i = 0; i < n; i++) {
            trans[i] = transfer.get(i);
        }

        int[] cTrip = new int[m];
        int[] cFrom = new int[m];
        int[] cTo = new int[m];
        long[] cDep = new long[m];
        long[] cArr = new long[m];

        HashMap<Long, Integer> tripIdMap = new HashMap<>(Math.min(m * 2, 1 << 17));
        int[] tripCount = new int[m];
        int numTrips = 0;
        int[] stationCount = new int[n];

        for (int i = 0; i < m; i++) {
            Tuple1 t = connections.get(i);
            Integer tid = tripIdMap.get(t.f0());
            int id;
            if (tid == null) {
                id = numTrips++;
                tripIdMap.put(t.f0(), id);
            } else {
                id = tid;
            }
            cTrip[i] = id;
            int from = (int) t.f1();
            int to = (int) t.f2();
            cFrom[i] = from;
            cTo[i] = to;
            cDep[i] = t.f3();
            cArr[i] = t.f4();
            tripCount[id]++;
            stationCount[from]++;
        }

        int[] tripStart = new int[numTrips + 1];
        for (int t = 0; t < numTrips; t++) {
            tripStart[t + 1] = tripStart[t] + tripCount[t];
        }
        int[] tripFill = Arrays.copyOf(tripStart, numTrips);
        int[] tripConns = new int[m];
        for (int i = 0; i < m; i++) {
            int t = cTrip[i];
            tripConns[tripFill[t]++] = i;
        }

        int[] tmp = new int[m];
        int[] tripEnd = new int[numTrips];
        int[] cGPos = new int[m];
        for (int t = 0; t < numTrips; t++) {
            int s = tripStart[t];
            int e = tripStart[t + 1];
            sortSlice(tripConns, s, e, cDep, tmp);
            tripEnd[t] = e;
            for (int p = s; p < e; p++) {
                cGPos[tripConns[p]] = p;
            }
        }

        int[] stationStart = new int[n + 1];
        for (int x = 0; x < n; x++) {
            stationStart[x + 1] = stationStart[x] + stationCount[x];
        }
        int[] stationFill = Arrays.copyOf(stationStart, n);
        int[] stationOut = new int[m];
        for (int i = 0; i < m; i++) {
            int from = cFrom[i];
            stationOut[stationFill[from]++] = i;
        }
        int[] stationPtr = new int[n];
        for (int x = 0; x < n; x++) {
            int s = stationStart[x];
            int e = stationStart[x + 1];
            sortSlice(stationOut, s, e, cDep, tmp);
            stationPtr[x] = e;
        }

        final long INF = Long.MAX_VALUE / 4;
        long[] bestReady = new long[n];
        Arrays.fill(bestReady, INF);
        bestReady[src] = start_time;
        long bestTarget = INF;

        int[] marked = new int[n];
        long[] roundReady = new long[n];
        int[] nextMarked = new int[n];
        int[] lastMarkedRound = new int[n];

        marked[0] = src;
        int markedCount = 1;

        long maxRounds = Math.min(max_boardings, (long) n - 1);
        for (int round = 1; round <= maxRounds && markedCount > 0; round++) {
            for (int i = 0; i < markedCount; i++) {
                roundReady[i] = bestReady[marked[i]];
            }
            int nextCount = 0;
            for (int i = 0; i < markedCount; i++) {
                int x = marked[i];
                long r = roundReady[i];
                int ptr = stationPtr[x];
                int limit = stationStart[x];
                while (ptr > limit && cDep[stationOut[ptr - 1]] >= r) {
                    ptr--;
                    int c = stationOut[ptr];
                    int t = cTrip[c];
                    int gPos = cGPos[c];
                    int tEnd = tripEnd[t];
                    if (gPos < tEnd) {
                        for (int p = gPos; p < tEnd; p++) {
                            int conn = tripConns[p];
                            int y = cTo[conn];
                            long arr = cArr[conn];
                            if (y == tgt && arr < bestTarget) {
                                bestTarget = arr;
                            }
                            long nr = arr + trans[y];
                            if (nr < bestReady[y]) {
                                bestReady[y] = nr;
                                if (lastMarkedRound[y] != round) {
                                    lastMarkedRound[y] = round;
                                    nextMarked[nextCount++] = y;
                                }
                            }
                        }
                        tripEnd[t] = gPos;
                    }
                }
                stationPtr[x] = ptr;
            }
            int[] swap = marked;
            marked = nextMarked;
            nextMarked = swap;
            markedCount = nextCount;
        }

        return bestTarget == INF ? null : bestTarget;
    }

    private static void sortSlice(int[] arr, int lo, int hi, long[] keys, int[] tmp) {
        if (hi - lo <= 16) {
            for (int i = lo + 1; i < hi; i++) {
                int x = arr[i];
                long kx = keys[x];
                int j = i - 1;
                while (j >= lo && keys[arr[j]] > kx) {
                    arr[j + 1] = arr[j];
                    j--;
                }
                arr[j + 1] = x;
            }
            return;
        }
        int mid = (lo + hi) >>> 1;
        sortSlice(arr, lo, mid, keys, tmp);
        sortSlice(arr, mid, hi, keys, tmp);
        if (keys[arr[mid - 1]] <= keys[arr[mid]]) {
            return;
        }
        System.arraycopy(arr, lo, tmp, lo, mid - lo);
        int i = lo;
        int j = mid;
        int k = lo;
        while (i < mid && j < hi) {
            if (keys[tmp[i]] <= keys[arr[j]]) {
                arr[k++] = tmp[i++];
            } else {
                arr[k++] = arr[j++];
            }
        }
        while (i < mid) {
            arr[k++] = tmp[i++];
        }
    }
}

#include <algorithm>
#include <limits>
#include <optional>
#include <tuple>
#include <vector>

std::optional<long long> earliest_arrival(
    const std::vector<std::tuple<long long, long long, long long, long long, long long>>& connections,
    const std::vector<long long>& transfer,
    long long source,
    long long target,
    long long start_time,
    long long max_boardings) {
    if (source == target) {
        return start_time;
    }
    int n = static_cast<int>(transfer.size());
    int m = static_cast<int>(connections.size());
    if (max_boardings <= 0 || m == 0) {
        return std::nullopt;
    }

    struct Conn {
        long long trip_id;
        long long dep;
        long long arr;
        int from;
        int to;
    };

    std::vector<Conn> conns;
    conns.reserve(m);
    for (const auto& t : connections) {
        conns.push_back({
            std::get<0>(t),
            std::get<3>(t),
            std::get<4>(t),
            static_cast<int>(std::get<1>(t)),
            static_cast<int>(std::get<2>(t))
        });
    }

    std::sort(conns.begin(), conns.end(), [](const Conn& a, const Conn& b) {
        if (a.trip_id != b.trip_id) {
            return a.trip_id < b.trip_id;
        }
        return a.dep < b.dep;
    });

    std::vector<int> trip_end;
    std::vector<int> conn_trip(m);
    std::vector<int> deg(n, 0);
    int num_trips = 0;
    for (int i = 0; i < m;) {
        long long tid = conns[i].trip_id;
        int j = i;
        while (j < m && conns[j].trip_id == tid) {
            conn_trip[j] = num_trips;
            ++deg[conns[j].from];
            ++j;
        }
        trip_end.push_back(j);
        ++num_trips;
        i = j;
    }

    struct Dep {
        long long dep;
        int conn_idx;
        int trip_idx;
    };

    std::vector<std::vector<Dep>> departures(n);
    for (int u = 0; u < n; ++u) {
        departures[u].reserve(deg[u]);
    }
    for (int i = 0; i < m; ++i) {
        departures[conns[i].from].push_back({conns[i].dep, i, conn_trip[i]});
    }
    for (int u = 0; u < n; ++u) {
        std::sort(departures[u].begin(), departures[u].end(), [](const Dep& a, const Dep& b) {
            return a.dep < b.dep;
        });
    }

    const long long INF = std::numeric_limits<long long>::max();
    const int UNSET = m + 1;

    std::vector<long long> ready(n, INF);
    std::vector<int> ptr(n);
    for (int u = 0; u < n; ++u) {
        ptr[u] = static_cast<int>(departures[u].size());
    }

    std::vector<int> best_boarded = std::move(trip_end);
    std::vector<int> round_min(num_trips, UNSET);
    std::vector<int> stamp(n, 0);

    int src = static_cast<int>(source);
    int tgt = static_cast<int>(target);
    ready[src] = start_time;

    std::vector<int> marked = {src};
    std::vector<int> next_marked;
    std::vector<int> touched_trips;

    long long ans = INF;
    bool found = false;

    for (long long round = 1; round <= max_boardings && !marked.empty(); ++round) {
        int round_id = static_cast<int>(round);

        for (int u : marked) {
            long long r_u = ready[u];
            const auto& deps = departures[u];
            int p = ptr[u];
            while (p > 0 && deps[p - 1].dep >= r_u) {
                --p;
                int t = deps[p].trip_idx;
                int c_idx = deps[p].conn_idx;
                if (c_idx < best_boarded[t] && c_idx < round_min[t]) {
                    if (round_min[t] == UNSET) {
                        touched_trips.push_back(t);
                    }
                    round_min[t] = c_idx;
                }
            }
            ptr[u] = p;
        }

        for (int t : touched_trips) {
            int start_idx = round_min[t];
            round_min[t] = UNSET;
            int end_idx = best_boarded[t];
            best_boarded[t] = start_idx;
            for (int j = start_idx; j < end_idx; ++j) {
                const auto& c = conns[j];
                if (c.to == tgt) {
                    if (!found || c.arr < ans) {
                        ans = c.arr;
                        found = true;
                    }
                }
                long long r = (transfer[c.to] >= INF - c.arr) ? INF : (c.arr + transfer[c.to]);
                if (r < ready[c.to]) {
                    ready[c.to] = r;
                    if (stamp[c.to] != round_id) {
                        stamp[c.to] = round_id;
                        next_marked.push_back(c.to);
                    }
                }
            }
        }

        touched_trips.clear();
        marked.swap(next_marked);
        next_marked.clear();
    }

    if (!found) {
        return std::nullopt;
    }
    return ans;
}

export function earliestArrival(
  connections: [number, number, number, number, number][],
  transfer: number[],
  source: number,
  target: number,
  start_time: number,
  max_boardings: number
): number | null {
  if (source === target) {
    return start_time;
  }
  const total = connections.length;
  if (max_boardings <= 0 || total === 0) {
    return null;
  }

  const n = transfer.length;
  const effMaxBoardings = max_boardings < n ? max_boardings : n;
  const INF = effMaxBoardings + 1;

  const cTrip = new Int32Array(total);
  const cFrom = new Int32Array(total);
  const cTo = new Int32Array(total);
  const cDep = new Float64Array(total);
  const cArr = new Float64Array(total);

  const tripMap = new Map<number, number>();
  let numTrips = 0;
  let m = 0;

  for (let i = 0; i < total; i++) {
    const c = connections[i];
    const dep = c[3];
    if (dep < start_time) {
      continue;
    }
    const tripId = c[0];
    let tIdx = tripMap.get(tripId);
    if (tIdx === undefined) {
      tIdx = numTrips++;
      tripMap.set(tripId, tIdx);
    }
    cTrip[m] = tIdx;
    cFrom[m] = c[1];
    cTo[m] = c[2];
    cDep[m] = dep;
    cArr[m] = c[4];
    m++;
  }

  if (m === 0) {
    return null;
  }

  const order = new Int32Array(m);
  for (let i = 0; i < m; i++) {
    order[i] = i;
  }
  const scratch = new Int32Array(m);

  const RUN = 32;
  for (let start = 0; start < m; start += RUN) {
    const end = start + RUN < m ? start + RUN : m;
    for (let i = start + 1; i < end; i++) {
      const key = order[i];
      const keyDep = cDep[key];
      let j = i - 1;
      while (j >= start && cDep[order[j]] > keyDep) {
        order[j + 1] = order[j];
        j--;
      }
      order[j + 1] = key;
    }
  }

  for (let width = RUN; width < m; width *= 2) {
    const step = width * 2;
    for (let left = 0; left < m; left += step) {
      const mid = left + width;
      if (mid >= m) {
        break;
      }
      const right = left + step < m ? left + step : m;
      if (cDep[order[mid - 1]] <= cDep[order[mid]]) {
        continue;
      }
      let i = left;
      let j = mid;
      let k = left;
      while (i < mid && j < right) {
        if (cDep[order[i]] <= cDep[order[j]]) {
          scratch[k++] = order[i++];
        } else {
          scratch[k++] = order[j++];
        }
      }
      while (i < mid) {
        scratch[k++] = order[i++];
      }
      while (j < right) {
        scratch[k++] = order[j++];
      }
      for (let p = left; p < right; p++) {
        order[p] = scratch[p];
      }
    }
  }

  const bestBoardings = new Int32Array(n);
  bestBoardings.fill(INF);
  const tripBoardings = new Int32Array(numTrips);
  tripBoardings.fill(INF);

  const heapCap = m + 1;
  const heapTime = new Float64Array(heapCap);
  const heapStation = new Int32Array(heapCap);
  const heapBoard = new Int32Array(heapCap);
  let heapSize = 0;

  function pushReady(t: number, s: number, b: number): void {
    let idx = heapSize++;
    while (idx > 0) {
      const parent = (idx - 1) >> 1;
      if (heapTime[parent] <= t) {
        break;
      }
      heapTime[idx] = heapTime[parent];
      heapStation[idx] = heapStation[parent];
      heapBoard[idx] = heapBoard[parent];
      idx = parent;
    }
    heapTime[idx] = t;
    heapStation[idx] = s;
    heapBoard[idx] = b;
  }

  function popReady(): void {
    const s = heapStation[0];
    const b = heapBoard[0];
    if (b < bestBoardings[s]) {
      bestBoardings[s] = b;
    }
    const last = --heapSize;
    if (last > 0) {
      const lt = heapTime[last];
      const ls = heapStation[last];
      const lb = heapBoard[last];
      let idx = 0;
      const half = last >> 1;
      while (idx < half) {
        let child = (idx << 1) + 1;
        const right = child + 1;
        if (right < last && heapTime[right] < heapTime[child]) {
          child = right;
        }
        if (lt <= heapTime[child]) {
          break;
        }
        heapTime[idx] = heapTime[child];
        heapStation[idx] = heapStation[child];
        heapBoard[idx] = heapBoard[child];
        idx = child;
      }
      heapTime[idx] = lt;
      heapStation[idx] = ls;
      heapBoard[idx] = lb;
    }
  }

  pushReady(start_time, source, 0);

  let minArr = Infinity;

  for (let p = 0; p < m; p++) {
    const idx = order[p];
    const dep = cDep[idx];
    if (dep >= minArr) {
      break;
    }

    while (heapSize > 0 && heapTime[0] <= dep) {
      popReady();
    }

    const t = cTrip[idx];
    const u = cFrom[idx];
    const bStay = tripBoardings[t];
    const bBoard = bestBoardings[u] + 1;
    const b = bStay < bBoard ? bStay : bBoard;

    if (b <= effMaxBoardings) {
      tripBoardings[t] = b;
      const v = cTo[idx];
      const arr = cArr[idx];
      if (v === target) {
        if (arr < minArr) {
          minArr = arr;
        }
      } else {
        const ready = arr + transfer[v];
        if (ready < minArr && b < bestBoardings[v]) {
          pushReady(ready, v, b);
        }
      }
    }
  }

  return minArr === Infinity ? null : minArr;
}

from collections import deque


def run_kiosk(levels, threshold, patience, arrivals):
    n = len(arrivals)
    for i in range(1, n):
        if arrivals[i][0] < arrivals[i - 1][0]:
            raise ValueError("arrivals must be non-decreasing in time")

    if n == 0:
        return []

    num_slots = len(levels)
    t0 = [0] * num_slots
    c0 = list(levels)
    ready = [0 if c >= threshold else threshold - c for c in levels]

    queue = deque()
    outcomes = []
    idx = 0
    t = arrivals[0][0]

    while True:
        # 1. Serve the queue
        while queue and min(ready) <= t:
            best_charge = threshold - 1
            best_slot = -1
            for k in range(num_slots):
                if ready[k] <= t:
                    ch = c0[k] + (t - t0[k])
                    if ch > 100:
                        ch = 100
                    if ch > best_charge:
                        best_charge = ch
                        best_slot = k
                        if ch == 100:
                            break
            _, drone, d_charge = queue.popleft()
            outcomes.append((drone, "SWAP", t, best_slot))
            t0[best_slot] = t
            c0[best_slot] = d_charge
            ready[best_slot] = t if d_charge >= threshold else t + (threshold - d_charge)

        # 2. Handle arrivals with this t, in list order
        while idx < n and arrivals[idx][0] == t:
            t_arr, drone, d_charge = arrivals[idx]
            idx += 1
            if not queue and min(ready) <= t:
                best_charge = threshold - 1
                best_slot = -1
                for k in range(num_slots):
                    if ready[k] <= t:
                        ch = c0[k] + (t - t0[k])
                        if ch > 100:
                            ch = 100
                        if ch > best_charge:
                            best_charge = ch
                            best_slot = k
                            if ch == 100:
                                break
                outcomes.append((drone, "SWAP", t, best_slot))
                t0[best_slot] = t
                c0[best_slot] = d_charge
                ready[best_slot] = t if d_charge >= threshold else t + (threshold - d_charge)
            else:
                queue.append((t_arr, drone, d_charge))

        # 3. Give up
        while queue and queue[0][0] + patience <= t:
            _, drone, _ = queue.popleft()
            outcomes.append((drone, "LEFT", t))

        # Jump to the next event time
        if not queue:
            if idx < n:
                t = arrivals[idx][0]
            else:
                break
        else:
            next_t = queue[0][0] + patience
            if idx < n and arrivals[idx][0] < next_t:
                next_t = arrivals[idx][0]
            earliest_ready = min(ready)
            if earliest_ready < next_t:
                next_t = earliest_ready
            t = next_t

    return outcomes

from collections import deque

_ACTIVE = 0
_WAITING = 1
_FINISHED = 2
_INF = float("inf")


class _Resource:
    __slots__ = (
        "s_holders",
        "x_holder",
        "waiting_s_holders",
        "q_head",
        "q_tail",
        "q_last_upg",
        "xq_head",
        "xq_tail",
        "xq_last_upg",
    )

    def __init__(self):
        self.s_holders = set()
        self.x_holder = None
        self.waiting_s_holders = set()
        self.q_head = None
        self.q_tail = None
        self.q_last_upg = None
        self.xq_head = None
        self.xq_tail = None
        self.xq_last_upg = None


def run_lock_manager(ops):
    logs = []
    resources = {}

    tx_state = {}
    tx_locks = {}
    tx_wait_res = {}
    tx_wait_mode = {}
    tx_is_upgrade = {}

    q_prev = {}
    q_next = {}
    xq_prev = {}
    xq_next = {}

    waiting_txs = set()
    topo = {}

    def q_append(robj, tx, mode):
        tail = robj.q_tail
        q_prev[tx] = tail
        q_next[tx] = None
        if tail is None:
            robj.q_head = robj.q_tail = tx
        else:
            q_next[tail] = tx
            robj.q_tail = tx

        if mode == "X":
            xtail = robj.xq_tail
            xq_prev[tx] = xtail
            xq_next[tx] = None
            if xtail is None:
                robj.xq_head = robj.xq_tail = tx
            else:
                xq_next[xtail] = tx
                robj.xq_tail = tx

    def q_insert_upgrade(robj, tx):
        last_u = robj.q_last_upg
        if last_u is None:
            head = robj.q_head
            q_prev[tx] = None
            q_next[tx] = head
            if head is None:
                robj.q_head = robj.q_tail = tx
            else:
                q_prev[head] = tx
                robj.q_head = tx
        else:
            nxt = q_next[last_u]
            q_prev[tx] = last_u
            q_next[tx] = nxt
            q_next[last_u] = tx
            if nxt is None:
                robj.q_tail = tx
            else:
                q_prev[nxt] = tx
        robj.q_last_upg = tx

        xlast_u = robj.xq_last_upg
        if xlast_u is None:
            xhead = robj.xq_head
            xq_prev[tx] = None
            xq_next[tx] = xhead
            if xhead is None:
                robj.xq_head = robj.xq_tail = tx
            else:
                xq_prev[xhead] = tx
                robj.xq_head = tx
        else:
            xnxt = xq_next[xlast_u]
            xq_prev[tx] = xlast_u
            xq_next[tx] = xnxt
            xq_next[xlast_u] = tx
            if xnxt is None:
                robj.xq_tail = tx
            else:
                xq_prev[xnxt] = tx
        robj.xq_last_upg = tx

    def q_remove(robj, tx):
        if robj.q_last_upg == tx:
            robj.q_last_upg = q_prev[tx]
        prv = q_prev.pop(tx)
        nxt = q_next.pop(tx)
        if prv is None:
            robj.q_head = nxt
        else:
            q_next[prv] = nxt
        if nxt is None:
            robj.q_tail = prv
        else:
            q_prev[nxt] = prv

        if tx_wait_mode[tx] == "X":
            if robj.xq_last_upg == tx:
                robj.xq_last_upg = xq_prev[tx]
            xprv = xq_prev.pop(tx)
            xnxt = xq_next.pop(tx)
            if xprv is None:
                robj.xq_head = xnxt
            else:
                xq_next[xprv] = xnxt
            if xnxt is None:
                robj.xq_tail = xprv
            else:
                xq_prev[xnxt] = xprv

    def release(tx, op_idx):
        locks = tx_locks[tx]
        affected = set(locks.keys())

        if tx_state[tx] == _WAITING:
            wres = tx_wait_res.pop(tx)
            affected.add(wres)
            q_remove(resources[wres], tx)
            tx_wait_mode.pop(tx)
            tx_is_upgrade.pop(tx)
            waiting_txs.discard(tx)
            topo.pop(tx, None)
            for r2, lmode in locks.items():
                if lmode == "S":
                    resources[r2].waiting_s_holders.discard(tx)

        for r2, lmode in locks.items():
            robj = resources[r2]
            if lmode == "X":
                robj.x_holder = None
            else:
                robj.s_holders.discard(tx)
        locks.clear()
        tx_state[tx] = _FINISHED

        for rname in sorted(affected):
            robj = resources[rname]
            while robj.q_head is not None:
                u = robj.q_head
                umode = tx_wait_mode[u]
                if umode == "S":
                    grantable = robj.x_holder is None
                elif tx_is_upgrade[u]:
                    grantable = robj.x_holder is None and len(robj.s_holders) == 1
                else:
                    grantable = robj.x_holder is None and not robj.s_holders

                if not grantable:
                    break

                q_remove(robj, u)
                tx_wait_res.pop(u)
                tx_wait_mode.pop(u)
                was_upg = tx_is_upgrade.pop(u)
                waiting_txs.discard(u)
                topo.pop(u, None)

                u_locks = tx_locks[u]
                for r2, lmode in u_locks.items():
                    if lmode == "S":
                        resources[r2].waiting_s_holders.discard(u)

                if was_upg:
                    robj.s_holders.discard(u)
                    robj.x_holder = u
                    u_locks[rname] = "X"
                else:
                    if umode == "S":
                        robj.s_holders.add(u)
                    else:
                        robj.x_holder = u
                    u_locks[rname] = umode

                tx_state[u] = _ACTIVE
                logs.append(("GRANT", op_idx, u, rname, umode))

    def iter_fwd_neighbors(w, skipped_fwd):
        wrobj = resources[tx_wait_res[w]]
        prv = q_prev[w]
        if prv is not None:
            yield prv
        xh = wrobj.x_holder
        if xh is not None and xh != w and tx_state[xh] == _WAITING:
            yield xh
        if tx_wait_mode[w] == "X":
            if wrobj not in skipped_fwd:
                found_w = False
                for h in wrobj.waiting_s_holders:
                    if h == w:
                        skipped_fwd[wrobj] = w
                        found_w = True
                    else:
                        yield h
                if not found_w:
                    skipped_fwd[wrobj] = None
            else:
                sk = skipped_fwd[wrobj]
                if sk is not None and sk != w:
                    skipped_fwd[wrobj] = None
                    yield sk

    def find_scc(t):
        fwd = set()
        fq = deque()
        skipped_fwd = {}

        for nxt in iter_fwd_neighbors(t, skipped_fwd):
            if nxt not in fwd:
                fwd.add(nxt)
                fq.append(nxt)

        while fq:
            w = fq.popleft()
            for nxt in iter_fwd_neighbors(w, skipped_fwd):
                if nxt not in fwd:
                    fwd.add(nxt)
                    if nxt != t:
                        fq.append(nxt)

        if t not in fwd:
            return set()

        bwd = {t}
        bq = deque([t])
        while bq:
            v = bq.popleft()
            nxt_q = q_next[v]
            if nxt_q is not None and nxt_q in fwd and nxt_q not in bwd:
                bwd.add(nxt_q)
                bq.append(nxt_q)
            for r2, lmode in tx_locks[v].items():
                r2obj = resources[r2]
                u = r2obj.q_head if lmode == "X" else r2obj.xq_head
                if u is not None and u != v and u in fwd and u not in bwd:
                    bwd.add(u)
                    bq.append(u)
        return bwd

    def relabel_all_topo():
        visited = set()
        post_order = []
        skipped_dfs = {}
        for start in waiting_txs:
            if start in visited:
                continue
            stack = [(start, False)]
            while stack:
                w, done = stack.pop()
                if done:
                    post_order.append(w)
                    continue
                if w in visited:
                    continue
                visited.add(w)
                stack.append((w, True))
                wrobj = resources[tx_wait_res[w]]
                nxt = q_prev[w]
                if nxt is not None and nxt not in visited:
                    stack.append((nxt, False))
                xh = wrobj.x_holder
                if xh is not None and xh != w and tx_state[xh] == _WAITING and xh not in visited:
                    stack.append((xh, False))
                if tx_wait_mode[w] == "X":
                    if wrobj not in skipped_dfs:
                        found_w = False
                        for h in wrobj.waiting_s_holders:
                            if h == w:
                                skipped_dfs[wrobj] = w
                                found_w = True
                            elif h not in visited:
                                stack.append((h, False))
                        if not found_w:
                            skipped_dfs[wrobj] = None
                    else:
                        sk = skipped_dfs[wrobj]
                        if sk is not None and sk != w:
                            skipped_dfs[wrobj] = None
                            if sk not in visited:
                                stack.append((sk, False))

        n = len(post_order)
        for idx_p, w in enumerate(post_order):
            topo[w] = float((n - idx_p) * 1024)

    def resolve_deadlocks(t, op_idx):
        while tx_state[t] == _WAITING:
            rname = tx_wait_res[t]
            robj = resources[rname]
            wmode = tx_wait_mode[t]
            is_upg = tx_is_upgrade[t]

            if is_upg and q_prev[t] is not None:
                scc = find_scc(t)
                victim = max(scc)
                logs.append(("ABORT", op_idx, victim))
                release(victim, op_idx)
                continue

            incoming_set = set()
            lo = -_INF
            for r2, lmode in tx_locks[t].items():
                if r2 == rname:
                    continue
                r2obj = resources[r2]
                u = r2obj.q_head if lmode == "X" else r2obj.xq_head
                if u is not None:
                    incoming_set.add(u)
                    tu = topo[u]
                    if tu > lo:
                        lo = tu
            if is_upg:
                u = q_next[t]
                if u is not None:
                    incoming_set.add(u)
                    tu = topo[u]
                    if tu > lo:
                        lo = tu

            outgoing = []
            hi = _INF
            prv = q_prev[t]
            if prv is not None:
                outgoing.append(prv)
                tp = topo[prv]
                if tp < hi:
                    hi = tp
            xh = robj.x_holder
            if xh is not None and xh != t and tx_state[xh] == _WAITING:
                outgoing.append(xh)
                txh = topo[xh]
                if txh < hi:
                    hi = txh
            if wmode == "X":
                for h in robj.waiting_s_holders:
                    if h != t:
                        outgoing.append(h)
                        th = topo[h]
                        if th < hi:
                            hi = th

            if lo < hi:
                if lo == -_INF and hi == _INF:
                    topo[t] = 0.0
                elif lo == -_INF:
                    val = hi - 1.0
                    if val >= hi:
                        relabel_all_topo()
                    else:
                        topo[t] = val
                elif hi == _INF:
                    val = lo + 1.0
                    if val <= lo:
                        relabel_all_topo()
                    else:
                        topo[t] = val
                else:
                    mid = (lo + hi) * 0.5
                    if mid <= lo or mid >= hi:
                        relabel_all_topo()
                    else:
                        topo[t] = mid
                break

            visited_f = []
            seen = set()
            hi_out = _INF
            fq = deque()
            skipped_fwd = {}
            cycle_found = False

            for v in outgoing:
                if v in incoming_set:
                    cycle_found = True
                    break
                tv = topo[v]
                if tv <= lo:
                    if v not in seen:
                        seen.add(v)
                        fq.append(v)
                elif tv < hi_out:
                    hi_out = tv

            while fq and not cycle_found:
                w = fq.popleft()
                visited_f.append(w)
                for nxt in iter_fwd_neighbors(w, skipped_fwd):
                    if nxt == t or nxt in incoming_set:
                        cycle_found = True
                        break
                    if nxt not in seen:
                        tn = topo[nxt]
                        if tn <= lo:
                            seen.add(nxt)
                            fq.append(nxt)
                        elif tn < hi_out:
                            hi_out = tn

            if cycle_found:
                scc = find_scc(t)
                victim = max(scc)
                logs.append(("ABORT", op_idx, victim))
                release(victim, op_idx)
                continue

            visited_f.sort(key=topo.__getitem__)
            k = 1 + len(visited_f)
            if hi_out == _INF:
                ok = True
                prev_val = lo
                val = lo + 1.0
                if val <= prev_val:
                    ok = False
                else:
                    topo[t] = val
                    prev_val = val
                    for w in visited_f:
                        val = prev_val + 1.0
                        if val <= prev_val:
                            ok = False
                            break
                        topo[w] = val
                        prev_val = val
                if not ok:
                    relabel_all_topo()
            else:
                step = (hi_out - lo) / (k + 1)
                ok = step > 0.0
                if ok:
                    vals = []
                    prev_val = lo
                    for idx_f in range(1, k + 1):
                        v_new = lo + step * idx_f
                        if v_new <= prev_val or v_new >= hi_out:
                            ok = False
                            break
                        vals.append(v_new)
                        prev_val = v_new
                    if ok:
                        topo[t] = vals[0]
                        for w, v_new in zip(visited_f, vals[1:]):
                            topo[w] = v_new
                if not ok:
                    relabel_all_topo()
            break

    for i, op in enumerate(ops):
        kind = op[0]
        tx = op[1]

        st = tx_state.get(tx)
        if st is None:
            tx_state[tx] = _ACTIVE
            tx_locks[tx] = {}
        elif st != _ACTIVE:
            logs.append(("IGNORED", i, tx))
            continue

        if kind == "COMMIT":
            logs.append(("COMMIT", i, tx))
            release(tx, i)
            continue

        res = op[2]
        robj = resources.get(res)
        if robj is None:
            robj = _Resource()
            resources[res] = robj

        locks = tx_locks[tx]
        held = locks.get(res)
        if held == "X" or (held == "S" and kind == "S"):
            logs.append(("HELD", i, tx, res))
            continue

        if held == "S":
            if robj.x_holder is None and len(robj.s_holders) == 1:
                robj.s_holders.remove(tx)
                robj.x_holder = tx
                locks[res] = "X"
                logs.append(("GRANT", i, tx, res, "X"))
                continue

            q_insert_upgrade(robj, tx)
            tx_state[tx] = _WAITING
            tx_wait_res[tx] = res
            tx_wait_mode[tx] = "X"
            tx_is_upgrade[tx] = True
            waiting_txs.add(tx)
            for r2, lmode in locks.items():
                if lmode == "S":
                    resources[r2].waiting_s_holders.add(tx)
            logs.append(("WAIT", i, tx, res, "X"))
            resolve_deadlocks(tx, i)
            continue

        if robj.q_head is None and robj.x_holder is None and (kind == "S" or not robj.s_holders):
            if kind == "S":
                robj.s_holders.add(tx)
            else:
                robj.x_holder = tx
            locks[res] = kind
            logs.append(("GRANT", i, tx, res, kind))
            continue

        q_append(robj, tx, kind)
        tx_state[tx] = _WAITING
        tx_wait_res[tx] = res
        tx_wait_mode[tx] = kind
        tx_is_upgrade[tx] = False
        waiting_txs.add(tx)
        for r2, lmode in locks.items():
            if lmode == "S":
                resources[r2].waiting_s_holders.add(tx)
        logs.append(("WAIT", i, tx, res, kind))
        resolve_deadlocks(tx, i)

    return logs

package main

import "errors"

type Tuple1 struct {
	F0 int
	F1 string
	F2 int
	F3 bool
}

type clientState struct {
	tokens   int
	lastTime int
	banUntil int
	strikes  []int
}

func AdmitRequests(requests []Tuple1, config map[string]int) ([]string, error) {
	for i := 1; i < len(requests); i++ {
		if requests[i].F0 < requests[i-1].F0 {
			return nil, errors.New("request timestamps must be non-decreasing")
		}
	}

	capVal := config["cap"]
	period := config["period"]
	gcap := config["gcap"]
	gperiod := config["gperiod"]
	reserve := config["reserve"]
	strikesLimit := config["strikes"]
	window := config["window"]
	banLen := config["ban"]

	globalTokens := gcap
	lastGlobalTime := 0

	clients := make(map[string]*clientState)
	results := make([]string, len(requests))

	for i, req := range requests {
		t := req.F0
		name := req.F1
		cost := req.F2
		vip := req.F3

		if t > lastGlobalTime {
			refills := t/gperiod - lastGlobalTime/gperiod
			if refills > 0 {
				if refills >= gcap-globalTokens {
					globalTokens = gcap
				} else {
					globalTokens += refills
				}
			}
			lastGlobalTime = t
		}

		c, exists := clients[name]
		if !exists {
			c = &clientState{
				tokens:   capVal,
				lastTime: t,
				banUntil: -1,
			}
			clients[name] = c
		} else if t > c.lastTime {
			refills := t/period - c.lastTime/period
			if refills > 0 {
				if refills >= capVal-c.tokens {
					c.tokens = capVal
				} else {
					c.tokens += refills
				}
			}
			c.lastTime = t
		}

		// Rule 1: banned
		if t < c.banUntil {
			results[i] = "BANNED"
			continue
		}

		// Rule 2: client bucket check
		if c.tokens < cost {
			cutoff := t - window
			drop := 0
			for drop < len(c.strikes) && c.strikes[drop] <= cutoff {
				drop++
			}
			if drop > 0 {
				c.strikes = c.strikes[drop:]
			}
			c.strikes = append(c.strikes, t)

			if len(c.strikes) >= strikesLimit {
				results[i] = "BAN"
				c.strikes = nil
				c.banUntil = t + banLen
			} else {
				results[i] = "DENY"
			}
			continue
		}

		// Rule 3: global bucket check
		if vip {
			if globalTokens < cost {
				results[i] = "BUSY"
				continue
			}
		} else {
			if globalTokens < cost || globalTokens-cost < reserve {
				results[i] = "BUSY"
				continue
			}
		}

		// Rule 4: admit request
		c.tokens -= cost
		globalTokens -= cost
		results[i] = "OK"
	}

	return results, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, String f1, long f2, boolean f3) {}

    private static final class ClientState {
        long tokens;
        long lastTime;
        long banUntil;
        final ArrayDeque<Long> strikes = new ArrayDeque<>();

        ClientState(long cap, long t) {
            this.tokens = cap;
            this.lastTime = t;
            this.banUntil = -1L;
        }
    }

    public static List<String> admitRequests(List<Tuple1> requests, Map<String, Long> config) {
        long prevT = 0L;
        for (Tuple1 req : requests) {
            long t = req.f0();
            if (t < prevT) {
                throw new IllegalArgumentException("Timestamps must be non-decreasing and >= 0");
            }
            prevT = t;
        }

        long cap = config.get("cap");
        long period = config.get("period");
        long gcap = config.get("gcap");
        long gperiod = config.get("gperiod");
        long reserve = config.get("reserve");
        long strikesLimit = config.get("strikes");
        long window = config.get("window");
        long ban = config.get("ban");

        long globalTokens = gcap;
        long lastGlobalTime = 0L;

        Map<String, ClientState> clients = new HashMap<>();
        List<String> result = new ArrayList<>(requests.size());

        for (Tuple1 req : requests) {
            long t = req.f0();
            String clientName = req.f1();
            long cost = req.f2();
            boolean vip = req.f3();

            if (t > lastGlobalTime) {
                long gAdd = t / gperiod - lastGlobalTime / gperiod;
                if (gAdd > 0) {
                    globalTokens += Math.min(gcap - globalTokens, gAdd);
                }
                lastGlobalTime = t;
            }

            ClientState client = clients.get(clientName);
            if (client == null) {
                client = new ClientState(cap, t);
                clients.put(clientName, client);
            } else if (t > client.lastTime) {
                long cAdd = t / period - client.lastTime / period;
                if (cAdd > 0) {
                    client.tokens += Math.min(cap - client.tokens, cAdd);
                }
                client.lastTime = t;
            }

            if (t < client.banUntil) {
                result.add("BANNED");
                continue;
            }

            if (client.tokens < cost) {
                long cutoff = t - window;
                while (!client.strikes.isEmpty() && client.strikes.peekFirst() <= cutoff) {
                    client.strikes.pollFirst();
                }
                client.strikes.addLast(t);
                if (client.strikes.size() >= strikesLimit) {
                    client.strikes.clear();
                    client.banUntil = t + ban;
                    result.add("BAN");
                } else {
                    result.add("DENY");
                }
                continue;
            }

            boolean globalOk = vip ? (globalTokens >= cost) : (globalTokens - reserve >= cost);
            if (!globalOk) {
                result.add("BUSY");
                continue;
            }

            client.tokens -= cost;
            globalTokens -= cost;
            result.add("OK");
        }

        return result;
    }
}

#include <algorithm>
#include <deque>
#include <map>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<std::string> admit_requests(
    const std::vector<std::tuple<long long, std::string, long long, bool>>& requests,
    const std::map<std::string, long long>& config) {
    for (std::size_t i = 1; i < requests.size(); ++i) {
        if (std::get<0>(requests[i]) < std::get<0>(requests[i - 1])) {
            throw std::invalid_argument("request timestamps must be non-decreasing");
        }
    }

    const long long cap = config.at("cap");
    const long long period = config.at("period");
    const long long gcap = config.at("gcap");
    const long long gperiod = config.at("gperiod");
    const long long reserve = config.at("reserve");
    const long long strikes_limit = config.at("strikes");
    const long long window = config.at("window");
    const long long ban_len = config.at("ban");

    struct ClientState {
        long long tokens;
        long long last_t;
        long long ban_until;
        std::deque<long long> strikes;
    };

    std::unordered_map<std::string_view, ClientState> clients;
    clients.reserve(std::min<std::size_t>(requests.size(), 8192));

    long long global_tokens = gcap;
    long long global_last_t = 0;

    std::vector<std::string> result;
    result.reserve(requests.size());

    for (const auto& req : requests) {
        const long long t = std::get<0>(req);
        const std::string_view client_name = std::get<1>(req);
        const long long cost = std::get<2>(req);
        const bool vip = std::get<3>(req);

        if (t > global_last_t) {
            const long long g_add = t / gperiod - global_last_t / gperiod;
            global_tokens += std::min(gcap - global_tokens, g_add);
            global_last_t = t;
        }

        auto [it, inserted] = clients.try_emplace(
            client_name, ClientState{cap, t, 0, {}});
        ClientState& client = it->second;

        if (!inserted && t > client.last_t) {
            const long long c_add = t / period - client.last_t / period;
            client.tokens += std::min(cap - client.tokens, c_add);
            client.last_t = t;
        }

        if (t < client.ban_until) {
            result.emplace_back("BANNED");
            continue;
        }

        if (client.tokens < cost) {
            client.strikes.push_back(t);
            const long long cutoff = t - window;
            while (!client.strikes.empty() && client.strikes.front() <= cutoff) {
                client.strikes.pop_front();
            }
            if (static_cast<long long>(client.strikes.size()) >= strikes_limit) {
                client.strikes.clear();
                client.ban_until = t + ban_len;
                result.emplace_back("BAN");
            } else {
                result.emplace_back("DENY");
            }
            continue;
        }

        const bool global_ok = vip
            ? (global_tokens >= cost)
            : (global_tokens >= reserve && global_tokens - reserve >= cost);

        if (!global_ok) {
            result.emplace_back("BUSY");
            continue;
        }

        client.tokens -= cost;
        global_tokens -= cost;
        result.emplace_back("OK");
    }

    return result;
}

type ClientState = {
  tokens: number;
  lastT: number;
  banUntil: number;
  strikes: number[];
  strikeHead: number;
};

export function admitRequests(
  requests: [number, string, number, boolean][],
  config: Record<string, number>,
): string[] {
  for (let i = 1; i < requests.length; i++) {
    if (requests[i][0] < requests[i - 1][0]) {
      throw new Error("Request timestamps must be non-decreasing");
    }
  }

  const cap = config["cap"];
  const period = config["period"];
  const gcap = config["gcap"];
  const gperiod = config["gperiod"];
  const reserve = config["reserve"];
  const maxStrikes = config["strikes"];
  const windowLen = config["window"];
  const banLen = config["ban"];

  const results: string[] = new Array(requests.length);
  const clients = new Map<string, ClientState>();

  let globalTokens = gcap;
  let lastGlobalT = 0;

  for (let i = 0; i < requests.length; i++) {
    const req = requests[i];
    const t = req[0];
    const clientName = req[1];
    const cost = req[2];
    const vip = req[3];

    if (t > lastGlobalT) {
      const globalRefills =
        Math.floor(t / gperiod) - Math.floor(lastGlobalT / gperiod);
      if (globalRefills > 0) {
        globalTokens = Math.min(gcap, globalTokens + globalRefills);
      }
      lastGlobalT = t;
    }

    let client = clients.get(clientName);
    if (client === undefined) {
      client = {
        tokens: cap,
        lastT: t,
        banUntil: -1,
        strikes: [],
        strikeHead: 0,
      };
      clients.set(clientName, client);
    } else if (t > client.lastT) {
      const clientRefills =
        Math.floor(t / period) - Math.floor(client.lastT / period);
      if (clientRefills > 0) {
        client.tokens = Math.min(cap, client.tokens + clientRefills);
      }
      client.lastT = t;
    }

    if (t < client.banUntil) {
      results[i] = "BANNED";
      continue;
    }

    if (client.tokens < cost) {
      const cutoff = t - windowLen;
      const strikes = client.strikes;
      let head = client.strikeHead;
      while (head < strikes.length && strikes[head] <= cutoff) {
        head++;
      }
      strikes.push(t);
      if (strikes.length - head >= maxStrikes) {
        strikes.length = 0;
        client.strikeHead = 0;
        client.banUntil = t + banLen;
        results[i] = "BAN";
      } else {
        if (head > 64 && head * 2 >= strikes.length) {
          client.strikes = strikes.slice(head);
          client.strikeHead = 0;
        } else {
          client.strikeHead = head;
        }
        results[i] = "DENY";
      }
      continue;
    }

    const globalOk = vip
      ? globalTokens >= cost
      : globalTokens - cost >= reserve;
    if (!globalOk) {
      results[i] = "BUSY";
      continue;
    }

    client.tokens -= cost;
    globalTokens -= cost;
    results[i] = "OK";
  }

  return results;
}

def simulate_vending(prices, stock, bank, events, timeout):
    prev_t = None
    for event in events:
        t = event[0]
        if prev_t is not None and t < prev_t:
            raise ValueError("Event timestamps must be non-decreasing")
        prev_t = t

    cur_stock = dict(stock)
    b5 = bank.get(5, 0)
    b10 = bank.get(10, 0)
    b25 = bank.get(25, 0)
    b100 = bank.get(100, 0)

    escrow = []
    escrow_total = 0
    last = 0
    log = []

    for t, kind, arg in events:
        if escrow and t >= last + timeout:
            log.append(("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True))))
            escrow.clear()
            escrow_total = 0

        if kind == "coin":
            v = arg
            if v not in (5, 10, 25, 100) or len(escrow) >= 10:
                log.append(("REJECT", t, v))
            else:
                escrow.append(v)
                escrow_total += v
                last = t

        elif kind == "select":
            s = arg
            last = t
            if s not in prices:
                log.append(("UNKNOWN", t, s))
            elif cur_stock[s] == 0:
                log.append(("SOLD_OUT", t, s))
            elif escrow_total < prices[s]:
                log.append(("NEED", t, prices[s] - escrow_total))
            else:
                tb5, tb10, tb25, tb100 = b5, b10, b25, b100
                for c in escrow:
                    if c == 5:
                        tb5 += 1
                    elif c == 10:
                        tb10 += 1
                    elif c == 25:
                        tb25 += 1
                    else:
                        tb100 += 1

                rem = escrow_total - prices[s]
                change = []

                if rem >= 100 and tb100 > 0:
                    k = min(tb100, rem // 100)
                    tb100 -= k
                    rem -= k * 100
                    change.extend([100] * k)
                if rem >= 25 and tb25 > 0:
                    k = min(tb25, rem // 25)
                    tb25 -= k
                    rem -= k * 25
                    change.extend([25] * k)
                if rem >= 10 and tb10 > 0:
                    k = min(tb10, rem // 10)
                    tb10 -= k
                    rem -= k * 10
                    change.extend([10] * k)
                if rem >= 5 and tb5 > 0:
                    k = min(tb5, rem // 5)
                    tb5 -= k
                    rem -= k * 5
                    change.extend([5] * k)

                if rem == 0:
                    b5, b10, b25, b100 = tb5, tb10, tb25, tb100
                    cur_stock[s] -= 1
                    escrow.clear()
                    escrow_total = 0
                    log.append(("VEND", t, s, tuple(change)))
                else:
                    log.append(("EXACT_ONLY", t, s))

        elif kind == "cancel":
            last = t
            if escrow:
                log.append(("RETURN", t, tuple(sorted(escrow, reverse=True))))
                escrow.clear()
                escrow_total = 0

    if escrow:
        log.append(("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True))))
        escrow.clear()

    return log, (b5, b10, b25, b100)

import re

_NAME_RE = re.compile(r"[a-z0-9_]+", re.ASCII)
_ACTION_WORD_RE = re.compile(r"[a-z]+", re.ASCII)
_SEG_RE = re.compile(r"[a-z0-9._-]+", re.ASCII)


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    parsed_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields

        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        if principal == "*":
            p_type = 0
            p_val = None
        elif principal.startswith("user:"):
            name = principal[5:]
            if _NAME_RE.fullmatch(name) is None:
                raise ValueError(f"rule {i}: bad principal {principal!r}")
            p_type = 2
            p_val = name
        elif principal.startswith("group:"):
            name = principal[6:]
            if _NAME_RE.fullmatch(name) is None:
                raise ValueError(f"rule {i}: bad principal {principal!r}")
            p_type = 1
            p_val = name
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")

        if action == "*":
            a_type = 0
            a_set = None
        else:
            parts = action.split(",")
            for part in parts:
                if _ACTION_WORD_RE.fullmatch(part) is None:
                    raise ValueError(f"rule {i}: bad action {action!r}")
            a_type = 1
            a_set = frozenset(parts)

        if not resource.startswith("/"):
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        if resource == "/":
            res_segs = []
        else:
            res_segs = resource[1:].split("/")
            for seg in res_segs:
                if seg != "*" and seg != "**" and _SEG_RE.fullmatch(seg) is None:
                    raise ValueError(f"rule {i}: bad resource {resource!r}")

        lit_count = 0
        min_len = 0
        collapsed = []
        for seg in res_segs:
            if seg == "**":
                if not collapsed or collapsed[-1] != "**":
                    collapsed.append(seg)
            else:
                min_len += 1
                if seg != "*":
                    lit_count += 1
                collapsed.append(seg)

        dstar_indices = [idx for idx, seg in enumerate(collapsed) if seg == "**"]
        if not dstar_indices:
            has_dstar = False
            prefix_checks = tuple(
                (idx, seg) for idx, seg in enumerate(collapsed) if seg != "*"
            )
            suffix_checks = ()
            prefix_len = 0
            suffix_len = 0
            chunks = ()
        else:
            has_dstar = True
            first_d = dstar_indices[0]
            last_d = dstar_indices[-1]
            prefix = collapsed[:first_d]
            suffix = collapsed[last_d + 1:]
            prefix_len = len(prefix)
            suffix_len = len(suffix)
            prefix_checks = tuple(
                (idx, seg) for idx, seg in enumerate(prefix) if seg != "*"
            )
            suffix_checks = tuple(
                (suffix_len - idx, seg) for idx, seg in enumerate(suffix) if seg != "*"
            )
            raw_chunks = []
            for k in range(len(dstar_indices) - 1):
                chunk = collapsed[dstar_indices[k] + 1 : dstar_indices[k + 1]]
                c_len = len(chunk)
                off0 = -1
                lit0 = None
                for off, seg in enumerate(chunk):
                    if seg != "*":
                        off0 = off
                        lit0 = seg
                        break
                if lit0 is not None:
                    extra = tuple(
                        (off, seg)
                        for off, seg in enumerate(chunk)
                        if seg != "*" and off != off0
                    )
                else:
                    extra = ()
                raw_chunks.append((c_len, off0, lit0, extra))
            chunks_list = []
            rem = 0
            for c_len, off0, lit0, extra in reversed(raw_chunks):
                rem += c_len
                chunks_list.append((c_len, off0, lit0, extra, rem))
            chunks_list.reverse()
            chunks = tuple(chunks_list)

        effect_rank = 0 if effect == "DENY" else 1
        sort_key = (-lit_count, -p_type, -a_type, effect_rank, i)
        decision = f"{effect} by rule {i}"
        parsed_rules.append((
            sort_key,
            p_type,
            p_val,
            a_type,
            a_set,
            has_dstar,
            min_len,
            prefix_len,
            suffix_len,
            prefix_checks,
            suffix_checks,
            chunks,
            decision,
        ))

    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req
        if not isinstance(user, str) or _NAME_RE.fullmatch(user) is None:
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list):
            raise ValueError(f"request {j}: bad groups")
        for g in groups:
            if not isinstance(g, str) or _NAME_RE.fullmatch(g) is None:
                raise ValueError(f"request {j}: bad groups")
        if not isinstance(action, str) or _ACTION_WORD_RE.fullmatch(action) is None:
            raise ValueError(f"request {j}: bad action {action!r}")
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError(f"request {j}: bad path {path!r}")
        if path == "/":
            path_segs = ()
        else:
            segs = path[1:].split("/")
            for seg in segs:
                if _SEG_RE.fullmatch(seg) is None:
                    raise ValueError(f"request {j}: bad path {path!r}")
            path_segs = tuple(segs)
        parsed_requests.append((user, frozenset(groups), action, path_segs, len(path_segs)))

    parsed_rules.sort(key=lambda r: r[0])
    compiled_rules = [r[1:] for r in parsed_rules]

    decisions = []
    for user, group_set, action, path_segs, n in parsed_requests:
        dec = "DENY by default"
        for (
            p_type,
            p_val,
            a_type,
            a_set,
            has_dstar,
            min_len,
            prefix_len,
            suffix_len,
            prefix_checks,
            suffix_checks,
            chunks,
            decision,
        ) in compiled_rules:
            if p_type == 2:
                if user != p_val:
                    continue
            elif p_type == 1:
                if p_val not in group_set:
                    continue

            if a_type == 1 and action not in a_set:
                continue

            if not has_dstar:
                if n != min_len:
                    continue
                matched = True
                for idx, lit in prefix_checks:
                    if path_segs[idx] != lit:
                        matched = False
                        break
                if not matched:
                    continue
            else:
                if n < min_len:
                    continue
                matched = True
                for idx, lit in prefix_checks:
                    if path_segs[idx] != lit:
                        matched = False
                        break
                if not matched:
                    continue
                for offset, lit in suffix_checks:
                    if path_segs[n - offset] != lit:
                        matched = False
                        break
                if not matched:
                    continue
                if chunks:
                    pos = prefix_len
                    mid_end = n - suffix_len
                    for c_len, off0, lit0, extra, min_rem in chunks:
                        if lit0 is None:
                            pos += c_len
                            continue
                        search_idx = pos + off0
                        limit = mid_end - min_rem + 1 + off0
                        found = False
                        while True:
                            try:
                                idx = path_segs.index(lit0, search_idx, limit)
                            except ValueError:
                                break
                            s = idx - off0
                            ok = True
                            for e_off, e_lit in extra:
                                if path_segs[s + e_off] != e_lit:
                                    ok = False
                                    break
                            if ok:
                                pos = s + c_len
                                found = True
                                break
                            search_idx = idx + 1
                        if not found:
                            matched = False
                            break
                    if not matched:
                        continue

            dec = decision
            break
        decisions.append(dec)

    return decisions

package main

import (
	"fmt"
	"strings"
)

type Tuple1 struct {
	F0 string
	F1 []string
	F2 string
	F3 string
}

type specificity struct {
	l int
	p int
	a int
}

func cmpSpecificity(x, y specificity) int {
	if x.l != y.l {
		if x.l < y.l {
			return -1
		}
		return 1
	}
	if x.p != y.p {
		if x.p < y.p {
			return -1
		}
		return 1
	}
	if x.a != y.a {
		if x.a < y.a {
			return -1
		}
		return 1
	}
	return 0
}

type parsedRule struct {
	isDeny        bool
	principalType int // 0 = "*", 1 = "group:", 2 = "user:"
	principalName string
	actionStar    bool
	actions       []string
	resourceSegs  []string
	spec          specificity
}

func isValidName(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func isValidActionWord(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') {
			return false
		}
	}
	return true
}

func isValidPathSeg(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-') {
			return false
		}
	}
	return true
}

func parseResource(s string) ([]string, int, bool) {
	if len(s) == 0 || s[0] != '/' {
		return nil, 0, false
	}
	if s == "/" {
		return nil, 0, true
	}
	segs := strings.Split(s[1:], "/")
	literals := 0
	for _, seg := range segs {
		if seg == "*" || seg == "**" {
			continue
		}
		if !isValidPathSeg(seg) {
			return nil, 0, false
		}
		literals++
	}
	return segs, literals, true
}

func parsePath(s string) ([]string, bool) {
	if len(s) == 0 || s[0] != '/' {
		return nil, false
	}
	if s == "/" {
		return nil, true
	}
	segs := strings.Split(s[1:], "/")
	for _, seg := range segs {
		if !isValidPathSeg(seg) {
			return nil, false
		}
	}
	return segs, true
}

func matchSegments(pat, path []string) bool {
	pi, si := 0, 0
	starIdx := -1
	matchIdx := 0

	for si < len(path) {
		if pi < len(pat) && pat[pi] != "**" && (pat[pi] == "*" || pat[pi] == path[si]) {
			pi++
			si++
		} else if pi < len(pat) && pat[pi] == "**" {
			starIdx = pi
			matchIdx = si
			pi++
		} else if starIdx != -1 {
			pi = starIdx + 1
			matchIdx++
			si = matchIdx
		} else {
			return false
		}
	}

	for pi < len(pat) && pat[pi] == "**" {
		pi++
	}
	return pi == len(pat)
}

func EvaluateAccess(rules []string, requests []Tuple1) ([]string, error) {
	parsedRules := make([]parsedRule, len(rules))
	for i, rule := range rules {
		fields := strings.Fields(rule)
		if len(fields) != 4 {
			return nil, fmt.Errorf("rule %d: expected 4 fields, got %d", i, len(fields))
		}
		effect, principal, action, resource := fields[0], fields[1], fields[2], fields[3]

		var isDeny bool
		switch effect {
		case "ALLOW":
			isDeny = false
		case "DENY":
			isDeny = true
		default:
			return nil, fmt.Errorf("rule %d: bad effect %q", i, effect)
		}

		var pType int
		var pName string
		if principal == "*" {
			pType = 0
		} else if strings.HasPrefix(principal, "user:") && isValidName(principal[5:]) {
			pType = 2
			pName = principal[5:]
		} else if strings.HasPrefix(principal, "group:") && isValidName(principal[6:]) {
			pType = 1
			pName = principal[6:]
		} else {
			return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
		}

		var actionStar bool
		var actions []string
		var aSpec int
		if action == "*" {
			actionStar = true
			aSpec = 0
		} else {
			parts := strings.Split(action, ",")
			for _, w := range parts {
				if !isValidActionWord(w) {
					return nil, fmt.Errorf("rule %d: bad action %q", i, action)
				}
			}
			actions = parts
			aSpec = 1
		}

		resSegs, lSpec, ok := parseResource(resource)
		if !ok {
			return nil, fmt.Errorf("rule %d: bad resource %q", i, resource)
		}

		parsedRules[i] = parsedRule{
			isDeny:        isDeny,
			principalType: pType,
			principalName: pName,
			actionStar:    actionStar,
			actions:       actions,
			resourceSegs:  resSegs,
			spec:          specificity{l: lSpec, p: pType, a: aSpec},
		}
	}

	parsedPaths := make([][]string, len(requests))
	for j, req := range requests {
		if !isValidName(req.F0) {
			return nil, fmt.Errorf("request %d: bad user %q", j, req.F0)
		}
		for _, g := range req.F1 {
			if !isValidName(g) {
				return nil, fmt.Errorf("request %d: bad groups", j)
			}
		}
		if !isValidActionWord(req.F2) {
			return nil, fmt.Errorf("request %d: bad action %q", j, req.F2)
		}
		pathSegs, ok := parsePath(req.F3)
		if !ok {
			return nil, fmt.Errorf("request %d: bad path %q", j, req.F3)
		}
		parsedPaths[j] = pathSegs
	}

	decisions := make([]string, len(requests))
	for j, req := range requests {
		user := req.F0
		groups := req.F1
		action := req.F2
		pathSegs := parsedPaths[j]

		var groupSet map[string]struct{}
		if len(groups) > 8 {
			groupSet = make(map[string]struct{}, len(groups))
			for _, g := range groups {
				groupSet[g] = struct{}{}
			}
		}

		hasBest := false
		var bestSpec specificity
		bestDeny := false
		bestIdx := -1

		for i := range parsedRules {
			r := &parsedRules[i]
			if hasBest {
				c := cmpSpecificity(r.spec, bestSpec)
				if c < 0 {
					continue
				}
				if c == 0 && (bestDeny || !r.isDeny) {
					continue
				}
			}

			switch r.principalType {
			case 2:
				if r.principalName != user {
					continue
				}
			case 1:
				found := false
				if groupSet != nil {
					_, found = groupSet[r.principalName]
				} else {
					for _, g := range groups {
						if g == r.principalName {
							found = true
							break
						}
					}
				}
				if !found {
					continue
				}
			}

			if !r.actionStar {
				found := false
				for _, a := range r.actions {
					if a == action {
						found = true
						break
					}
				}
				if !found {
					continue
				}
			}

			if !matchSegments(r.resourceSegs, pathSegs) {
				continue
			}

			hasBest = true
			bestSpec = r.spec
			bestDeny = r.isDeny
			bestIdx = i
		}

		if !hasBest {
			decisions[j] = "DENY by default"
		} else if bestDeny {
			decisions[j] = fmt.Sprintf("DENY by rule %d", bestIdx)
		} else {
			decisions[j] = fmt.Sprintf("ALLOW by rule %d", bestIdx)
		}
	}

	return decisions, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, List<String> f1, String f2, String f3) {}

    private static final int PRINCIPAL_ANY = 0;
    private static final int PRINCIPAL_GROUP = 1;
    private static final int PRINCIPAL_USER = 2;

    private static final class ParsedRule {
        final boolean isDeny;
        final int principalType;
        final String principalName; // null if PRINCIPAL_ANY
        final Set<String> actions;  // null if "*"
        final String[] resourceSegs;
        final int minPathLength;
        final boolean hasStarStar;
        final long specificity;

        ParsedRule(
                boolean isDeny,
                int principalType,
                String principalName,
                Set<String> actions,
                String[] resourceSegs,
                int minPathLength,
                boolean hasStarStar,
                int literalCount) {
            this.isDeny = isDeny;
            this.principalType = principalType;
            this.principalName = principalName;
            this.actions = actions;
            this.resourceSegs = resourceSegs;
            this.minPathLength = minPathLength;
            this.hasStarStar = hasStarStar;
            int actionSpec = (actions == null) ? 0 : 1;
            this.specificity = ((long) literalCount << 3) | ((long) principalType << 1) | actionSpec;
        }
    }

    private static final class ParsedRequest {
        final String user;
        final Set<String> groupSet;
        final List<String> groupList;
        final String action;
        final String[] pathSegs;

        ParsedRequest(String user, List<String> groups, String action, String[] pathSegs) {
            this.user = user;
            this.groupList = groups;
            this.groupSet = groups.size() > 4 ? new HashSet<>(groups) : null;
            this.action = action;
            this.pathSegs = pathSegs;
        }

        boolean hasGroup(String group) {
            if (groupSet != null) {
                return groupSet.contains(group);
            }
            return groupList.contains(group);
        }
    }

    public static List<String> evaluateAccess(List<String> rules, List<Tuple1> requests) {
        if (rules == null) {
            throw new IllegalArgumentException("rules must be a list");
        }
        if (requests == null) {
            throw new IllegalArgumentException("requests must be a list");
        }

        List<ParsedRule> parsedRules = new ArrayList<>(rules.size());
        for (int i = 0; i < rules.size(); i++) {
            String raw = rules.get(i);
            if (raw == null) {
                throw new IllegalArgumentException("rule " + i + ": not a str");
            }
            List<String> fields = splitWhitespace(raw);
            if (fields.size() != 4) {
                throw new IllegalArgumentException("rule " + i + ": expected 4 fields, got " + fields.size());
            }

            String effect = fields.get(0);
            boolean isDeny;
            if ("ALLOW".equals(effect)) {
                isDeny = false;
            } else if ("DENY".equals(effect)) {
                isDeny = true;
            } else {
                throw new IllegalArgumentException("rule " + i + ": bad effect " + effect);
            }

            String principal = fields.get(1);
            int principalType;
            String principalName = null;
            if ("*".equals(principal)) {
                principalType = PRINCIPAL_ANY;
            } else if (principal.startsWith("user:")) {
                String name = principal.substring(5);
                if (!isName(name)) {
                    throw new IllegalArgumentException("rule " + i + ": bad principal " + principal);
                }
                principalType = PRINCIPAL_USER;
                principalName = name;
            } else if (principal.startsWith("group:")) {
                String name = principal.substring(6);
                if (!isName(name)) {
                    throw new IllegalArgumentException("rule " + i + ": bad principal " + principal);
                }
                principalType = PRINCIPAL_GROUP;
                principalName = name;
            } else {
                throw new IllegalArgumentException("rule " + i + ": bad principal " + principal);
            }

            String actionField = fields.get(2);
            Set<String> actions = null;
            if (!"*".equals(actionField)) {
                String[] parts = actionField.split(",", -1);
                if (parts.length == 0) {
                    throw new IllegalArgumentException("rule " + i + ": bad action " + actionField);
                }
                actions = new HashSet<>(parts.length * 2);
                for (String part : parts) {
                    if (!isActionWord(part)) {
                        throw new IllegalArgumentException("rule " + i + ": bad action " + actionField);
                    }
                    actions.add(part);
                }
            }

            String resource = fields.get(3);
            String[] resourceSegs = parseSegments(resource, true, "rule " + i + ": bad resource " + resource);
            int literalCount = 0;
            int minPathLength = 0;
            boolean hasStarStar = false;
            for (String seg : resourceSegs) {
                if ("**".equals(seg)) {
                    hasStarStar = true;
                } else if ("*".equals(seg)) {
                    minPathLength++;
                } else {
                    literalCount++;
                    minPathLength++;
                }
            }

            parsedRules.add(new ParsedRule(
                    isDeny,
                    principalType,
                    principalName,
                    actions,
                    resourceSegs,
                    minPathLength,
                    hasStarStar,
                    literalCount));
        }

        List<ParsedRequest> parsedRequests = new ArrayList<>(requests.size());
        for (int j = 0; j < requests.size(); j++) {
            Tuple1 req = requests.get(j);
            if (req == null) {
                throw new IllegalArgumentException("request " + j + ": expected 4-tuple");
            }
            String user = req.f0();
            if (!isName(user)) {
                throw new IllegalArgumentException("request " + j + ": bad user " + user);
            }
            List<String> groups = req.f1();
            if (groups == null) {
                throw new IllegalArgumentException("request " + j + ": bad groups");
            }
            for (String g : groups) {
                if (!isName(g)) {
                    throw new IllegalArgumentException("request " + j + ": bad groups");
                }
            }
            String action = req.f2();
            if (!isActionWord(action)) {
                throw new IllegalArgumentException("request " + j + ": bad action " + action);
            }
            String path = req.f3();
            String[] pathSegs = parseSegments(path, false, "request " + j + ": bad path " + path);
            parsedRequests.add(new ParsedRequest(user, groups, action, pathSegs));
        }

        List<String> results = new ArrayList<>(parsedRequests.size());
        for (ParsedRequest req : parsedRequests) {
            long bestSpec = -1L;
            boolean bestIsDeny = false;
            int bestRuleIdx = -1;

            for (int i = 0; i < parsedRules.size(); i++) {
                ParsedRule rule = parsedRules.get(i);
                if (rule.principalType == PRINCIPAL_USER) {
                    if (!rule.principalName.equals(req.user)) {
                        continue;
                    }
                } else if (rule.principalType == PRINCIPAL_GROUP) {
                    if (!req.hasGroup(rule.principalName)) {
                        continue;
                    }
                }

                if (rule.actions != null && !rule.actions.contains(req.action)) {
                    continue;
                }

                if (rule.hasStarStar) {
                    if (req.pathSegs.length < rule.minPathLength) {
                        continue;
                    }
                } else if (req.pathSegs.length != rule.minPathLength) {
                    continue;
                }

                if (!matchResource(rule.resourceSegs, req.pathSegs)) {
                    continue;
                }

                if (rule.specificity > bestSpec) {
                    bestSpec = rule.specificity;
                    bestIsDeny = rule.isDeny;
                    bestRuleIdx = i;
                } else if (rule.specificity == bestSpec) {
                    if (!bestIsDeny && rule.isDeny) {
                        bestIsDeny = true;
                        bestRuleIdx = i;
                    }
                }
            }

            if (bestRuleIdx == -1) {
                results.add("DENY by default");
            } else if (bestIsDeny) {
                results.add("DENY by rule " + bestRuleIdx);
            } else {
                results.add("ALLOW by rule " + bestRuleIdx);
            }
        }

        return results;
    }

    private static List<String> splitWhitespace(String s) {
        List<String> fields = new ArrayList<>();
        int n = s.length();
        int i = 0;
        while (i < n) {
            while (i < n && Character.isWhitespace(s.charAt(i))) {
                i++;
            }
            if (i >= n) {
                break;
            }
            int start = i;
            while (i < n && !Character.isWhitespace(s.charAt(i))) {
                i++;
            }
            fields.add(s.substring(start, i));
        }
        return fields;
    }

    private static boolean isName(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
                return false;
            }
        }
        return true;
    }

    private static boolean isActionWord(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < 'a' || c > 'z') {
                return false;
            }
        }
        return true;
    }

    private static boolean isLiteralSegment(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')) {
                return false;
            }
        }
        return true;
    }

    private static String[] parseSegments(String s, boolean allowWildcards, String errMsg) {
        if (s == null || s.isEmpty() || s.charAt(0) != '/') {
            throw new IllegalArgumentException(errMsg);
        }
        if (s.length() == 1) {
            return new String[0];
        }
        if (s.charAt(s.length() - 1) == '/') {
            throw new IllegalArgumentException(errMsg);
        }
        List<String> segs = new ArrayList<>();
        int start = 1;
        int n = s.length();
        for (int i = 1; i <= n; i++) {
            if (i == n || s.charAt(i) == '/') {
                String seg = s.substring(start, i);
                if (seg.isEmpty()) {
                    throw new IllegalArgumentException(errMsg);
                }
                if (allowWildcards && ("*".equals(seg) || "**".equals(seg))) {
                    segs.add(seg);
                } else if (isLiteralSegment(seg)) {
                    segs.add(seg);
                } else {
                    throw new IllegalArgumentException(errMsg);
                }
                start = i + 1;
            }
        }
        return segs.toArray(new String[0]);
    }

    private static boolean matchResource(String[] res, String[] path) {
        int r = 0;
        int p = 0;
        int rStar = -1;
        int pStar = -1;
        while (p < path.length) {
            if (r < res.length && ("*".equals(res[r]) || res[r].equals(path[p]))) {
                r++;
                p++;
            } else if (r < res.length && "**".equals(res[r])) {
                rStar = r;
                pStar = p;
                r++;
            } else if (rStar != -1) {
                r = rStar + 1;
                pStar++;
                p = pStar;
            } else {
                return false;
            }
        }
        while (r < res.length && "**".equals(res[r])) {
            r++;
        }
        return r == res.length;
    }
}

#include <algorithm>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <unordered_map>
#include <utility>
#include <vector>

namespace {

bool is_ascii_ws(char ch) {
    return ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' || ch == '\v' || ch == '\f';
}

std::vector<std::string_view> split_ws(std::string_view s) {
    std::vector<std::string_view> fields;
    std::size_t i = 0;
    const std::size_t n = s.size();
    while (i < n) {
        while (i < n && is_ascii_ws(s[i])) {
            ++i;
        }
        if (i == n) {
            break;
        }
        std::size_t j = i;
        while (j < n && !is_ascii_ws(s[j])) {
            ++j;
        }
        fields.push_back(s.substr(i, j - i));
        i = j;
    }
    return fields;
}

bool is_valid_name(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (unsigned char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
            return false;
        }
    }
    return true;
}

bool is_valid_action_word(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (unsigned char c : s) {
        if (!(c >= 'a' && c <= 'z')) {
            return false;
        }
    }
    return true;
}

bool is_valid_path_seg(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (unsigned char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')) {
            return false;
        }
    }
    return true;
}

struct ParsedRule {
    int orig_index = 0;
    bool is_deny = false;
    int L = 0;
    int P = 0; // 0 = *, 1 = group, 2 = user
    int A = 0; // 0 = *, 1 = list
    std::string principal_name;
    std::vector<std::string> actions;
    std::vector<int> seg_ids; // -1 = "*", -2 = "**", >= 0 = literal ID
};

bool two_pointer_match(const std::vector<int>& rule_segs, const std::vector<int>& path_ids) {
    const std::size_t R = rule_segs.size();
    const std::size_t P = path_ids.size();
    std::size_t ri = 0;
    std::size_t pi = 0;
    std::size_t star_ri = static_cast<std::size_t>(-1);
    std::size_t star_pi = 0;

    while (pi < P) {
        if (ri < R && (rule_segs[ri] == -1 || rule_segs[ri] == path_ids[pi])) {
            ++ri;
            ++pi;
        } else if (ri < R && rule_segs[ri] == -2) {
            star_ri = ri;
            star_pi = pi;
            ++ri;
        } else if (star_ri != static_cast<std::size_t>(-1)) {
            ri = star_ri + 1;
            ++star_pi;
            pi = star_pi;
        } else {
            return false;
        }
    }

    while (ri < R && rule_segs[ri] == -2) {
        ++ri;
    }
    return ri == R;
}

bool bitset_match(const std::vector<int>& rule_segs, std::size_t P, const std::vector<std::uint64_t>& seg_masks) {
    const std::uint64_t valid_mask = (~0ULL) >> (63 - P);
    std::uint64_t dp = 1ULL;
    for (int s : rule_segs) {
        if (s == -2) {
            std::uint64_t lsb = dp & (~dp + 1ULL);
            dp = (~(lsb - 1ULL)) & valid_mask;
        } else if (s == -1) {
            dp = (dp << 1) & valid_mask;
        } else {
            dp = (dp << 1) & seg_masks[static_cast<std::size_t>(s)];
        }
        if (dp == 0ULL) {
            return false;
        }
    }
    return ((dp >> P) & 1ULL) != 0ULL;
}

} // namespace

std::vector<std::string> evaluate_access(
    const std::vector<std::string>& rules,
    const std::vector<std::tuple<std::string, std::vector<std::string>, std::string, std::string>>& requests) {

    std::unordered_map<std::string, int> seg_dict;
    int next_seg_id = 0;
    auto intern_seg = [&](std::string_view sv) -> int {
        std::string key(sv);
        auto [it, inserted] = seg_dict.emplace(std::move(key), next_seg_id);
        if (inserted) {
            ++next_seg_id;
        }
        return it->second;
    };

    std::vector<ParsedRule> parsed_rules;
    parsed_rules.reserve(rules.size());

    // 1. Validate and parse all rules
    for (std::size_t i = 0; i < rules.size(); ++i) {
        std::vector<std::string_view> fields = split_ws(rules[i]);
        if (fields.size() != 4) {
            throw std::invalid_argument("rule " + std::to_string(i) + ": expected 4 fields, got " +
                                        std::to_string(fields.size()));
        }

        ParsedRule pr;
        pr.orig_index = static_cast<int>(i);

        // EFFECT
        if (fields[0] == "ALLOW") {
            pr.is_deny = false;
        } else if (fields[0] == "DENY") {
            pr.is_deny = true;
        } else {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad effect");
        }

        // PRINCIPAL
        std::string_view p_sv = fields[1];
        if (p_sv == "*") {
            pr.P = 0;
        } else if (p_sv.size() > 5 && p_sv.substr(0, 5) == "user:" && is_valid_name(p_sv.substr(5))) {
            pr.P = 2;
            pr.principal_name = std::string(p_sv.substr(5));
        } else if (p_sv.size() > 6 && p_sv.substr(0, 6) == "group:" && is_valid_name(p_sv.substr(6))) {
            pr.P = 1;
            pr.principal_name = std::string(p_sv.substr(6));
        } else {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad principal");
        }

        // ACTION
        std::string_view a_sv = fields[2];
        if (a_sv == "*") {
            pr.A = 0;
        } else {
            pr.A = 1;
            std::size_t pos = 0;
            while (true) {
                std::size_t comma = a_sv.find(',', pos);
                std::string_view word = (comma == std::string_view::npos) ? a_sv.substr(pos) : a_sv.substr(pos, comma - pos);
                if (!is_valid_action_word(word)) {
                    throw std::invalid_argument("rule " + std::to_string(i) + ": bad action");
                }
                pr.actions.emplace_back(word);
                if (comma == std::string_view::npos) {
                    break;
                }
                pos = comma + 1;
            }
            std::sort(pr.actions.begin(), pr.actions.end());
            pr.actions.erase(std::unique(pr.actions.begin(), pr.actions.end()), pr.actions.end());
        }

        // RESOURCE
        std::string_view r_sv = fields[3];
        if (r_sv.empty() || r_sv[0] != '/') {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad resource");
        }
        if (r_sv.size() > 1) {
            std::size_t pos = 1;
            while (true) {
                std::size_t slash = r_sv.find('/', pos);
                std::string_view seg = (slash == std::string_view::npos) ? r_sv.substr(pos) : r_sv.substr(pos, slash - pos);
                if (seg.empty()) {
                    throw std::invalid_argument("rule " + std::to_string(i) + ": bad resource");
                }
                if (seg == "*") {
                    pr.seg_ids.push_back(-1);
                } else if (seg == "**") {
                    pr.seg_ids.push_back(-2);
                } else if (is_valid_path_seg(seg)) {
                    pr.seg_ids.push_back(intern_seg(seg));
                    ++pr.L;
                } else {
                    throw std::invalid_argument("rule " + std::to_string(i) + ": bad resource");
                }
                if (slash == std::string_view::npos) {
                    break;
                }
                pos = slash + 1;
            }
        }

        parsed_rules.push_back(std::move(pr));
    }

    // 2. Validate all requests and extract path segments
    struct ParsedRequestPath {
        std::vector<int> path_ids;
    };
    std::vector<ParsedRequestPath> parsed_paths;
    parsed_paths.reserve(requests.size());

    for (std::size_t j = 0; j < requests.size(); ++j) {
        const auto& [user, groups, action, path] = requests[j];
        if (!is_valid_name(user)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad user");
        }
        for (const auto& g : groups) {
            if (!is_valid_name(g)) {
                throw std::invalid_argument("request " + std::to_string(j) + ": bad groups");
            }
        }
        if (!is_valid_action_word(action)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad action");
        }
        if (path.empty() || path[0] != '/') {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad path");
        }

        ParsedRequestPath prp;
        if (path.size() > 1) {
            std::string_view p_sv(path);
            std::size_t pos = 1;
            while (true) {
                std::size_t slash = p_sv.find('/', pos);
                std::string_view seg = (slash == std::string_view::npos) ? p_sv.substr(pos) : p_sv.substr(pos, slash - pos);
                if (!is_valid_path_seg(seg)) {
                    throw std::invalid_argument("request " + std::to_string(j) + ": bad path");
                }
                auto it = seg_dict.find(std::string(seg));
                prp.path_ids.push_back(it != seg_dict.end() ? it->second : -3);
                if (slash == std::string_view::npos) {
                    break;
                }
                pos = slash + 1;
            }
        }
        parsed_paths.push_back(std::move(prp));
    }

    // 3. Sort rules by priority: (L, P, A) desc, DENY before ALLOW, orig_index asc
    std::sort(parsed_rules.begin(), parsed_rules.end(), [](const ParsedRule& a, const ParsedRule& b) {
        if (a.L != b.L) return a.L > b.L;
        if (a.P != b.P) return a.P > b.P;
        if (a.A != b.A) return a.A > b.A;
        if (a.is_deny != b.is_deny) return a.is_deny > b.is_deny;
        return a.orig_index < b.orig_index;
    });

    // 4. Evaluate requests
    std::vector<std::string> results;
    results.reserve(requests.size());

    std::vector<std::uint64_t> seg_masks(static_cast<std::size_t>(next_seg_id), 0ULL);
    std::vector<std::string_view> sorted_groups;

    for (std::size_t j = 0; j < requests.size(); ++j) {
        const auto& [user, groups, action, path] = requests[j];
        const auto& path_ids = parsed_paths[j].path_ids;
        const std::size_t P = path_ids.size();

        sorted_groups.clear();
        sorted_groups.reserve(groups.size());
        for (const auto& g : groups) {
            sorted_groups.emplace_back(g);
        }
        std::sort(sorted_groups.begin(), sorted_groups.end());

        const bool use_bitset = (P <= 63);
        if (use_bitset) {
            for (std::size_t k = 0; k < P; ++k) {
                int id = path_ids[k];
                if (id >= 0) {
                    seg_masks[static_cast<std::size_t>(id)] |= (1ULL << (k + 1));
                }
            }
        }

        const ParsedRule* winner = nullptr;
        for (const auto& rule : parsed_rules) {
            // Check PRINCIPAL
            if (rule.P == 2) {
                if (rule.principal_name != user) {
                    continue;
                }
            } else if (rule.P == 1) {
                if (!std::binary_search(sorted_groups.begin(), sorted_groups.end(), std::string_view(rule.principal_name))) {
                    continue;
                }
            }

            // Check ACTION
            if (rule.A == 1) {
                if (!std::binary_search(rule.actions.begin(), rule.actions.end(), action)) {
                    continue;
                }
            }

            // Check RESOURCE
            bool matched = use_bitset ? bitset_match(rule.seg_ids, P, seg_masks)
                                      : two_pointer_match(rule.seg_ids, path_ids);
            if (matched) {
                winner = &rule;
                break;
            }
        }

        if (use_bitset) {
            for (std::size_t k = 0; k < P; ++k) {
                int id = path_ids[k];
                if (id >= 0) {
                    seg_masks[static_cast<std::size_t>(id)] = 0ULL;
                }
            }
        }

        if (winner == nullptr) {
            results.emplace_back("DENY by default");
        } else if (winner->is_deny) {
            results.push_back("DENY by rule " + std::to_string(winner->orig_index));
        } else {
            results.push_back("ALLOW by rule " + std::to_string(winner->orig_index));
        }
    }

    return results;
}

type Effect = "ALLOW" | "DENY";

interface ParsedRule {
  effect: Effect;
  principalType: 0 | 1 | 2;
  principalName: string;
  actionAll: boolean;
  actions: Set<string> | null;
  segments: string[];
  minSegs: number;
  specL: number;
  specP: 0 | 1 | 2;
  specA: 0 | 1;
}

interface ParsedRequest {
  user: string;
  groups: Set<string>;
  action: string;
  pathSegments: string[];
}

const NAME_RE = /^[a-z0-9_]+$/;
const ACTION_WORD_RE = /^[a-z]+$/;
const LITERAL_SEG_RE = /^[a-z0-9._-]+$/;

function parseResource(resource: string): {
  segments: string[];
  minSegs: number;
  specL: number;
} | null {
  if (resource === "/") {
    return { segments: [], minSegs: 0, specL: 0 };
  }
  if (!resource.startsWith("/")) {
    return null;
  }
  const raw = resource.slice(1).split("/");
  const segments: string[] = [];
  let minSegs = 0;
  let specL = 0;

  for (const seg of raw) {
    if (seg === "*") {
      segments.push(seg);
      minSegs++;
    } else if (seg === "**") {
      if (segments.length === 0 || segments[segments.length - 1] !== "**") {
        segments.push(seg);
      }
    } else if (LITERAL_SEG_RE.test(seg)) {
      segments.push(seg);
      minSegs++;
      specL++;
    } else {
      return null;
    }
  }

  return { segments, minSegs, specL };
}

function parsePath(path: string): string[] | null {
  if (path === "/") {
    return [];
  }
  if (!path.startsWith("/")) {
    return null;
  }
  const segments = path.slice(1).split("/");
  for (const seg of segments) {
    if (!LITERAL_SEG_RE.test(seg)) {
      return null;
    }
  }
  return segments;
}

function matchPath(pattern: string[], path: string[]): boolean {
  const m = pattern.length;
  const n = path.length;
  let pi = 0;
  let si = 0;
  let starPi = -1;
  let starSi = 0;

  while (si < n) {
    if (pi < m && (pattern[pi] === "*" || pattern[pi] === path[si])) {
      pi++;
      si++;
    } else if (pi < m && pattern[pi] === "**") {
      starPi = pi;
      starSi = si;
      pi++;
    } else if (starPi !== -1) {
      starSi++;
      si = starSi;
      pi = starPi + 1;
    } else {
      return false;
    }
  }

  while (pi < m && pattern[pi] === "**") {
    pi++;
  }

  return pi === m;
}

export function evaluateAccess(
  rules: string[],
  requests: [string, string[], string, string][]
): string[] {
  if (!Array.isArray(rules)) {
    throw new Error("rules must be a list");
  }
  if (!Array.isArray(requests)) {
    throw new Error("requests must be a list");
  }

  const parsedRules: ParsedRule[] = new Array(rules.length);

  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (typeof rule !== "string") {
      throw new Error(`rule ${i}: not a str`);
    }

    const trimmed = rule.trim();
    const fields = trimmed === "" ? [] : trimmed.split(/\s+/);
    if (fields.length !== 4) {
      throw new Error(`rule ${i}: expected 4 fields, got ${fields.length}`);
    }

    const [effectStr, principalStr, actionStr, resourceStr] = fields;

    if (effectStr !== "ALLOW" && effectStr !== "DENY") {
      throw new Error(`rule ${i}: bad effect '${effectStr}'`);
    }
    const effect: Effect = effectStr;

    let principalType: 0 | 1 | 2;
    let principalName = "";
    if (principalStr === "*") {
      principalType = 0;
    } else if (principalStr.startsWith("user:")) {
      const name = principalStr.slice(5);
      if (!NAME_RE.test(name)) {
        throw new Error(`rule ${i}: bad principal '${principalStr}'`);
      }
      principalType = 2;
      principalName = name;
    } else if (principalStr.startsWith("group:")) {
      const name = principalStr.slice(6);
      if (!NAME_RE.test(name)) {
        throw new Error(`rule ${i}: bad principal '${principalStr}'`);
      }
      principalType = 1;
      principalName = name;
    } else {
      throw new Error(`rule ${i}: bad principal '${principalStr}'`);
    }

    let actionAll = false;
    let actions: Set<string> | null = null;
    if (actionStr === "*") {
      actionAll = true;
    } else {
      const parts = actionStr.split(",");
      const set = new Set<string>();
      for (const word of parts) {
        if (!ACTION_WORD_RE.test(word)) {
          throw new Error(`rule ${i}: bad action '${actionStr}'`);
        }
        set.add(word);
      }
      actions = set;
    }

    const parsedResource = parseResource(resourceStr);
    if (parsedResource === null) {
      throw new Error(`rule ${i}: bad resource '${resourceStr}'`);
    }

    parsedRules[i] = {
      effect,
      principalType,
      principalName,
      actionAll,
      actions,
      segments: parsedResource.segments,
      minSegs: parsedResource.minSegs,
      specL: parsedResource.specL,
      specP: principalType,
      specA: actionAll ? 0 : 1,
    };
  }

  const parsedRequests: ParsedRequest[] = new Array(requests.length);

  for (let j = 0; j < requests.length; j++) {
    const req = requests[j];
    if (!Array.isArray(req) || req.length !== 4) {
      throw new Error(`request ${j}: expected 4-tuple`);
    }

    const [user, groups, action, path] = req;

    if (typeof user !== "string" || !NAME_RE.test(user)) {
      throw new Error(`request ${j}: bad user ${String(user)}`);
    }

    if (!Array.isArray(groups)) {
      throw new Error(`request ${j}: bad groups`);
    }
    const groupSet = new Set<string>();
    for (const g of groups) {
      if (typeof g !== "string" || !NAME_RE.test(g)) {
        throw new Error(`request ${j}: bad groups`);
      }
      groupSet.add(g);
    }

    if (typeof action !== "string" || !ACTION_WORD_RE.test(action)) {
      throw new Error(`request ${j}: bad action ${String(action)}`);
    }

    if (typeof path !== "string") {
      throw new Error(`request ${j}: bad path ${String(path)}`);
    }
    const pathSegments = parsePath(path);
    if (pathSegments === null) {
      throw new Error(`request ${j}: bad path '${path}'`);
    }

    parsedRequests[j] = {
      user,
      groups: groupSet,
      action,
      pathSegments,
    };
  }

  const results: string[] = new Array(parsedRequests.length);

  for (let j = 0; j < parsedRequests.length; j++) {
    const req = parsedRequests[j];
    const pathLen = req.pathSegments.length;

    let bestL = -1;
    let bestP = -1;
    let bestA = -1;
    let bestIsDeny = false;
    let bestIdx = -1;

    for (let i = 0; i < parsedRules.length; i++) {
      const rule = parsedRules[i];

      if (rule.principalType === 2) {
        if (rule.principalName !== req.user) {
          continue;
        }
      } else if (rule.principalType === 1) {
        if (!req.groups.has(rule.principalName)) {
          continue;
        }
      }

      if (!rule.actionAll && !rule.actions!.has(req.action)) {
        continue;
      }

      if (pathLen < rule.minSegs) {
        continue;
      }

      if (!matchPath(rule.segments, req.pathSegments)) {
        continue;
      }

      const l = rule.specL;
      const p = rule.specP;
      const a = rule.specA;

      if (
        l > bestL ||
        (l === bestL && (p > bestP || (p === bestP && a > bestA)))
      ) {
        bestL = l;
        bestP = p;
        bestA = a;
        bestIsDeny = rule.effect === "DENY";
        bestIdx = i;
      } else if (l === bestL && p === bestP && a === bestA) {
        if (!bestIsDeny && rule.effect === "DENY") {
          bestIsDeny = true;
          bestIdx = i;
        }
      }
    }

    if (bestIdx === -1) {
      results[j] = "DENY by default";
    } else {
      results[j] = `${bestIsDeny ? "DENY" : "ALLOW"} by rule ${bestIdx}`;
    }
  }

  return results;
}

import copy
import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*", re.ASCII)


def _value_type(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "str"
    if isinstance(value, list):
        return "list"
    if isinstance(value, dict):
        return "dict"
    raise TypeError(f"unsupported value type: {type(value).__name__}")


def _child_path(parent_path: str, name: str) -> str:
    if _IDENT_RE.fullmatch(name):
        return f"{parent_path}.{name}"
    return f"{parent_path}[{json.dumps(name, ensure_ascii=False)}]"


def _merge_dict(
    layer_index: int,
    overlay: dict,
    target: dict,
    path: str,
    warnings: list[str],
) -> None:
    for key, value in overlay.items():
        if not isinstance(key, str):
            raise TypeError(f"layer {layer_index}: non-string key at {path}")

        if key.startswith("-"):
            op = "delete"
            name = key[1:]
        elif key.endswith("+"):
            op = "append"
            name = key[:-1]
        else:
            op = "set"
            name = key

        if name == "":
            raise ValueError(f"layer {layer_index}: empty key name at {path}")

        child_path = _child_path(path, name)

        if op == "delete":
            if value is not None:
                raise ValueError(
                    f"layer {layer_index}: delete directive needs null at {child_path}"
                )
            if name in target:
                del target[name]
            else:
                warnings.append(
                    f"layer {layer_index}: delete of missing key at {child_path}"
                )
        elif op == "append":
            if not isinstance(value, list):
                raise ValueError(
                    f"layer {layer_index}: append directive needs a list at {child_path}"
                )
            if name not in target:
                target[name] = copy.deepcopy(value)
            elif isinstance(target[name], list):
                target[name].extend(copy.deepcopy(value))
            else:
                raise ValueError(
                    f"layer {layer_index}: cannot append to {_value_type(target[name])} at {child_path}"
                )
        else:
            if name in target:
                old_type = _value_type(target[name])
                new_type = _value_type(value)
                if old_type != new_type:
                    warnings.append(
                        f"layer {layer_index}: type change at {child_path}: {old_type} -> {new_type}"
                    )

            if isinstance(value, dict):
                if name in target and isinstance(target[name], dict):
                    subtarget = target[name]
                else:
                    subtarget = {}
                    target[name] = subtarget
                _merge_dict(layer_index, value, subtarget, child_path, warnings)
            else:
                target[name] = copy.deepcopy(value)


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    for layer_index, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {layer_index} is not a dict")
        _merge_dict(layer_index, layer, result, "$", warnings)

    return result, warnings

package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
	F3 string
}

var (
	openingRe = regexp.MustCompile(`\A-?(0|[1-9][0-9]{0,8})\.[0-9]{2}\z`)
	amountRe  = regexp.MustCompile(`\A(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?\z`)
)

func parseOpeningCents(opening string) (int64, bool) {
	if !openingRe.MatchString(opening) {
		return 0, false
	}
	neg := false
	s := opening
	if s[0] == '-' {
		neg = true
		s = s[1:]
	}
	dot := strings.IndexByte(s, '.')
	intVal, err := strconv.ParseInt(s[:dot], 10, 64)
	if err != nil {
		return 0, false
	}
	fracVal, err := strconv.ParseInt(s[dot+1:], 10, 64)
	if err != nil {
		return 0, false
	}
	cents := intVal*100 + fracVal
	if neg {
		cents = -cents
	}
	return cents, true
}

func parseAmountCents(amount string) (int64, bool) {
	if !amountRe.MatchString(amount) {
		return 0, false
	}
	dot := strings.IndexByte(amount, '.')
	var intStr, fracStr string
	if dot == -1 {
		intStr = amount
	} else {
		intStr = amount[:dot]
		fracStr = amount[dot+1:]
	}
	intVal, err := strconv.ParseInt(intStr, 10, 64)
	if err != nil {
		return 0, false
	}
	var fracVal int64
	if len(fracStr) == 1 {
		fracVal = int64(fracStr[0]-'0') * 10
	} else if len(fracStr) == 2 {
		fracVal = int64(fracStr[0]-'0')*10 + int64(fracStr[1]-'0')
	}
	cents := intVal*100 + fracVal
	if cents == 0 {
		return 0, false
	}
	return cents, true
}

func isValidDate(date string) bool {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return false
	}
	for i := 0; i < 10; i++ {
		if i == 4 || i == 7 {
			continue
		}
		if date[i] < '0' || date[i] > '9' {
			return false
		}
	}
	year, _ := strconv.Atoi(date[0:4])
	month, _ := strconv.Atoi(date[5:7])
	day, _ := strconv.Atoi(date[8:10])
	if year < 1900 || year > 2999 {
		return false
	}
	if month < 1 || month > 12 {
		return false
	}
	maxDay := 31
	switch month {
	case 4, 6, 9, 11:
		maxDay = 30
	case 2:
		if (year%4 == 0 && year%100 != 0) || year%400 == 0 {
			maxDay = 29
		} else {
			maxDay = 28
		}
	}
	return day >= 1 && day <= maxDay
}

func isValidMemo(memo string) bool {
	for _, r := range memo {
		if r < 32 || r == 127 {
			return false
		}
	}
	return len(strings.Fields(memo)) > 0
}

func formatMoney(cents int64) string {
	var neg bool
	var abs uint64
	if cents < 0 {
		neg = true
		abs = uint64(-cents)
	} else {
		abs = uint64(cents)
	}
	intPart := abs / 100
	fracPart := abs % 100

	s := strconv.FormatUint(intPart, 10)
	var b strings.Builder
	if neg {
		b.WriteByte('-')
	}
	n := len(s)
	for i := 0; i < n; i++ {
		if i > 0 && (n-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(s[i])
	}
	b.WriteByte('.')
	b.WriteByte(byte('0' + fracPart/10))
	b.WriteByte(byte('0' + fracPart%10))
	return b.String()
}

func formatMemo(memo string) string {
	norm := strings.Join(strings.Fields(memo), " ")
	runes := []rune(norm)
	if len(runes) > 20 {
		runes = append(runes[:19], '~')
	}
	if len(runes) < 20 {
		return string(runes) + strings.Repeat(" ", 20-len(runes))
	}
	return string(runes)
}

func padLeft(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return strings.Repeat(" ", width-len(s)) + s
}

func formatLine(date, memo, sign string, amtCents, balCents int64) string {
	memoCol := formatMemo(memo)
	amtCol := padLeft(sign+formatMoney(amtCents), 14)
	balCol := padLeft(formatMoney(balCents), 15)
	flag := ""
	if balCents < 0 {
		flag = " OD"
	}
	return fmt.Sprintf("%s  %s  %s  %s%s", date, memoCol, amtCol, balCol, flag)
}

func RenderStatement(opening string, entries []Tuple1) ([]string, error) {
	openingCents, ok := parseOpeningCents(opening)
	if !ok {
		return nil, fmt.Errorf("opening: bad amount %q", opening)
	}

	type parsedEntry struct {
		date   string
		kind   string
		amount int64
		memo   string
	}

	parsed := make([]parsedEntry, len(entries))
	for i, e := range entries {
		date, kind, amountStr, memo := e.F0, e.F1, e.F2, e.F3
		if !isValidDate(date) {
			return nil, fmt.Errorf("entry %d: bad date %q", i, date)
		}
		if i > 0 && date < entries[i-1].F0 {
			return nil, fmt.Errorf("entry %d: date out of order", i)
		}
		if kind != "credit" && kind != "debit" && kind != "fee" {
			return nil, fmt.Errorf("entry %d: bad kind %q", i, kind)
		}
		amtCents, ok := parseAmountCents(amountStr)
		if !ok {
			return nil, fmt.Errorf("entry %d: bad amount %q", i, amountStr)
		}
		if !isValidMemo(memo) {
			return nil, fmt.Errorf("entry %d: bad memo", i)
		}
		parsed[i] = parsedEntry{
			date:   date,
			kind:   kind,
			amount: amtCents,
			memo:   memo,
		}
	}

	lines := make([]string, 0, len(parsed)+3)
	lines = append(lines, "Opening balance: "+formatMoney(openingCents))

	balance := openingCents
	overdraftDates := make(map[string]bool)
	var credits, debits, fees int

	for _, e := range parsed {
		switch e.kind {
		case "credit":
			balance += e.amount
			lines = append(lines, formatLine(e.date, e.memo, "+", e.amount, balance))
			credits++
		case "debit":
			balance -= e.amount
			lines = append(lines, formatLine(e.date, e.memo, "-", e.amount, balance))
			debits++
			if balance < 0 && !overdraftDates[e.date] {
				overdraftDates[e.date] = true
				balance -= 2500
				lines = append(lines, formatLine(e.date, "OVERDRAFT FEE", "-", 2500, balance))
				fees++
			}
		case "fee":
			balance -= e.amount
			lines = append(lines, formatLine(e.date, e.memo, "-", e.amount, balance))
			fees++
		}
	}

	lines = append(lines, "Closing balance: "+formatMoney(balance))
	lines = append(lines, fmt.Sprintf("Credits: %d  Debits: %d  Fees: %d", credits, debits, fees))
	return lines, nil
}

import java.time.DateTimeException;
import java.time.LocalDate;
import java.util.*;
import java.util.regex.Pattern;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2, String f3) {}

    private record ValidatedEntry(String date, String kind, long amountCents, String normalizedMemo) {}

    private static final Pattern OPENING_PATTERN =
            Pattern.compile("-?(0|[1-9][0-9]{0,8})\\.[0-9]{2}");
    private static final Pattern DATE_PATTERN =
            Pattern.compile("[0-9]{4}-[0-9]{2}-[0-9]{2}");
    private static final Pattern AMOUNT_PATTERN =
            Pattern.compile("(0|[1-9][0-9]{0,8})(\\.[0-9]{1,2})?");
    private static final long OVERDRAFT_FEE_CENTS = 2500L;

    public static List<String> renderStatement(String opening, List<Tuple1> entries) {
        if (opening == null) {
            throw new IllegalArgumentException("opening must be a str");
        }
        if (!OPENING_PATTERN.matcher(opening).matches()) {
            throw new IllegalArgumentException("opening: bad amount " + opening);
        }
        long openingCents = parseOpeningCents(opening);

        if (entries == null) {
            throw new IllegalArgumentException("entries must be a list");
        }

        List<ValidatedEntry> validated = new ArrayList<>(entries.size());
        LocalDate prevDate = null;

        for (int i = 0; i < entries.size(); i++) {
            Tuple1 entry = entries.get(i);
            if (entry == null) {
                throw new IllegalArgumentException("entry " + i + ": expected 4-tuple");
            }

            String dateStr = entry.f0();
            LocalDate date = validateDate(dateStr, i);
            if (prevDate != null && date.isBefore(prevDate)) {
                throw new IllegalArgumentException("entry " + i + ": date out of order");
            }

            String kind = entry.f1();
            if (!"credit".equals(kind) && !"debit".equals(kind) && !"fee".equals(kind)) {
                throw new IllegalArgumentException("entry " + i + ": bad kind " + kind);
            }

            long amountCents = validateAndParseAmount(entry.f2(), i);
            String normalizedMemo = validateAndNormalizeMemo(entry.f3(), i);

            validated.add(new ValidatedEntry(dateStr, kind, amountCents, normalizedMemo));
            prevDate = date;
        }

        List<String> lines = new ArrayList<>();
        lines.add("Opening balance: " + formatMoney(openingCents));

        long balance = openingCents;
        long credits = 0;
        long debits = 0;
        long fees = 0;
        Set<String> overdraftDates = new HashSet<>();

        for (ValidatedEntry entry : validated) {
            String sign;
            switch (entry.kind()) {
                case "credit" -> {
                    balance += entry.amountCents();
                    credits++;
                    sign = "+";
                }
                case "debit" -> {
                    balance -= entry.amountCents();
                    debits++;
                    sign = "-";
                }
                case "fee" -> {
                    balance -= entry.amountCents();
                    fees++;
                    sign = "-";
                }
                default -> throw new IllegalStateException("Unexpected kind: " + entry.kind());
            }

            lines.add(formatEntryLine(entry.date(), entry.normalizedMemo(), sign, entry.amountCents(), balance));

            if ("debit".equals(entry.kind()) && balance < 0 && overdraftDates.add(entry.date())) {
                balance -= OVERDRAFT_FEE_CENTS;
                fees++;
                lines.add(formatEntryLine(entry.date(), "OVERDRAFT FEE", "-", OVERDRAFT_FEE_CENTS, balance));
            }
        }

        lines.add("Closing balance: " + formatMoney(balance));
        lines.add("Credits: " + credits + "  Debits: " + debits + "  Fees: " + fees);
        return lines;
    }

    private static long parseOpeningCents(String opening) {
        boolean neg = opening.startsWith("-");
        String s = neg ? opening.substring(1) : opening;
        int dot = s.indexOf('.');
        long dollars = Long.parseLong(s.substring(0, dot));
        long cents = Long.parseLong(s.substring(dot + 1));
        long total = dollars * 100L + cents;
        return neg ? -total : total;
    }

    private static LocalDate validateDate(String date, int index) {
        if (date == null || !DATE_PATTERN.matcher(date).matches()) {
            throw new IllegalArgumentException("entry " + index + ": bad date " + date);
        }
        int year = Integer.parseInt(date.substring(0, 4));
        if (year < 1900 || year > 2999) {
            throw new IllegalArgumentException("entry " + index + ": bad date " + date);
        }
        int month = Integer.parseInt(date.substring(5, 7));
        int day = Integer.parseInt(date.substring(8, 10));
        try {
            return LocalDate.of(year, month, day);
        } catch (DateTimeException ex) {
            throw new IllegalArgumentException("entry " + index + ": bad date " + date);
        }
    }

    private static long validateAndParseAmount(String amount, int index) {
        if (amount == null || !AMOUNT_PATTERN.matcher(amount).matches()) {
            throw new IllegalArgumentException("entry " + index + ": bad amount " + amount);
        }
        int dot = amount.indexOf('.');
        long dollars;
        long cents;
        if (dot < 0) {
            dollars = Long.parseLong(amount);
            cents = 0;
        } else {
            dollars = Long.parseLong(amount.substring(0, dot));
            String frac = amount.substring(dot + 1);
            cents = frac.length() == 1 ? Long.parseLong(frac) * 10L : Long.parseLong(frac);
        }
        long total = dollars * 100L + cents;
        if (total == 0L) {
            throw new IllegalArgumentException("entry " + index + ": bad amount " + amount);
        }
        return total;
    }

    private static String validateAndNormalizeMemo(String memo, int index) {
        if (memo == null) {
            throw new IllegalArgumentException("entry " + index + ": bad memo");
        }
        StringBuilder normalized = new StringBuilder();
        boolean inToken = false;
        boolean needSpace = false;

        int i = 0;
        while (i < memo.length()) {
            int cp = memo.codePointAt(i);
            i += Character.charCount(cp);

            if (cp < 32 || cp == 127) {
                throw new IllegalArgumentException("entry " + index + ": bad memo");
            }
            if (isPyWhitespace(cp)) {
                if (inToken) {
                    inToken = false;
                    needSpace = true;
                }
            } else {
                if (needSpace) {
                    normalized.append(' ');
                    needSpace = false;
                }
                normalized.appendCodePoint(cp);
                inToken = true;
            }
        }

        if (normalized.isEmpty()) {
            throw new IllegalArgumentException("entry " + index + ": bad memo");
        }
        return normalized.toString();
    }

    private static boolean isPyWhitespace(int cp) {
        return cp == 0x85 || Character.isWhitespace(cp) || Character.isSpaceChar(cp);
    }

    private static String formatEntryLine(String date, String normalizedMemo, String sign, long amountCents, long balanceCents) {
        String memoCol = formatMemoColumn(normalizedMemo);
        String amtCol = padLeft(sign + formatMoney(amountCents), 14);
        String balCol = padLeft(formatMoney(balanceCents), 15);
        String flag = balanceCents < 0 ? " OD" : "";
        return date + "  " + memoCol + "  " + amtCol + "  " + balCol + flag;
    }

    private static String formatMemoColumn(String normalizedMemo) {
        int cpCount = normalizedMemo.codePointCount(0, normalizedMemo.length());
        String s = normalizedMemo;
        if (cpCount > 20) {
            int endOffset = normalizedMemo.offsetByCodePoints(0, 19);
            s = normalizedMemo.substring(0, endOffset) + "~";
            cpCount = 20;
        }
        if (cpCount < 20) {
            return s + " ".repeat(20 - cpCount);
        }
        return s;
    }

    private static String padLeft(String s, int width) {
        int cpCount = s.codePointCount(0, s.length());
        if (cpCount < width) {
            return " ".repeat(width - cpCount) + s;
        }
        return s;
    }

    private static String formatMoney(long cents) {
        boolean neg = cents < 0;
        long abs = neg ? -cents : cents;
        long dollars = abs / 100L;
        long rem = abs % 100L;

        String rawDollars = Long.toString(dollars);
        StringBuilder sb = new StringBuilder();
        if (neg) {
            sb.append('-');
        }
        int len = rawDollars.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) {
                sb.append(',');
            }
            sb.append(rawDollars.charAt(i));
        }
        sb.append('.');
        if (rem < 10) {
            sb.append('0');
        }
        sb.append(rem);
        return sb.toString();
    }
}

#include <cstddef>
#include <stdexcept>
#include <string>
#include <tuple>
#include <vector>

namespace {

bool is_ascii_digit(char c) {
    return c >= '0' && c <= '9';
}

long long parse_opening_cents(const std::string& s) {
    const std::size_t n = s.size();
    std::size_t pos = 0;
    bool neg = false;
    if (pos < n && s[pos] == '-') {
        neg = true;
        ++pos;
    }

    if (pos >= n || !is_ascii_digit(s[pos])) {
        throw std::invalid_argument("opening: bad amount");
    }

    long long dollars = 0;
    if (s[pos] == '0') {
        ++pos;
    } else {
        std::size_t start = pos;
        while (pos < n && is_ascii_digit(s[pos])) {
            dollars = dollars * 10 + (s[pos] - '0');
            ++pos;
        }
        if (pos - start > 9) {
            throw std::invalid_argument("opening: bad amount");
        }
    }

    if (pos >= n || s[pos] != '.') {
        throw std::invalid_argument("opening: bad amount");
    }
    ++pos;

    if (n - pos != 2 || !is_ascii_digit(s[pos]) || !is_ascii_digit(s[pos + 1])) {
        throw std::invalid_argument("opening: bad amount");
    }

    long long cents = (s[pos] - '0') * 10 + (s[pos + 1] - '0');
    long long total = dollars * 100 + cents;
    return neg ? -total : total;
}

bool is_valid_date(const std::string& d) {
    if (d.size() != 10 || d[4] != '-' || d[7] != '-') {
        return false;
    }
    for (std::size_t i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) {
            continue;
        }
        if (!is_ascii_digit(d[i])) {
            return false;
        }
    }

    int year = (d[0] - '0') * 1000 + (d[1] - '0') * 100 + (d[2] - '0') * 10 + (d[3] - '0');
    int month = (d[5] - '0') * 10 + (d[6] - '0');
    int day = (d[8] - '0') * 10 + (d[9] - '0');

    if (year < 1900 || year > 2999 || month < 1 || month > 12) {
        return false;
    }

    static constexpr int days_in_month[12] = {
        31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
    };
    int max_day = days_in_month[month - 1];
    if (month == 2 && ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
        max_day = 29;
    }

    return day >= 1 && day <= max_day;
}

long long parse_entry_amount_cents(const std::string& s) {
    const std::size_t n = s.size();
    std::size_t pos = 0;

    if (pos >= n || !is_ascii_digit(s[pos])) {
        throw std::invalid_argument("bad amount");
    }

    long long dollars = 0;
    if (s[pos] == '0') {
        ++pos;
    } else {
        std::size_t start = pos;
        while (pos < n && is_ascii_digit(s[pos])) {
            dollars = dollars * 10 + (s[pos] - '0');
            ++pos;
        }
        if (pos - start > 9) {
            throw std::invalid_argument("bad amount");
        }
    }

    long long cents = 0;
    if (pos < n) {
        if (s[pos] != '.') {
            throw std::invalid_argument("bad amount");
        }
        ++pos;
        std::size_t frac_len = n - pos;
        if (frac_len != 1 && frac_len != 2) {
            throw std::invalid_argument("bad amount");
        }
        if (!is_ascii_digit(s[pos])) {
            throw std::invalid_argument("bad amount");
        }
        if (frac_len == 1) {
            cents = (s[pos] - '0') * 10;
        } else {
            if (!is_ascii_digit(s[pos + 1])) {
                throw std::invalid_argument("bad amount");
            }
            cents = (s[pos] - '0') * 10 + (s[pos + 1] - '0');
        }
    }

    long long total = dollars * 100 + cents;
    if (total <= 0) {
        throw std::invalid_argument("bad amount");
    }
    return total;
}

std::string validate_and_normalize_memo(const std::string& memo) {
    for (char c : memo) {
        unsigned char uc = static_cast<unsigned char>(c);
        if (uc < 32 || uc == 127) {
            throw std::invalid_argument("bad memo");
        }
    }

    std::string normalized;
    std::size_t i = 0;
    const std::size_t n = memo.size();
    while (i < n) {
        while (i < n && memo[i] == ' ') {
            ++i;
        }
        if (i >= n) {
            break;
        }
        std::size_t start = i;
        while (i < n && memo[i] != ' ') {
            ++i;
        }
        if (!normalized.empty()) {
            normalized.push_back(' ');
        }
        normalized.append(memo, start, i - start);
    }

    if (normalized.empty()) {
        throw std::invalid_argument("bad memo");
    }
    return normalized;
}

std::string format_money(long long cents) {
    std::string result;
    if (cents < 0) {
        result.push_back('-');
        cents = -cents;
    }

    long long dollars = cents / 100;
    long long rem_cents = cents % 100;

    std::string raw_dollars = std::to_string(dollars);
    const std::size_t len = raw_dollars.size();
    for (std::size_t i = 0; i < len; ++i) {
        if (i > 0 && (len - i) % 3 == 0) {
            result.push_back(',');
        }
        result.push_back(raw_dollars[i]);
    }

    result.push_back('.');
    result.push_back(static_cast<char>('0' + (rem_cents / 10)));
    result.push_back(static_cast<char>('0' + (rem_cents % 10)));
    return result;
}

std::string format_memo_col(const std::string& normalized_memo) {
    std::string col;
    if (normalized_memo.size() > 20) {
        col = normalized_memo.substr(0, 19);
        col.push_back('~');
    } else {
        col = normalized_memo;
        col.append(20 - col.size(), ' ');
    }
    return col;
}

std::string right_justify(const std::string& s, std::size_t width) {
    if (s.size() >= width) {
        return s;
    }
    return std::string(width - s.size(), ' ') + s;
}

std::string render_entry_line(
    const std::string& date,
    const std::string& norm_memo,
    const std::string& kind,
    long long amount_cents,
    long long balance_after
) {
    std::string amt_str = (kind == "credit" ? "+" : "-") + format_money(amount_cents);
    std::string bal_str = format_money(balance_after);
    std::string line;
    line.reserve(72);
    line += date;
    line += "  ";
    line += format_memo_col(norm_memo);
    line += "  ";
    line += right_justify(amt_str, 14);
    line += "  ";
    line += right_justify(bal_str, 15);
    if (balance_after < 0) {
        line += " OD";
    }
    return line;
}

struct ParsedEntry {
    std::string date;
    std::string kind;
    long long amount_cents;
    std::string norm_memo;
};

} // namespace

std::vector<std::string> render_statement(
    const std::string& opening,
    const std::vector<std::tuple<std::string, std::string, std::string, std::string>>& entries
) {
    long long balance = parse_opening_cents(opening);

    std::vector<ParsedEntry> parsed;
    parsed.reserve(entries.size());

    std::string prev_date;
    for (std::size_t i = 0; i < entries.size(); ++i) {
        const auto& [date, kind, amount, memo] = entries[i];

        if (!is_valid_date(date)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad date");
        }
        if (i > 0 && date < prev_date) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": date out of order");
        }
        if (kind != "credit" && kind != "debit" && kind != "fee") {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad kind");
        }
        long long amount_cents = parse_entry_amount_cents(amount);
        std::string norm_memo = validate_and_normalize_memo(memo);

        prev_date = date;
        parsed.push_back(ParsedEntry{date, kind, amount_cents, std::move(norm_memo)});
    }

    std::vector<std::string> lines;
    lines.reserve(parsed.size() + 3);
    lines.push_back("Opening balance: " + format_money(balance));

    long long credits = 0;
    long long debits = 0;
    long long fees = 0;
    std::string last_auto_fee_date;

    for (const auto& entry : parsed) {
        if (entry.kind == "credit") {
            balance += entry.amount_cents;
            ++credits;
        } else if (entry.kind == "debit") {
            balance -= entry.amount_cents;
            ++debits;
        } else {
            balance -= entry.amount_cents;
            ++fees;
        }

        lines.push_back(render_entry_line(
            entry.date, entry.norm_memo, entry.kind, entry.amount_cents, balance
        ));

        if (entry.kind == "debit" && balance < 0 && last_auto_fee_date != entry.date) {
            constexpr long long kOverdraftFeeCents = 2500;
            balance -= kOverdraftFeeCents;
            ++fees;
            last_auto_fee_date = entry.date;
            lines.push_back(render_entry_line(
                entry.date, "OVERDRAFT FEE", "fee", kOverdraftFeeCents, balance
            ));
        }
    }

    lines.push_back("Closing balance: " + format_money(balance));
    lines.push_back(
        "Credits: " + std::to_string(credits) +
        "  Debits: " + std::to_string(debits) +
        "  Fees: " + std::to_string(fees)
    );

    return lines;
}

interface ParsedEntry {
  date: string;
  kind: "credit" | "debit" | "fee";
  amountCents: number;
  normalizedMemo: string;
}

const OPENING_RE = /^-?(0|[1-9][0-9]{0,8})\.[0-9]{2}$/;
const DATE_RE = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const AMOUNT_RE = /^(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?$/;

function isLeapYear(year: number): boolean {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysInMonth(year: number, month: number): number {
  switch (month) {
    case 1:
    case 3:
    case 5:
    case 7:
    case 8:
    case 10:
    case 12:
      return 31;
    case 4:
    case 6:
    case 9:
    case 11:
      return 30;
    case 2:
      return isLeapYear(year) ? 29 : 28;
    default:
      return 0;
  }
}

function isValidDate(date: unknown): date is string {
  if (typeof date !== "string" || !DATE_RE.test(date)) {
    return false;
  }
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  const day = Number(date.slice(8, 10));
  if (year < 1900 || year > 2999) {
    return false;
  }
  if (month < 1 || month > 12) {
    return false;
  }
  const maxDay = daysInMonth(year, month);
  return day >= 1 && day <= maxDay;
}

function parseOpeningCents(opening: string): number {
  const negative = opening.startsWith("-");
  const unsigned = negative ? opening.slice(1) : opening;
  const dotIdx = unsigned.indexOf(".");
  const intPart = Number(unsigned.slice(0, dotIdx));
  const decPart = Number(unsigned.slice(dotIdx + 1));
  const cents = intPart * 100 + decPart;
  return negative && cents !== 0 ? -cents : cents;
}

function parseAmountCents(amount: string): number {
  const dotIdx = amount.indexOf(".");
  if (dotIdx === -1) {
    return Number(amount) * 100;
  }
  const intPart = Number(amount.slice(0, dotIdx));
  const decStr = amount.slice(dotIdx + 1).padEnd(2, "0");
  return intPart * 100 + Number(decStr);
}

function formatMoney(cents: number): string {
  const negative = cents < 0;
  const abs = Math.abs(cents);
  const intPart = Math.trunc(abs / 100);
  const decPart = abs % 100;
  const intStr = String(intPart).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  const decStr = String(decPart).padStart(2, "0");
  return `${negative ? "-" : ""}${intStr}.${decStr}`;
}

function formatEntryLine(
  date: string,
  kind: "credit" | "debit" | "fee",
  amountCents: number,
  normalizedMemo: string,
  balanceCents: number,
): string {
  const memoChars = Array.from(normalizedMemo);
  const memoTruncated =
    memoChars.length > 20 ? memoChars.slice(0, 19).join("") + "~" : normalizedMemo;
  const memoLen = memoChars.length > 20 ? 20 : memoChars.length;
  const memoField = memoTruncated + " ".repeat(20 - memoLen);

  const sign = kind === "credit" ? "+" : "-";
  const amtField = (sign + formatMoney(amountCents)).padStart(14, " ");
  const balField = formatMoney(balanceCents).padStart(15, " ");
  const flag = balanceCents < 0 ? " OD" : "";

  return `${date}  ${memoField}  ${amtField}  ${balField}${flag}`;
}

export function renderStatement(
  opening: string,
  entries: [string, string, string, string][],
): string[] {
  if (typeof opening !== "string") {
    throw new Error("opening must be a str");
  }
  if (!OPENING_RE.test(opening)) {
    throw new Error(`opening: bad amount ${JSON.stringify(opening)}`);
  }
  if (!Array.isArray(entries)) {
    throw new Error("entries must be a list");
  }

  const openingCents = parseOpeningCents(opening);
  const parsedEntries: ParsedEntry[] = [];
  let prevDate: string | null = null;

  for (let i = 0; i < entries.length; i++) {
    const entry: unknown = entries[i];
    if (!Array.isArray(entry) || entry.length !== 4) {
      throw new Error(`entry ${i}: expected 4-tuple`);
    }

    const [date, kind, amount, memo] = entry as [unknown, unknown, unknown, unknown];

    if (!isValidDate(date)) {
      throw new Error(`entry ${i}: bad date ${JSON.stringify(date)}`);
    }
    if (prevDate !== null && date < prevDate) {
      throw new Error(`entry ${i}: date out of order`);
    }
    prevDate = date;

    if (kind !== "credit" && kind !== "debit" && kind !== "fee") {
      throw new Error(`entry ${i}: bad kind ${JSON.stringify(kind)}`);
    }

    if (typeof amount !== "string" || !AMOUNT_RE.test(amount)) {
      throw new Error(`entry ${i}: bad amount ${JSON.stringify(amount)}`);
    }
    const amountCents = parseAmountCents(amount);
    if (amountCents === 0) {
      throw new Error(`entry ${i}: bad amount ${JSON.stringify(amount)}`);
    }

    if (typeof memo !== "string") {
      throw new Error(`entry ${i}: bad memo`);
    }
    for (const ch of memo) {
      const cp = ch.codePointAt(0)!;
      if (cp < 32 || cp === 127) {
        throw new Error(`entry ${i}: bad memo`);
      }
    }
    const trimmed = memo.trim();
    if (trimmed.length === 0) {
      throw new Error(`entry ${i}: bad memo`);
    }
    const normalizedMemo = trimmed.split(/\s+/).join(" ");

    parsedEntries.push({
      date,
      kind,
      amountCents,
      normalizedMemo,
    });
  }

  const lines: string[] = [];
  let balanceCents = openingCents;
  const overdraftDates = new Set<string>();
  let creditCount = 0;
  let debitCount = 0;
  let feeCount = 0;

  lines.push(`Opening balance: ${formatMoney(openingCents)}`);

  for (const entry of parsedEntries) {
    if (entry.kind === "credit") {
      balanceCents += entry.amountCents;
      creditCount++;
      lines.push(
        formatEntryLine(
          entry.date,
          "credit",
          entry.amountCents,
          entry.normalizedMemo,
          balanceCents,
        ),
      );
    } else if (entry.kind === "debit") {
      balanceCents -= entry.amountCents;
      debitCount++;
      lines.push(
        formatEntryLine(
          entry.date,
          "debit",
          entry.amountCents,
          entry.normalizedMemo,
          balanceCents,
        ),
      );
      if (balanceCents < 0 && !overdraftDates.has(entry.date)) {
        overdraftDates.add(entry.date);
        balanceCents -= 2500;
        feeCount++;
        lines.push(
          formatEntryLine(
            entry.date,
            "fee",
            2500,
            "OVERDRAFT FEE",
            balanceCents,
          ),
        );
      }
    } else {
      balanceCents -= entry.amountCents;
      feeCount++;
      lines.push(
        formatEntryLine(
          entry.date,
          "fee",
          entry.amountCents,
          entry.normalizedMemo,
          balanceCents,
        ),
      );
    }
  }

  lines.push(`Closing balance: ${formatMoney(balanceCents)}`);
  lines.push(`Credits: ${creditCount}  Debits: ${debitCount}  Fees: ${feeCount}`);

  return lines;
}

import re

_PART_RE = r"(?:0|[1-9][0-9]*)"
_N_RE = r"[1-9][0-9]*"
_VERSION_RE = re.compile(rf"({_PART_RE})\.({_PART_RE})\.({_PART_RE})(?:~rc({_N_RE}))?")
_MAJOR_WILDCARD_RE = re.compile(rf"({_PART_RE})\.\*")
_MINOR_WILDCARD_RE = re.compile(rf"({_PART_RE})\.({_PART_RE})\.\*")
_AT_RE = re.compile(rf"@({_PART_RE})\.({_PART_RE})")


def _parse_version(s: str):
    m = _VERSION_RE.fullmatch(s)
    if m is None:
        return None
    x = int(m.group(1))
    y = int(m.group(2))
    z = int(m.group(3))
    rc = m.group(4)
    if rc is None:
        return (x, y, z, 1, 0)
    return (x, y, z, 0, int(rc))


def _compile_clause(clause: str):
    if clause == "*":
        return lambda v: True

    m = _MAJOR_WILDCARD_RE.fullmatch(clause)
    if m is not None:
        x = int(m.group(1))
        return lambda v: v[0] == x

    m = _MINOR_WILDCARD_RE.fullmatch(clause)
    if m is not None:
        x = int(m.group(1))
        y = int(m.group(2))
        return lambda v: v[0] == x and v[1] == y

    m = _AT_RE.fullmatch(clause)
    if m is not None:
        x = int(m.group(1))
        y = int(m.group(2))
        return lambda v: v[0] == x and v[1] >= y

    for op in ("!=", ">=", "<=", ">", "<", "="):
        if clause.startswith(op):
            target = _parse_version(clause[len(op):])
            break
    else:
        op = "="
        target = _parse_version(clause)

    if target is None:
        return None

    if op == "=":
        return lambda v: v == target
    if op == "!=":
        return lambda v: v != target
    if op == ">":
        return lambda v: v > target
    if op == ">=":
        return lambda v: v >= target
    if op == "<":
        return lambda v: v < target
    return lambda v: v <= target


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    parsed_available = []
    for i, element in enumerate(available):
        if not isinstance(element, str):
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed = _parse_version(element)
        if parsed is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append((parsed, element))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives = []
    for a_idx, raw_alt in enumerate(constraint.split("|"), start=1):
        alt = raw_alt.strip(" ")
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        else:
            allow_rc = False

        if alt == "":
            raise ValueError(f"alternative {a_idx} is empty")

        predicates = []
        for c_idx, raw_clause in enumerate(alt.split(","), start=1):
            clause = raw_clause.strip(" ")
            pred = _compile_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a_idx}, clause {c_idx}: invalid clause {clause!r}"
                )
            predicates.append(pred)

        alternatives.append((allow_rc, predicates))

    best_parsed = None
    best_str = None
    for parsed, ver_str in parsed_available:
        is_rc = parsed[3] == 0
        for allow_rc, predicates in alternatives:
            if is_rc and not allow_rc:
                continue
            if all(pred(parsed) for pred in predicates):
                if best_parsed is None or parsed > best_parsed:
                    best_parsed = parsed
                    best_str = ver_str
                break

    return best_str

package main

import (
	"errors"
	"fmt"
	"strings"
)

type version struct {
	raw  string
	x    string
	y    string
	z    string
	isRC bool
	n    string
}

func isValidNumPart(s string, allowZero bool) bool {
	if len(s) == 0 {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	if !allowZero && s == "0" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func parseVersion(s string) (version, bool) {
	v := version{raw: s}
	base := s
	if idx := strings.IndexByte(s, '~'); idx != -1 {
		base = s[:idx]
		rc := s[idx+1:]
		if !strings.HasPrefix(rc, "rc") {
			return v, false
		}
		nStr := rc[2:]
		if !isValidNumPart(nStr, false) {
			return v, false
		}
		v.isRC = true
		v.n = nStr
	}

	parts := strings.Split(base, ".")
	if len(parts) != 3 {
		return v, false
	}
	if !isValidNumPart(parts[0], true) || !isValidNumPart(parts[1], true) || !isValidNumPart(parts[2], true) {
		return v, false
	}
	v.x = parts[0]
	v.y = parts[1]
	v.z = parts[2]
	return v, true
}

func cmpNum(a, b string) int {
	if len(a) < len(b) {
		return -1
	}
	if len(a) > len(b) {
		return 1
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func cmpVersion(a, b version) int {
	if c := cmpNum(a.x, b.x); c != 0 {
		return c
	}
	if c := cmpNum(a.y, b.y); c != 0 {
		return c
	}
	if c := cmpNum(a.z, b.z); c != 0 {
		return c
	}
	if !a.isRC && !b.isRC {
		return 0
	}
	if !a.isRC {
		return 1
	}
	if !b.isRC {
		return -1
	}
	return cmpNum(a.n, b.n)
}

type clauseKind int

const (
	clauseAny clauseKind = iota
	clauseEq
	clauseNe
	clauseGt
	clauseGe
	clauseLt
	clauseLe
	clauseMajorWild
	clauseMinorWild
	clauseAtMinor
)

type clause struct {
	kind clauseKind
	ver  version
	x    string
	y    string
}

func parseClause(s string) (clause, bool) {
	if s == "*" {
		return clause{kind: clauseAny}, true
	}
	if strings.HasPrefix(s, "!=") {
		v, ok := parseVersion(s[2:])
		return clause{kind: clauseNe, ver: v}, ok
	}
	if strings.HasPrefix(s, ">=") {
		v, ok := parseVersion(s[2:])
		return clause{kind: clauseGe, ver: v}, ok
	}
	if strings.HasPrefix(s, "<=") {
		v, ok := parseVersion(s[2:])
		return clause{kind: clauseLe, ver: v}, ok
	}
	if strings.HasPrefix(s, ">") {
		v, ok := parseVersion(s[1:])
		return clause{kind: clauseGt, ver: v}, ok
	}
	if strings.HasPrefix(s, "<") {
		v, ok := parseVersion(s[1:])
		return clause{kind: clauseLt, ver: v}, ok
	}
	if strings.HasPrefix(s, "=") {
		v, ok := parseVersion(s[1:])
		return clause{kind: clauseEq, ver: v}, ok
	}
	if strings.HasPrefix(s, "@") {
		parts := strings.Split(s[1:], ".")
		if len(parts) == 2 && isValidNumPart(parts[0], true) && isValidNumPart(parts[1], true) {
			return clause{kind: clauseAtMinor, x: parts[0], y: parts[1]}, true
		}
		return clause{}, false
	}
	if strings.HasSuffix(s, ".*") {
		prefix := s[:len(s)-2]
		parts := strings.Split(prefix, ".")
		if len(parts) == 1 && isValidNumPart(parts[0], true) {
			return clause{kind: clauseMajorWild, x: parts[0]}, true
		}
		if len(parts) == 2 && isValidNumPart(parts[0], true) && isValidNumPart(parts[1], true) {
			return clause{kind: clauseMinorWild, x: parts[0], y: parts[1]}, true
		}
		return clause{}, false
	}
	v, ok := parseVersion(s)
	return clause{kind: clauseEq, ver: v}, ok
}

func matchClause(v version, c clause) bool {
	switch c.kind {
	case clauseAny:
		return true
	case clauseEq:
		return cmpVersion(v, c.ver) == 0
	case clauseNe:
		return cmpVersion(v, c.ver) != 0
	case clauseGt:
		return cmpVersion(v, c.ver) > 0
	case clauseGe:
		return cmpVersion(v, c.ver) >= 0
	case clauseLt:
		return cmpVersion(v, c.ver) < 0
	case clauseLe:
		return cmpVersion(v, c.ver) <= 0
	case clauseMajorWild:
		return v.x == c.x
	case clauseMinorWild:
		return v.x == c.x && v.y == c.y
	case clauseAtMinor:
		return v.x == c.x && cmpNum(v.y, c.y) >= 0
	default:
		return false
	}
}

type alternative struct {
	allowRC bool
	clauses []clause
}

func matchAlternative(v version, alt alternative) bool {
	if v.isRC && !alt.allowRC {
		return false
	}
	for _, c := range alt.clauses {
		if !matchClause(v, c) {
			return false
		}
	}
	return true
}

func matchConstraint(v version, alts []alternative) bool {
	for _, alt := range alts {
		if matchAlternative(v, alt) {
			return true
		}
	}
	return false
}

func PickVersion(available []string, constraint string) (*string, error) {
	versions := make([]version, len(available))
	for i, s := range available {
		v, ok := parseVersion(s)
		if !ok {
			return nil, fmt.Errorf("invalid version at index %d: %q", i, s)
		}
		versions[i] = v
	}

	if strings.Trim(constraint, " ") == "" {
		return nil, errors.New("empty constraint")
	}

	rawAlts := strings.Split(constraint, "|")
	alts := make([]alternative, len(rawAlts))
	for i, rawAlt := range rawAlts {
		a := i + 1
		altStr := strings.Trim(rawAlt, " ")
		allowRC := false
		if strings.HasPrefix(altStr, "?") {
			allowRC = true
			altStr = strings.Trim(altStr[1:], " ")
		}
		if altStr == "" {
			return nil, fmt.Errorf("alternative %d is empty", a)
		}

		rawClauses := strings.Split(altStr, ",")
		clauses := make([]clause, len(rawClauses))
		for j, rawClause := range rawClauses {
			c := j + 1
			clauseStr := strings.Trim(rawClause, " ")
			parsed, ok := parseClause(clauseStr)
			if !ok {
				return nil, fmt.Errorf("alternative %d, clause %d: invalid clause %q", a, c, clauseStr)
			}
			clauses[j] = parsed
		}
		alts[i] = alternative{
			allowRC: allowRC,
			clauses: clauses,
		}
	}

	var best *version
	for i := range versions {
		if matchConstraint(versions[i], alts) {
			if best == nil || cmpVersion(versions[i], *best) > 0 {
				best = &versions[i]
			}
		}
	}

	if best == nil {
		return nil, nil
	}
	res := best.raw
	return &res, nil
}

import java.util.*;

public final class Solution {
    public static String pickVersion(List<String> available, String constraint) {
        if (available == null) {
            throw new IllegalArgumentException("available must be a list");
        }
        List<Version> versions = new ArrayList<>(available.size());
        for (int i = 0; i < available.size(); i++) {
            String elem = available.get(i);
            Version v = parseVersion(elem);
            if (v == null) {
                throw new IllegalArgumentException("invalid version at index " + i + ": " + elem);
            }
            versions.add(v);
        }
        if (constraint == null) {
            throw new IllegalArgumentException("constraint must be a str");
        }
        if (stripSpaces(constraint).isEmpty()) {
            throw new IllegalArgumentException("empty constraint");
        }

        String[] rawAlts = constraint.split("\\|", -1);
        List<Alternative> alternatives = new ArrayList<>(rawAlts.length);
        for (int a = 0; a < rawAlts.length; a++) {
            String altText = stripSpaces(rawAlts[a]);
            boolean allowRc = false;
            if (altText.startsWith("?")) {
                allowRc = true;
                altText = stripSpaces(altText.substring(1));
            }
            if (altText.isEmpty()) {
                throw new IllegalArgumentException("alternative " + (a + 1) + " is empty");
            }
            String[] rawClauses = altText.split(",", -1);
            List<Clause> clauses = new ArrayList<>(rawClauses.length);
            for (int c = 0; c < rawClauses.length; c++) {
                String clauseText = stripSpaces(rawClauses[c]);
                Clause clause = parseClause(clauseText);
                if (clause == null) {
                    throw new IllegalArgumentException(
                            "alternative " + (a + 1) + ", clause " + (c + 1) + ": invalid clause '" + clauseText + "'");
                }
                clauses.add(clause);
            }
            alternatives.add(new Alternative(allowRc, clauses));
        }

        Version best = null;
        for (Version v : versions) {
            boolean ok = false;
            for (Alternative alt : alternatives) {
                if (alt.matches(v)) {
                    ok = true;
                    break;
                }
            }
            if (ok && (best == null || v.compareTo(best) > 0)) {
                best = v;
            }
        }
        return best == null ? null : best.original();
    }

    private static String stripSpaces(String s) {
        int start = 0;
        int end = s.length();
        while (start < end && s.charAt(start) == ' ') {
            start++;
        }
        while (end > start && s.charAt(end - 1) == ' ') {
            end--;
        }
        return s.substring(start, end);
    }

    private static boolean isValidPart(String s) {
        if (s.isEmpty()) {
            return false;
        }
        if (s.equals("0")) {
            return true;
        }
        char first = s.charAt(0);
        if (first < '1' || first > '9') {
            return false;
        }
        for (int i = 1; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch < '0' || ch > '9') {
                return false;
            }
        }
        return true;
    }

    private static boolean isValidPositivePart(String s) {
        return !s.equals("0") && isValidPart(s);
    }

    private static int compareNum(String a, String b) {
        int cmp = Integer.compare(a.length(), b.length());
        if (cmp != 0) {
            return cmp;
        }
        return a.compareTo(b);
    }

    private static Version parseVersion(String s) {
        if (s == null || s.isEmpty()) {
            return null;
        }
        String base = s;
        String rc = null;
        int tildeIdx = s.indexOf('~');
        if (tildeIdx >= 0) {
            String suffix = s.substring(tildeIdx);
            if (!suffix.startsWith("~rc")) {
                return null;
            }
            String rcNum = suffix.substring(3);
            if (!isValidPositivePart(rcNum)) {
                return null;
            }
            rc = rcNum;
            base = s.substring(0, tildeIdx);
        }
        int dot1 = base.indexOf('.');
        if (dot1 < 0) {
            return null;
        }
        int dot2 = base.indexOf('.', dot1 + 1);
        if (dot2 < 0 || base.indexOf('.', dot2 + 1) >= 0) {
            return null;
        }
        String major = base.substring(0, dot1);
        String minor = base.substring(dot1 + 1, dot2);
        String patch = base.substring(dot2 + 1);
        if (!isValidPart(major) || !isValidPart(minor) || !isValidPart(patch)) {
            return null;
        }
        return new Version(s, major, minor, patch, rc);
    }

    private static Clause parseClause(String clause) {
        if (clause.isEmpty()) {
            return null;
        }
        if (clause.equals("*")) {
            return new MatchAll();
        }
        if (clause.startsWith("@")) {
            String rest = clause.substring(1);
            int dot = rest.indexOf('.');
            if (dot < 0 || rest.indexOf('.', dot + 1) >= 0) {
                return null;
            }
            String major = rest.substring(0, dot);
            String minor = rest.substring(dot + 1);
            if (!isValidPart(major) || !isValidPart(minor)) {
                return null;
            }
            return new AtLeastMinor(major, minor);
        }
        if (clause.startsWith(">=")) {
            Version v = parseVersion(clause.substring(2));
            return v == null ? null : new CompareClause(CompareOp.GE, v);
        }
        if (clause.startsWith("<=")) {
            Version v = parseVersion(clause.substring(2));
            return v == null ? null : new CompareClause(CompareOp.LE, v);
        }
        if (clause.startsWith("!=")) {
            Version v = parseVersion(clause.substring(2));
            return v == null ? null : new CompareClause(CompareOp.NE, v);
        }
        if (clause.startsWith(">")) {
            Version v = parseVersion(clause.substring(1));
            return v == null ? null : new CompareClause(CompareOp.GT, v);
        }
        if (clause.startsWith("<")) {
            Version v = parseVersion(clause.substring(1));
            return v == null ? null : new CompareClause(CompareOp.LT, v);
        }
        if (clause.startsWith("=")) {
            Version v = parseVersion(clause.substring(1));
            return v == null ? null : new CompareClause(CompareOp.EQ, v);
        }
        if (clause.endsWith(".*")) {
            String prefix = clause.substring(0, clause.length() - 2);
            int dot = prefix.indexOf('.');
            if (dot < 0) {
                return isValidPart(prefix) ? new MajorWildcard(prefix) : null;
            }
            if (prefix.indexOf('.', dot + 1) >= 0) {
                return null;
            }
            String major = prefix.substring(0, dot);
            String minor = prefix.substring(dot + 1);
            if (!isValidPart(major) || !isValidPart(minor)) {
                return null;
            }
            return new MajorMinorWildcard(major, minor);
        }
        Version v = parseVersion(clause);
        return v == null ? null : new CompareClause(CompareOp.EQ, v);
    }

    private record Version(String original, String major, String minor, String patch, String rc)
            implements Comparable<Version> {
        @Override
        public int compareTo(Version other) {
            int c = compareNum(this.major, other.major);
            if (c != 0) {
                return c;
            }
            c = compareNum(this.minor, other.minor);
            if (c != 0) {
                return c;
            }
            c = compareNum(this.patch, other.patch);
            if (c != 0) {
                return c;
            }
            if (this.rc == null && other.rc == null) {
                return 0;
            }
            if (this.rc == null) {
                return 1;
            }
            if (other.rc == null) {
                return -1;
            }
            return compareNum(this.rc, other.rc);
        }
    }

    private record Alternative(boolean allowRc, List<Clause> clauses) {
        boolean matches(Version v) {
            if (v.rc() != null && !allowRc) {
                return false;
            }
            for (Clause clause : clauses) {
                if (!clause.matches(v)) {
                    return false;
                }
            }
            return true;
        }
    }

    private enum CompareOp {
        EQ, NE, GT, GE, LT, LE
    }

    private sealed interface Clause {
        boolean matches(Version v);
    }

    private record MatchAll() implements Clause {
        @Override
        public boolean matches(Version v) {
            return true;
        }
    }

    private record CompareClause(CompareOp op, Version target) implements Clause {
        @Override
        public boolean matches(Version v) {
            int cmp = v.compareTo(target);
            return switch (op) {
                case EQ -> cmp == 0;
                case NE -> cmp != 0;
                case GT -> cmp > 0;
                case GE -> cmp >= 0;
                case LT -> cmp < 0;
                case LE -> cmp <= 0;
            };
        }
    }

    private record MajorWildcard(String major) implements Clause {
        @Override
        public boolean matches(Version v) {
            return v.major().equals(major);
        }
    }

    private record MajorMinorWildcard(String major, String minor) implements Clause {
        @Override
        public boolean matches(Version v) {
            return v.major().equals(major) && v.minor().equals(minor);
        }
    }

    private record AtLeastMinor(String major, String minor) implements Clause {
        @Override
        public boolean matches(Version v) {
            return v.major().equals(major) && compareNum(v.minor(), minor) >= 0;
        }
    }
}

#include <cstddef>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

namespace {

std::string_view trim_spaces(std::string_view s) {
    while (!s.empty() && s.front() == ' ') {
        s.remove_prefix(1);
    }
    while (!s.empty() && s.back() == ' ') {
        s.remove_suffix(1);
    }
    return s;
}

std::vector<std::string_view> split_char(std::string_view s, char delim) {
    std::vector<std::string_view> out;
    std::size_t start = 0;
    while (true) {
        std::size_t pos = s.find(delim, start);
        if (pos == std::string_view::npos) {
            out.push_back(s.substr(start));
            break;
        }
        out.push_back(s.substr(start, pos - start));
        start = pos + 1;
    }
    return out;
}

bool is_valid_part(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    if (s.size() > 1 && s[0] == '0') {
        return false;
    }
    for (char ch : s) {
        if (ch < '0' || ch > '9') {
            return false;
        }
    }
    return true;
}

int cmp_uint_str(std::string_view a, std::string_view b) {
    if (a.size() != b.size()) {
        return a.size() < b.size() ? -1 : 1;
    }
    if (a == b) {
        return 0;
    }
    return a < b ? -1 : 1;
}

struct Version {
    std::string raw;
    std::string x;
    std::string y;
    std::string z;
    bool is_rc = false;
    std::string n;
};

std::optional<Version> parse_version(std::string_view s) {
    std::size_t tilde = s.find('~');
    std::string_view main_part = (tilde == std::string_view::npos) ? s : s.substr(0, tilde);

    Version v;
    v.raw = std::string(s);

    if (tilde != std::string_view::npos) {
        std::string_view rc_part = s.substr(tilde + 1);
        if (rc_part.size() < 3 || rc_part[0] != 'r' || rc_part[1] != 'c') {
            return std::nullopt;
        }
        std::string_view n_part = rc_part.substr(2);
        if (!is_valid_part(n_part) || n_part == "0") {
            return std::nullopt;
        }
        v.is_rc = true;
        v.n = std::string(n_part);
    }

    auto parts = split_char(main_part, '.');
    if (parts.size() != 3) {
        return std::nullopt;
    }
    if (!is_valid_part(parts[0]) || !is_valid_part(parts[1]) || !is_valid_part(parts[2])) {
        return std::nullopt;
    }
    v.x = std::string(parts[0]);
    v.y = std::string(parts[1]);
    v.z = std::string(parts[2]);
    return v;
}

int cmp_version(const Version& a, const Version& b) {
    if (int c = cmp_uint_str(a.x, b.x); c != 0) return c;
    if (int c = cmp_uint_str(a.y, b.y); c != 0) return c;
    if (int c = cmp_uint_str(a.z, b.z); c != 0) return c;
    if (a.is_rc != b.is_rc) {
        return a.is_rc ? -1 : 1;
    }
    if (!a.is_rc) {
        return 0;
    }
    return cmp_uint_str(a.n, b.n);
}

enum class ClauseKind {
    Wildcard,
    Eq,
    Ne,
    Gt,
    Ge,
    Lt,
    Le,
    MajorWild,
    MajorMinorWild,
    AtMajorMinor
};

struct Clause {
    ClauseKind kind;
    Version ver;
    std::string x;
    std::string y;

    bool matches(const Version& candidate) const {
        switch (kind) {
            case ClauseKind::Wildcard:
                return true;
            case ClauseKind::Eq:
                return cmp_version(candidate, ver) == 0;
            case ClauseKind::Ne:
                return cmp_version(candidate, ver) != 0;
            case ClauseKind::Gt:
                return cmp_version(candidate, ver) > 0;
            case ClauseKind::Ge:
                return cmp_version(candidate, ver) >= 0;
            case ClauseKind::Lt:
                return cmp_version(candidate, ver) < 0;
            case ClauseKind::Le:
                return cmp_version(candidate, ver) <= 0;
            case ClauseKind::MajorWild:
                return candidate.x == x;
            case ClauseKind::MajorMinorWild:
                return candidate.x == x && candidate.y == y;
            case ClauseKind::AtMajorMinor:
                return candidate.x == x && cmp_uint_str(candidate.y, y) >= 0;
        }
        return false;
    }
};

std::optional<Clause> parse_clause(std::string_view s) {
    if (s.empty()) {
        return std::nullopt;
    }
    if (s == "*") {
        Clause c;
        c.kind = ClauseKind::Wildcard;
        return c;
    }
    if (s.front() == '@') {
        auto parts = split_char(s.substr(1), '.');
        if (parts.size() != 2 || !is_valid_part(parts[0]) || !is_valid_part(parts[1])) {
            return std::nullopt;
        }
        Clause c;
        c.kind = ClauseKind::AtMajorMinor;
        c.x = std::string(parts[0]);
        c.y = std::string(parts[1]);
        return c;
    }

    auto parse_op = [&](std::string_view prefix, ClauseKind kind) -> std::optional<Clause> {
        if (s.size() >= prefix.size() && s.substr(0, prefix.size()) == prefix) {
            auto v = parse_version(s.substr(prefix.size()));
            if (!v) {
                return std::nullopt;
            }
            Clause c;
            c.kind = kind;
            c.ver = std::move(*v);
            return c;
        }
        return std::nullopt;
    };

    if (s.size() >= 2 && s.substr(0, 2) == "!=") return parse_op("!=", ClauseKind::Ne);
    if (s.size() >= 2 && s.substr(0, 2) == ">=") return parse_op(">=", ClauseKind::Ge);
    if (s.size() >= 2 && s.substr(0, 2) == "<=") return parse_op("<=", ClauseKind::Le);
    if (s.front() == '>') return parse_op(">", ClauseKind::Gt);
    if (s.front() == '<') return parse_op("<", ClauseKind::Lt);
    if (s.front() == '=') return parse_op("=", ClauseKind::Eq);

    if (s.size() >= 2 && s.substr(s.size() - 2) == ".*") {
        std::string_view prefix = s.substr(0, s.size() - 2);
        auto parts = split_char(prefix, '.');
        if (parts.size() == 1 && is_valid_part(parts[0])) {
            Clause c;
            c.kind = ClauseKind::MajorWild;
            c.x = std::string(parts[0]);
            return c;
        }
        if (parts.size() == 2 && is_valid_part(parts[0]) && is_valid_part(parts[1])) {
            Clause c;
            c.kind = ClauseKind::MajorMinorWild;
            c.x = std::string(parts[0]);
            c.y = std::string(parts[1]);
            return c;
        }
        return std::nullopt;
    }

    auto v = parse_version(s);
    if (!v) {
        return std::nullopt;
    }
    Clause c;
    c.kind = ClauseKind::Eq;
    c.ver = std::move(*v);
    return c;
}

struct Alternative {
    bool allows_rc = false;
    std::vector<Clause> clauses;

    bool matches(const Version& candidate) const {
        if (candidate.is_rc && !allows_rc) {
            return false;
        }
        for (const auto& clause : clauses) {
            if (!clause.matches(candidate)) {
                return false;
            }
        }
        return true;
    }
};

} // namespace

std::optional<std::string> pick_version(const std::vector<std::string>& available, const std::string& constraint) {
    std::vector<Version> versions;
    versions.reserve(available.size());
    for (std::size_t i = 0; i < available.size(); ++i) {
        auto parsed = parse_version(available[i]);
        if (!parsed) {
            throw std::invalid_argument("invalid version at index " + std::to_string(i) + ": '" + available[i] + "'");
        }
        versions.push_back(std::move(*parsed));
    }

    if (trim_spaces(constraint).empty()) {
        throw std::invalid_argument("empty constraint");
    }

    auto raw_alts = split_char(constraint, '|');
    std::vector<Alternative> alternatives;
    alternatives.reserve(raw_alts.size());

    for (std::size_t a_idx = 0; a_idx < raw_alts.size(); ++a_idx) {
        std::size_t a_num = a_idx + 1;
        std::string_view alt_sv = trim_spaces(raw_alts[a_idx]);
        Alternative alt;
        if (!alt_sv.empty() && alt_sv.front() == '?') {
            alt.allows_rc = true;
            alt_sv.remove_prefix(1);
            alt_sv = trim_spaces(alt_sv);
        }
        if (alt_sv.empty()) {
            throw std::invalid_argument("alternative " + std::to_string(a_num) + " is empty");
        }

        auto raw_clauses = split_char(alt_sv, ',');
        alt.clauses.reserve(raw_clauses.size());
        for (std::size_t c_idx = 0; c_idx < raw_clauses.size(); ++c_idx) {
            std::size_t c_num = c_idx + 1;
            std::string_view clause_sv = trim_spaces(raw_clauses[c_idx]);
            auto parsed_clause = parse_clause(clause_sv);
            if (!parsed_clause) {
                throw std::invalid_argument(
                    "alternative " + std::to_string(a_num) +
                    ", clause " + std::to_string(c_num) +
                    ": invalid clause '" + std::string(clause_sv) + "'"
                );
            }
            alt.clauses.push_back(std::move(*parsed_clause));
        }
        alternatives.push_back(std::move(alt));
    }

    std::optional<std::size_t> best_idx;
    for (std::size_t i = 0; i < versions.size(); ++i) {
        bool ok = false;
        for (const auto& alt : alternatives) {
            if (alt.matches(versions[i])) {
                ok = true;
                break;
            }
        }
        if (ok) {
            if (!best_idx || cmp_version(versions[i], versions[*best_idx]) > 0) {
                best_idx = i;
            }
        }
    }

    if (!best_idx) {
        return std::nullopt;
    }
    return available[*best_idx];
}

type ParsedVersion = {
  raw: string;
  major: number;
  minor: number;
  patch: number;
  rc: number | null;
};

type CmpOp = "=" | "!=" | ">" | ">=" | "<" | "<=";

type Clause =
  | { kind: "any" }
  | { kind: "cmp"; op: CmpOp; target: ParsedVersion }
  | { kind: "major"; major: number }
  | { kind: "minor"; major: number; minor: number }
  | { kind: "atLeastMinor"; major: number; minor: number };

type Alternative = {
  allowRc: boolean;
  clauses: Clause[];
};

const VERSION_RE =
  /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:~rc([1-9][0-9]*))?$/;
const MAJOR_WILDCARD_RE = /^(0|[1-9][0-9]*)\.\*$/;
const MINOR_WILDCARD_RE = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.\*$/;
const AT_LEAST_MINOR_RE = /^@(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function trimSpaces(s: string): string {
  return s.replace(/^ +| +$/g, "");
}

function parseVersion(s: string): ParsedVersion | null {
  const m = VERSION_RE.exec(s);
  if (!m) {
    return null;
  }
  return {
    raw: s,
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    rc: m[4] !== undefined ? Number(m[4]) : null,
  };
}

function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  if (a.major !== b.major) return a.major - b.major;
  if (a.minor !== b.minor) return a.minor - b.minor;
  if (a.patch !== b.patch) return a.patch - b.patch;
  if (a.rc === b.rc) return 0;
  if (a.rc === null) return 1;
  if (b.rc === null) return -1;
  return a.rc - b.rc;
}

function parseClause(clause: string): Clause | null {
  if (clause === "*") {
    return { kind: "any" };
  }

  let m = MAJOR_WILDCARD_RE.exec(clause);
  if (m) {
    return { kind: "major", major: Number(m[1]) };
  }

  m = MINOR_WILDCARD_RE.exec(clause);
  if (m) {
    return { kind: "minor", major: Number(m[1]), minor: Number(m[2]) };
  }

  m = AT_LEAST_MINOR_RE.exec(clause);
  if (m) {
    return { kind: "atLeastMinor", major: Number(m[1]), minor: Number(m[2]) };
  }

  const ops: readonly CmpOp[] = ["!=", ">=", "<=", "=", ">", "<"];
  for (const op of ops) {
    if (clause.startsWith(op)) {
      const target = parseVersion(clause.slice(op.length));
      if (!target) {
        return null;
      }
      return { kind: "cmp", op, target };
    }
  }

  const target = parseVersion(clause);
  if (target) {
    return { kind: "cmp", op: "=", target };
  }

  return null;
}

function matchesClause(v: ParsedVersion, clause: Clause): boolean {
  switch (clause.kind) {
    case "any":
      return true;
    case "major":
      return v.major === clause.major;
    case "minor":
      return v.major === clause.major && v.minor === clause.minor;
    case "atLeastMinor":
      return v.major === clause.major && v.minor >= clause.minor;
    case "cmp": {
      const cmp = compareVersions(v, clause.target);
      switch (clause.op) {
        case "=":
          return cmp === 0;
        case "!=":
          return cmp !== 0;
        case ">":
          return cmp > 0;
        case ">=":
          return cmp >= 0;
        case "<":
          return cmp < 0;
        case "<=":
          return cmp <= 0;
      }
    }
  }
}

export function pickVersion(
  available: string[],
  constraint: string,
): string | null {
  if (!Array.isArray(available)) {
    throw new Error("available must be a list");
  }

  const parsedAvailable: ParsedVersion[] = [];
  for (let i = 0; i < available.length; i++) {
    const elem = available[i];
    if (typeof elem !== "string") {
      throw new Error(`invalid version at index ${i}: ${String(elem)}`);
    }
    const parsed = parseVersion(elem);
    if (!parsed) {
      throw new Error(`invalid version at index ${i}: ${JSON.stringify(elem)}`);
    }
    parsedAvailable.push(parsed);
  }

  if (typeof constraint !== "string") {
    throw new Error("constraint must be a str");
  }

  if (/^ *$/.test(constraint)) {
    throw new Error("empty constraint");
  }

  const rawAlts = constraint.split("|");
  const alternatives: Alternative[] = [];

  for (let aIdx = 0; aIdx < rawAlts.length; aIdx++) {
    const altNum = aIdx + 1;
    let altText = trimSpaces(rawAlts[aIdx]);
    let allowRc = false;
    if (altText.startsWith("?")) {
      allowRc = true;
      altText = trimSpaces(altText.slice(1));
    }

    if (altText === "") {
      throw new Error(`alternative ${altNum} is empty`);
    }

    const rawClauses = altText.split(",");
    const clauses: Clause[] = [];
    for (let cIdx = 0; cIdx < rawClauses.length; cIdx++) {
      const clauseNum = cIdx + 1;
      const clauseText = trimSpaces(rawClauses[cIdx]);
      const parsedClause = parseClause(clauseText);
      if (!parsedClause) {
        throw new Error(
          `alternative ${altNum}, clause ${clauseNum}: invalid clause ${JSON.stringify(clauseText)}`,
        );
      }
      clauses.push(parsedClause);
    }

    alternatives.push({ allowRc, clauses });
  }

  let best: ParsedVersion | null = null;

  for (const v of parsedAvailable) {
    let satisfied = false;
    for (const alt of alternatives) {
      if (v.rc !== null && !alt.allowRc) {
        continue;
      }
      let allMatch = true;
      for (const clause of alt.clauses) {
        if (!matchesClause(v, clause)) {
          allMatch = false;
          break;
        }
      }
      if (allMatch) {
        satisfied = true;
        break;
      }
    }

    if (satisfied && (best === null || compareVersions(v, best) > 0)) {
      best = v;
    }
  }

  return best ? best.raw : null;
}

import re

_KEY_FULLMATCH = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*").fullmatch
_INT_FULLMATCH = re.compile(r"-?(?:0|[1-9][0-9]*)").fullmatch


def _parse_scalar(text: str, line_no: int):
    if text[0] == '"':
        if "\\" not in text:
            end = text.find('"', 1)
            if end == -1 or end != len(text) - 1:
                return None, ("error", line_no, "bad string")
            return text[1:-1], None

        out = []
        i = 1
        n = len(text)
        closed = False
        while i < n:
            ch = text[i]
            if ch == "\\":
                i += 1
                if i >= n:
                    return None, ("error", line_no, "bad escape")
                esc = text[i]
                if esc == "\\":
                    out.append("\\")
                elif esc == '"':
                    out.append('"')
                elif esc == "n":
                    out.append("\n")
                elif esc == "t":
                    out.append("\t")
                else:
                    return None, ("error", line_no, "bad escape")
                i += 1
            elif ch == '"':
                if i != n - 1:
                    return None, ("error", line_no, "bad string")
                closed = True
                break
            else:
                out.append(ch)
                i += 1

        if not closed:
            return None, ("error", line_no, "bad string")
        return "".join(out), None

    if text == "true":
        return True, None
    if text == "false":
        return False, None
    if text == "null":
        return None, None
    if text[0] in "-0123456789" and _INT_FULLMATCH(text) is not None:
        return int(text), None
    return text, None


def parse_outline(text: str) -> tuple:
    root = None
    stack = []  # entries: (indent, kind, container) where kind is "dict" or "list"
    pending_opener = None  # None or (indent, parent_container, key_or_index)

    for line_no, line in enumerate(text.split("\n"), 1):
        rest = line.lstrip(" \t")
        if not rest or rest[0] == "#":
            continue

        lead_len = len(line) - len(rest)
        if lead_len and line.find("\t", 0, lead_len) != -1:
            return ("error", line_no, "tab in indentation")

        if rest == "-" or rest.startswith("- "):
            kind = "list"
            key = None
            raw = rest[2:].strip(" ")
            if not raw:
                is_opener = True
                val = None
            else:
                is_opener = False
                val, err = _parse_scalar(raw, line_no)
                if err is not None:
                    return err
        else:
            colon = rest.find(":")
            if colon == -1:
                return ("error", line_no, "invalid entry")
            key = rest[:colon]
            if _KEY_FULLMATCH(key) is None:
                return ("error", line_no, "invalid entry")
            after = rest[colon + 1 :]
            raw = after.strip(" ")
            if not raw:
                is_opener = True
                val = None
            elif after[0] == " ":
                is_opener = False
                val, err = _parse_scalar(raw, line_no)
                if err is not None:
                    return err
            else:
                return ("error", line_no, "invalid entry")
            kind = "dict"

        if root is None:
            if lead_len != 0:
                return ("error", line_no, "unexpected indent")
            if kind == "dict":
                root = {key: val}
                stack.append((0, "dict", root))
                if is_opener:
                    pending_opener = (0, root, key)
            else:
                root = [val]
                stack.append((0, "list", root))
                if is_opener:
                    pending_opener = (0, root, 0)
            continue

        if pending_opener is not None and lead_len > pending_opener[0]:
            _, parent, slot = pending_opener
            if kind == "dict":
                new_block = {key: val}
                parent[slot] = new_block
                stack.append((lead_len, "dict", new_block))
                pending_opener = (lead_len, new_block, key) if is_opener else None
            else:
                new_block = [val]
                parent[slot] = new_block
                stack.append((lead_len, "list", new_block))
                pending_opener = (lead_len, new_block, 0) if is_opener else None
            continue

        pending_opener = None
        top_indent = stack[-1][0]
        if lead_len > top_indent:
            return ("error", line_no, "unexpected indent")
        if lead_len < top_indent:
            while stack and stack[-1][0] > lead_len:
                stack.pop()
            if not stack or stack[-1][0] != lead_len:
                return ("error", line_no, "inconsistent dedent")

        _, block_kind, container = stack[-1]
        if kind != block_kind:
            return ("error", line_no, "mixed block")

        if kind == "dict":
            if key in container:
                return ("error", line_no, f"duplicate key '{key}'")
            container[key] = val
            if is_opener:
                pending_opener = (lead_len, container, key)
        else:
            container.append(val)
            if is_opener:
                pending_opener = (lead_len, container, len(container) - 1)

    return ("ok", root)

import re

_TOKEN_RE = re.compile(r'\[|\]|[^ \t\n\r\[\]]+')
_INT_RE = re.compile(r'-?[0-9]+\Z')

_OP_INT = 0
_OP_QUOT = 1
_OP_WORD = 2
_OP_DUP = 3
_OP_DROP = 4
_OP_SWAP = 5
_OP_OVER = 6
_OP_ROT = 7
_OP_ADD = 8
_OP_SUB = 9
_OP_MUL = 10
_OP_DIV = 11
_OP_MOD = 12
_OP_LT = 13
_OP_EQ = 14
_OP_IF = 15
_OP_TIMES = 16
_OP_WHILE = 17
_OP_CALL = 18
_OP_DIP = 19
_OP_DEF = 20

_BUILTINS = {
    "dup": _OP_DUP,
    "drop": _OP_DROP,
    "swap": _OP_SWAP,
    "over": _OP_OVER,
    "rot": _OP_ROT,
    "+": _OP_ADD,
    "-": _OP_SUB,
    "*": _OP_MUL,
    "/": _OP_DIV,
    "%": _OP_MOD,
    "<": _OP_LT,
    "=": _OP_EQ,
    "if": _OP_IF,
    "times": _OP_TIMES,
    "while": _OP_WHILE,
    "call": _OP_CALL,
    "dip": _OP_DIP,
}

_BAD_NAMES = frozenset(_BUILTINS) | frozenset(("[", "]", ":", ";"))

_FR_SEQ = 0
_FR_DIP = 1
_FR_TIMES = 2
_FR_WHILE = 3


class _Quotation:
    __slots__ = ("code", "tokens", "res")

    def __init__(self, code, tokens):
        self.code = code
        self.tokens = tokens
        self.res = None


def _parse_int(tok: str) -> int:
    if len(tok) <= 4000:
        return int(tok)
    neg = tok[0] == "-"
    s = tok[1:] if neg else tok
    val = 0
    chunk = 1000
    base = 10 ** chunk
    for i in range(0, len(s), chunk):
        part = s[i:i + chunk]
        if len(part) == chunk:
            val = val * base + int(part)
        else:
            val = val * (10 ** len(part)) + int(part)
    return -val if neg else val


def _to_result_list(q: _Quotation) -> list:
    if q.res is not None:
        return q.res
    work = [(q, False)]
    while work:
        cur, done = work.pop()
        if cur.res is not None:
            continue
        if done:
            cur.res = [t.res if type(t) is _Quotation else t for t in cur.tokens]
        else:
            work.append((cur, True))
            for t in cur.tokens:
                if type(t) is _Quotation and t.res is None:
                    work.append((t, False))
    return q.res


def run_pile(src: str, max_steps: int) -> tuple:
    tokens = _TOKEN_RE.findall(src)
    n = len(tokens)

    top_code = []
    open_stack = []
    active_code = top_code
    active_tokens = None

    builtins_get = _BUILTINS.get
    int_match = _INT_RE.match
    bad_names = _BAD_NAMES

    i = 0
    while i < n:
        tok = tokens[i]
        if tok == "[":
            new_code = []
            new_tokens = []
            open_stack.append(("[", i, new_code, new_tokens))
            active_code = new_code
            active_tokens = new_tokens
        elif tok == "]":
            if not open_stack or open_stack[-1][0] != "[":
                return ("error", i, "unmatched ]")
            _, open_idx, q_code, q_tokens = open_stack.pop()
            q = _Quotation(q_code, q_tokens)
            if not open_stack:
                active_code = top_code
                active_tokens = None
            elif open_stack[-1][0] == "[":
                active_code = open_stack[-1][2]
                active_tokens = open_stack[-1][3]
            else:
                active_code = open_stack[-1][3]
                active_tokens = None
            active_code.append((_OP_QUOT, open_idx, q))
            if active_tokens is not None:
                active_tokens.append(q)
        elif tok == ":":
            if open_stack:
                return ("error", i, "misplaced :")
            if i + 1 >= n:
                return ("error", i, "unclosed :")
            name = tokens[i + 1]
            if name in bad_names or int_match(name):
                return ("error", i + 1, "bad name")
            def_code = []
            open_stack.append((":", i, name, def_code))
            active_code = def_code
            active_tokens = None
            i += 1
        elif tok == ";":
            if not open_stack or open_stack[-1][0] != ":":
                return ("error", i, "unmatched ;")
            _, open_idx, name, def_code = open_stack.pop()
            active_code = top_code
            active_tokens = None
            top_code.append((_OP_DEF, open_idx, (name, def_code)))
        else:
            if active_tokens is not None:
                active_tokens.append(tok)
            b_op = builtins_get(tok)
            if b_op is not None:
                active_code.append((b_op, i, None))
            elif int_match(tok):
                active_code.append((_OP_INT, i, _parse_int(tok)))
            else:
                active_code.append((_OP_WORD, i, tok))
        i += 1

    if open_stack:
        kind, open_idx = open_stack[0][0], open_stack[0][1]
        if kind == "[":
            return ("error", open_idx, "unclosed [")
        return ("error", open_idx, "unclosed :")

    stack = []
    stack_append = stack.append
    stack_pop = stack.pop
    defs = {}
    frames = []
    frames_append = frames.append
    frames_pop = frames.pop

    code = top_code
    pc = 0
    code_len = len(code)
    steps = 0

    while True:
        while pc < code_len:
            op, idx, arg = code[pc]
            pc += 1
            steps += 1
            if steps > max_steps:
                return ("error", idx, "step limit exceeded")

            if op <= 2:
                if op == _OP_WORD:
                    body = defs.get(arg)
                    if body is None:
                        return ("error", idx, f"unknown word '{arg}'")
                    b_len = len(body)
                    if b_len > 0:
                        if pc < code_len:
                            frames_append((_FR_SEQ, code, pc, code_len))
                        code = body
                        pc = 0
                        code_len = b_len
                else:
                    stack_append(arg)
            elif op < 10:
                if op == _OP_DUP:
                    if not stack:
                        return ("error", idx, "stack underflow")
                    stack_append(stack[-1])
                elif op == _OP_DROP:
                    if not stack:
                        return ("error", idx, "stack underflow")
                    stack_pop()
                elif op == _OP_SWAP:
                    if len(stack) < 2:
                        return ("error", idx, "stack underflow")
                    stack[-2], stack[-1] = stack[-1], stack[-2]
                elif op == _OP_OVER:
                    if len(stack) < 2:
                        return ("error", idx, "stack underflow")
                    stack_append(stack[-2])
                elif op == _OP_ROT:
                    if len(stack) < 3:
                        return ("error", idx, "stack underflow")
                    stack[-3], stack[-2], stack[-1] = stack[-2], stack[-1], stack[-3]
                elif op == _OP_ADD:
                    if len(stack) < 2:
                        return ("error", idx, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int or type(b) is not int:
                        return ("error", idx, "type error")
                    stack_pop()
                    stack[-1] = a + b
                else:  # _OP_SUB
                    if len(stack) < 2:
                        return ("error", idx, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int or type(b) is not int:
                        return ("error", idx, "type error")
                    stack_pop()
                    stack[-1] = a - b
            elif op < 15:
                if len(stack) < 2:
                    return ("error", idx, "stack underflow")
                b = stack[-1]
                a = stack[-2]
                if type(a) is not int or type(b) is not int:
                    return ("error", idx, "type error")
                if op == _OP_MUL:
                    stack_pop()
                    stack[-1] = a * b
                elif op == _OP_DIV:
                    if b == 0:
                        return ("error", idx, "division by zero")
                    stack_pop()
                    stack[-1] = a // b
                elif op == _OP_MOD:
                    if b == 0:
                        return ("error", idx, "division by zero")
                    stack_pop()
                    stack[-1] = a % b
                elif op == _OP_LT:
                    stack_pop()
                    stack[-1] = 1 if a < b else 0
                else:  # _OP_EQ
                    stack_pop()
                    stack[-1] = 1 if a == b else 0
            else:
                if op == _OP_IF:
                    if len(stack) < 3:
                        return ("error", idx, "stack underflow")
                    f = stack[-1]
                    t = stack[-2]
                    c = stack[-3]
                    if type(c) is not int or type(t) is not _Quotation or type(f) is not _Quotation:
                        return ("error", idx, "type error")
                    del stack[-3:]
                    chosen = t.code if c != 0 else f.code
                    c_len = len(chosen)
                    if c_len > 0:
                        if pc < code_len:
                            frames_append((_FR_SEQ, code, pc, code_len))
                        code = chosen
                        pc = 0
                        code_len = c_len
                elif op == _OP_TIMES:
                    if len(stack) < 2:
                        return ("error", idx, "stack underflow")
                    count = stack[-1]
                    q = stack[-2]
                    if type(q) is not _Quotation or type(count) is not int:
                        return ("error", idx, "type error")
                    if count < 0:
                        return ("error", idx, "negative count")
                    del stack[-2:]
                    q_code = q.code
                    q_len = len(q_code)
                    if q_len > 0 and count > 0:
                        if count == 1:
                            if pc < code_len:
                                frames_append((_FR_SEQ, code, pc, code_len))
                        else:
                            frames_append([_FR_TIMES, q_code, count - 1, code, pc, code_len])
                        code = q_code
                        pc = 0
                        code_len = q_len
                elif op == _OP_WHILE:
                    if len(stack) < 2:
                        return ("error", idx, "stack underflow")
                    b = stack[-1]
                    c = stack[-2]
                    if type(c) is not _Quotation or type(b) is not _Quotation:
                        return ("error", idx, "type error")
                    del stack[-2:]
                    c_code = c.code
                    frames_append([_FR_WHILE, 0, c_code, b.code, idx, code, pc, code_len])
                    code = c_code
                    pc = 0
                    code_len = len(c_code)
                elif op == _OP_CALL:
                    if not stack:
                        return ("error", idx, "stack underflow")
                    q = stack[-1]
                    if type(q) is not _Quotation:
                        return ("error", idx, "type error")
                    stack_pop()
                    q_code = q.code
                    q_len = len(q_code)
                    if q_len > 0:
                        if pc < code_len:
                            frames_append((_FR_SEQ, code, pc, code_len))
                        code = q_code
                        pc = 0
                        code_len = q_len
                elif op == _OP_DIP:
                    if len(stack) < 2:
                        return ("error", idx, "stack underflow")
                    q = stack[-1]
                    a = stack[-2]
                    if type(q) is not _Quotation:
                        return ("error", idx, "type error")
                    del stack[-2:]
                    q_code = q.code
                    q_len = len(q_code)
                    if q_len == 0:
                        stack_append(a)
                    else:
                        frames_append((_FR_DIP, a, code, pc, code_len))
                        code = q_code
                        pc = 0
                        code_len = q_len
                else:  # _OP_DEF
                    defs[arg[0]] = arg[1]

        if not frames:
            break
        frame = frames[-1]
        ft = frame[0]
        if ft == _FR_SEQ:
            frames_pop()
            _, code, pc, code_len = frame
        elif ft == _FR_DIP:
            frames_pop()
            _, a, code, pc, code_len = frame
            stack_append(a)
        elif ft == _FR_TIMES:
            rem = frame[2]
            if rem > 0:
                frame[2] = rem - 1
                code = frame[1]
                pc = 0
                code_len = len(code)
            else:
                frames_pop()
                code = frame[3]
                pc = frame[4]
                code_len = frame[5]
        else:  # _FR_WHILE
            if frame[1] == 0:
                if not stack:
                    return ("error", frame[4], "stack underflow")
                v = stack_pop()
                if type(v) is not int:
                    return ("error", frame[4], "type error")
                if v == 0:
                    frames_pop()
                    code = frame[5]
                    pc = frame[6]
                    code_len = frame[7]
                else:
                    frame[1] = 1
                    code = frame[3]
                    pc = 0
                    code_len = len(code)
            else:
                frame[1] = 0
                code = frame[2]
                pc = 0
                code_len = len(code)

    for idx_s, val in enumerate(stack):
        if type(val) is _Quotation:
            stack[idx_s] = _to_result_list(val)

    return ("ok", stack)

_KEYWORDS = frozenset(("and", "or", "not", "in", "has"))

# Parser stack states
_ST_END = 0
_ST_OR = 1
_ST_AFTER_OR = 2
_ST_MAKE_OR = 3
_ST_AND = 4
_ST_AFTER_AND = 5
_ST_MAKE_AND = 6
_ST_NOT = 7
_ST_MAKE_NOT = 8
_ST_PRIMARY = 9
_ST_RPAREN = 10

# Bytecode opcodes (truth values: 0=FALSE, 1=UNKNOWN, 2=TRUE)
_OP_HAS = 0
_OP_EQ = 1
_OP_NE = 2
_OP_LT = 3
_OP_LE = 4
_OP_GT = 5
_OP_GE = 6
_OP_IN = 7
_OP_NOT = 8
_OP_AND_SHORT = 9
_OP_AND_JOIN = 10
_OP_OR_SHORT = 11
_OP_OR_JOIN = 12

_CMP_OPS = {
    "=": _OP_EQ,
    "!=": _OP_NE,
    "<": _OP_LT,
    "<=": _OP_LE,
    ">": _OP_GT,
    ">=": _OP_GE,
}

_MISSING = object()


def _parse_int(s: str) -> int:
    if len(s) <= 4000:
        return int(s)
    # Chunked conversion avoids Python 3.11+ int_max_str_digits ValueError.
    neg = s[0] == "-"
    i = 1 if neg else 0
    n = len(s)
    base = 10**1000
    val = 0
    while i < n:
        end = i + 1000
        if end <= n:
            val = val * base + int(s[i:end])
            i = end
        else:
            val = val * (10 ** (n - i)) + int(s[i:n])
            break
    return -val if neg else val


def _tokenize(query: str):
    tokens = []
    n = len(query)
    i = 0

    while i < n:
        c = query[i]
        if c == " " or c == "\t" or c == "\n":
            i += 1
            continue

        if c in "()[],":
            tokens.append((c, i, c, None))
            i += 1
            continue

        if c == "!":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(("CMP", i, "!=", "!="))
                i += 2
                continue
            return None, ("error", i, "unexpected character '!'")

        if c == "<":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(("CMP", i, "<=", "<="))
                i += 2
            else:
                tokens.append(("CMP", i, "<", "<"))
                i += 1
            continue

        if c == ">":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(("CMP", i, ">=", ">="))
                i += 2
            else:
                tokens.append(("CMP", i, ">", ">"))
                i += 1
            continue

        if c == "=":
            tokens.append(("CMP", i, "=", "="))
            i += 1
            continue

        if ("0" <= c <= "9") or c == "-":
            start = i
            if c == "-":
                if i + 1 >= n or not ("0" <= query[i + 1] <= "9"):
                    return None, ("error", i, "unexpected character '-'")
                i += 2
            else:
                i += 1
            while i < n and "0" <= query[i] <= "9":
                i += 1
            raw = query[start:i]
            tokens.append(("INT", start, raw, _parse_int(raw)))
            continue

        if c == '"':
            start = i
            i += 1
            chars = []
            while True:
                if i >= n:
                    return None, ("error", start, "unterminated string")
                ch = query[i]
                if ch == '"':
                    i += 1
                    break
                if ch == "\\":
                    if i + 1 >= n:
                        return None, ("error", i, "bad escape")
                    nxt = query[i + 1]
                    if nxt != '"' and nxt != "\\":
                        return None, ("error", i, "bad escape")
                    chars.append(nxt)
                    i += 2
                else:
                    chars.append(ch)
                    i += 1
            raw = query[start:i]
            tokens.append(("STRING", start, raw, "".join(chars)))
            continue

        if ("A" <= c <= "Z") or ("a" <= c <= "z") or c == "_":
            start = i
            i += 1
            while i < n:
                ch = query[i]
                if (
                    ("A" <= ch <= "Z")
                    or ("a" <= ch <= "z")
                    or ("0" <= ch <= "9")
                    or ch == "_"
                    or ch == "."
                ):
                    i += 1
                else:
                    break
            raw = query[start:i]
            if raw in _KEYWORDS:
                tokens.append((raw, start, raw, None))
            else:
                tokens.append(("FIELD", start, raw, raw))
            continue

        return None, ("error", i, f"unexpected character '{c}'")

    tokens.append(("END", n, "", None))
    return tokens, None


def _syntax_err(tok):
    kind, pos, raw, _ = tok
    if kind == "END":
        return ("error", pos, "unexpected end of input")
    return ("error", pos, f"unexpected token '{raw}'")


def _parse(tokens):
    stack = [_ST_END, _ST_OR]
    vals = []
    pos = 0

    while stack:
        st = stack.pop()
        if st == _ST_OR:
            stack.append(_ST_AFTER_OR)
            stack.append(_ST_AND)
        elif st == _ST_AFTER_OR:
            if tokens[pos][0] == "or":
                pos += 1
                stack.append(_ST_AFTER_OR)
                stack.append(_ST_MAKE_OR)
                stack.append(_ST_AND)
        elif st == _ST_MAKE_OR:
            right = vals.pop()
            left = vals.pop()
            vals.append(("or", left, right))
        elif st == _ST_AND:
            stack.append(_ST_AFTER_AND)
            stack.append(_ST_NOT)
        elif st == _ST_AFTER_AND:
            if tokens[pos][0] == "and":
                pos += 1
                stack.append(_ST_AFTER_AND)
                stack.append(_ST_MAKE_AND)
                stack.append(_ST_NOT)
        elif st == _ST_MAKE_AND:
            right = vals.pop()
            left = vals.pop()
            vals.append(("and", left, right))
        elif st == _ST_NOT:
            parity = 0
            while tokens[pos][0] == "not":
                pos += 1
                parity ^= 1
            if parity:
                stack.append(_ST_MAKE_NOT)
            stack.append(_ST_PRIMARY)
        elif st == _ST_MAKE_NOT:
            vals.append(("not", vals.pop()))
        elif st == _ST_PRIMARY:
            tok = tokens[pos]
            kind = tok[0]
            if kind == "(":
                pos += 1
                stack.append(_ST_RPAREN)
                stack.append(_ST_OR)
            elif kind == "has":
                pos += 1
                ftok = tokens[pos]
                if ftok[0] != "FIELD":
                    return None, _syntax_err(ftok)
                pos += 1
                vals.append(("has", ftok[3]))
            elif kind == "FIELD":
                field = tok[3]
                pos += 1
                op_tok = tokens[pos]
                op_kind = op_tok[0]
                if op_kind == "CMP":
                    op = op_tok[3]
                    pos += 1
                    ltok = tokens[pos]
                    if ltok[0] != "INT" and ltok[0] != "STRING":
                        return None, _syntax_err(ltok)
                    pos += 1
                    vals.append(("cmp", field, op, ltok[3]))
                elif op_kind == "in":
                    pos += 1
                    btok = tokens[pos]
                    if btok[0] != "[":
                        return None, _syntax_err(btok)
                    pos += 1
                    ltok = tokens[pos]
                    if ltok[0] != "INT" and ltok[0] != "STRING":
                        return None, _syntax_err(ltok)
                    items = [ltok[3]]
                    pos += 1
                    while tokens[pos][0] == ",":
                        pos += 1
                        ltok = tokens[pos]
                        if ltok[0] != "INT" and ltok[0] != "STRING":
                            return None, _syntax_err(ltok)
                        items.append(ltok[3])
                        pos += 1
                    ctok = tokens[pos]
                    if ctok[0] != "]":
                        return None, _syntax_err(ctok)
                    pos += 1
                    vals.append(("in", field, frozenset(items)))
                else:
                    return None, _syntax_err(op_tok)
            else:
                return None, _syntax_err(tok)
        elif st == _ST_RPAREN:
            tok = tokens[pos]
            if tok[0] != ")":
                return None, _syntax_err(tok)
            pos += 1
        elif st == _ST_END:
            tok = tokens[pos]
            if tok[0] != "END":
                return None, _syntax_err(tok)

    return vals[0], None


def _compile(ast):
    code = []
    work = [(0, ast)]
    patch_stack = []

    while work:
        act, data = work.pop()
        if act == 0:
            tag = data[0]
            if tag == "has":
                code.append((_OP_HAS, data[1]))
            elif tag == "cmp":
                _, field, op, lit = data
                code.append((_CMP_OPS[op], field, lit, type(lit)))
            elif tag == "in":
                code.append((_OP_IN, data[1], data[2]))
            elif tag == "not":
                child = data[1]
                if child[0] == "not":
                    work.append((0, child[1]))
                else:
                    work.append((1, (_OP_NOT,)))
                    work.append((0, child))
            elif tag == "and":
                work.append((3, _OP_AND_SHORT))
                work.append((1, (_OP_AND_JOIN,)))
                work.append((0, data[2]))
                work.append((2, _OP_AND_SHORT))
                work.append((0, data[1]))
            elif tag == "or":
                work.append((3, _OP_OR_SHORT))
                work.append((1, (_OP_OR_JOIN,)))
                work.append((0, data[2]))
                work.append((2, _OP_OR_SHORT))
                work.append((0, data[1]))
        elif act == 1:
            code.append(data)
        elif act == 2:
            patch_stack.append(len(code))
            code.append((data, 0))
        else:
            idx = patch_stack.pop()
            code[idx] = (data, len(code))

    return code


def _eval_records(code, records: list[dict]) -> list[int]:
    n_code = len(code)
    indices = []
    missing = _MISSING
    stack = []
    append_idx = indices.append
    pop = stack.pop
    push = stack.append

    for idx, rec in enumerate(records):
        stack.clear()
        pc = 0
        rec_get = rec.get
        while pc < n_code:
            instr = code[pc]
            op = instr[0]
            if op == _OP_HAS:
                push(2 if instr[1] in rec else 0)
                pc += 1
            elif op == _OP_EQ:
                val = rec_get(instr[1], missing)
                if val is missing:
                    push(1)
                elif type(val) is instr[3]:
                    push(2 if val == instr[2] else 0)
                else:
                    push(0)
                pc += 1
            elif op == _OP_NE:
                val = rec_get(instr[1], missing)
                if val is missing:
                    push(1)
                elif type(val) is instr[3]:
                    push(2 if val != instr[2] else 0)
                else:
                    push(2)
                pc += 1
            elif op == _OP_LT:
                val = rec_get(instr[1], missing)
                if val is missing or type(val) is not instr[3]:
                    push(1)
                else:
                    push(2 if val < instr[2] else 0)
                pc += 1
            elif op == _OP_LE:
                val = rec_get(instr[1], missing)
                if val is missing or type(val) is not instr[3]:
                    push(1)
                else:
                    push(2 if val <= instr[2] else 0)
                pc += 1
            elif op == _OP_GT:
                val = rec_get(instr[1], missing)
                if val is missing or type(val) is not instr[3]:
                    push(1)
                else:
                    push(2 if val > instr[2] else 0)
                pc += 1
            elif op == _OP_GE:
                val = rec_get(instr[1], missing)
                if val is missing or type(val) is not instr[3]:
                    push(1)
                else:
                    push(2 if val >= instr[2] else 0)
                pc += 1
            elif op == _OP_IN:
                val = rec_get(instr[1], missing)
                if val is missing:
                    push(1)
                else:
                    push(2 if val in instr[2] else 0)
                pc += 1
            elif op == _OP_NOT:
                stack[-1] = 2 - stack[-1]
                pc += 1
            elif op == _OP_AND_SHORT:
                if stack[-1] == 0:
                    pc = instr[1]
                else:
                    pc += 1
            elif op == _OP_AND_JOIN:
                b = pop()
                if b < stack[-1]:
                    stack[-1] = b
                pc += 1
            elif op == _OP_OR_SHORT:
                if stack[-1] == 2:
                    pc = instr[1]
                else:
                    pc += 1
            else:  # _OP_OR_JOIN
                b = pop()
                if b > stack[-1]:
                    stack[-1] = b
                pc += 1

        if stack[0] == 2:
            append_idx(idx)

    return indices


def filter_records(query: str, records: list[dict]) -> tuple:
    tokens, err = _tokenize(query)
    if err is not None:
        return err

    ast, err = _parse(tokens)
    if err is not None:
        return err

    code = _compile(ast)
    return ("ok", _eval_records(code, records))

package main

import "sort"

type Tuple1 struct {
	F0 string
	F1 int
}

type playerState struct {
	score int
	rank  int
}

func LeaderboardRanks(submissions []Tuple1) []int {
	n := len(submissions)
	res := make([]int, n)
	if n == 0 {
		return res
	}

	order := make([]int, n)
	for i := 0; i < n; i++ {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		a, b := order[i], order[j]
		sa, sb := submissions[a].F1, submissions[b].F1
		if sa != sb {
			return sa > sb
		}
		return a < b
	})

	rankOf := make([]int, n)
	for pos, idx := range order {
		rankOf[idx] = pos + 1
	}

	bit := make([]int, n+1)
	add := func(idx, delta int) {
		for ; idx <= n; idx += idx & -idx {
			bit[idx] += delta
		}
	}
	query := func(idx int) int {
		sum := 0
		for ; idx > 0; idx -= idx & -idx {
			sum += bit[idx]
		}
		return sum
	}

	players := make(map[string]playerState)
	for i, sub := range submissions {
		name, score := sub.F0, sub.F1
		r := rankOf[i]
		st, exists := players[name]
		if !exists {
			players[name] = playerState{score: score, rank: r}
			add(r, 1)
			res[i] = query(r)
		} else if score > st.score {
			add(st.rank, -1)
			players[name] = playerState{score: score, rank: r}
			add(r, 1)
			res[i] = query(r)
		} else {
			res[i] = query(st.rank)
		}
	}

	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1) {}

    public static List<Long> leaderboardRanks(List<Tuple1> submissions) {
        int n = submissions.size();
        if (n == 0) {
            return new ArrayList<>();
        }

        String[] players = new String[n];
        long[] scores = new long[n];
        Integer[] order = new Integer[n];
        int idx = 0;
        for (Tuple1 sub : submissions) {
            players[idx] = sub.f0();
            scores[idx] = sub.f1();
            order[idx] = idx;
            idx++;
        }

        Arrays.sort(order, (a, b) -> {
            int cmp = Long.compare(scores[b], scores[a]);
            return cmp != 0 ? cmp : Integer.compare(a, b);
        });

        int[] pos = new int[n];
        for (int i = 0; i < n; i++) {
            pos[order[i]] = i + 1;
        }

        int[] bit = new int[n + 1];
        Map<String, Integer> bestIdxMap = HashMap.newHashMap(n);
        List<Long> result = new ArrayList<>(n);

        for (int i = 0; i < n; i++) {
            String player = players[i];
            long score = scores[i];
            Integer prevIdx = bestIdxMap.get(player);
            int curIdx;

            if (prevIdx == null) {
                add(bit, n, pos[i], 1);
                bestIdxMap.put(player, i);
                curIdx = i;
            } else if (score > scores[prevIdx]) {
                add(bit, n, pos[prevIdx], -1);
                add(bit, n, pos[i], 1);
                bestIdxMap.put(player, i);
                curIdx = i;
            } else {
                curIdx = prevIdx;
            }

            result.add((long) query(bit, pos[curIdx]));
        }

        return result;
    }

    private static void add(int[] bit, int n, int i, int delta) {
        for (; i <= n; i += i & -i) {
            bit[i] += delta;
        }
    }

    private static int query(int[] bit, int i) {
        int sum = 0;
        for (; i > 0; i -= i & -i) {
            sum += bit[i];
        }
        return sum;
    }
}

#include <algorithm>
#include <numeric>
#include <string>
#include <string_view>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<long long> leaderboard_ranks(
    const std::vector<std::tuple<std::string, long long>>& submissions) {
    const long long n = static_cast<long long>(submissions.size());
    std::vector<long long> result(n);
    if (n == 0) {
        return result;
    }

    std::vector<long long> order(n);
    std::iota(order.begin(), order.end(), 0LL);
    std::sort(order.begin(), order.end(), [&](long long a, long long b) {
        long long score_a = std::get<1>(submissions[a]);
        long long score_b = std::get<1>(submissions[b]);
        if (score_a != score_b) {
            return score_a > score_b;
        }
        return a < b;
    });

    std::vector<long long> pos(n);
    for (long long rank_idx = 0; rank_idx < n; ++rank_idx) {
        pos[order[rank_idx]] = rank_idx;
    }

    std::vector<long long> bit(n + 1, 0);
    auto add = [&](long long idx, long long delta) {
        for (long long x = idx + 1; x <= n; x += x & -x) {
            bit[x] += delta;
        }
    };
    auto prefix_sum = [&](long long idx) -> long long {
        long long sum = 0;
        for (long long x = idx + 1; x > 0; x -= x & -x) {
            sum += bit[x];
        }
        return sum;
    };

    std::unordered_map<std::string_view, long long> best_idx;
    best_idx.reserve(static_cast<std::size_t>(n));

    for (long long i = 0; i < n; ++i) {
        const auto& [player, score] = submissions[i];
        std::string_view player_view(player);

        auto it = best_idx.find(player_view);
        long long cur_pos = 0;
        if (it == best_idx.end()) {
            best_idx.emplace(player_view, i);
            cur_pos = pos[i];
            add(cur_pos, 1);
        } else {
            long long old_idx = it->second;
            long long old_best = std::get<1>(submissions[old_idx]);
            if (score > old_best) {
                add(pos[old_idx], -1);
                it->second = i;
                cur_pos = pos[i];
                add(cur_pos, 1);
            } else {
                cur_pos = pos[old_idx];
            }
        }

        result[i] = prefix_sum(cur_pos);
    }

    return result;
}

export function leaderboardRanks(submissions: [string, number][]): number[] {
  const n = submissions.length;
  if (n === 0) {
    return [];
  }

  const stateScore = new Float64Array(n);
  const stateTime = new Int32Array(n);
  const removeState = new Int32Array(n);
  const addState = new Int32Array(n);
  const queryState = new Int32Array(n);

  const playerState = new Map<string, number>();
  let m = 0;

  for (let i = 0; i < n; i++) {
    const sub = submissions[i];
    const player = sub[0];
    const score = sub[1];
    const prevState = playerState.get(player);

    if (prevState === undefined) {
      const k = m++;
      stateScore[k] = score;
      stateTime[k] = i;
      playerState.set(player, k);
      removeState[i] = -1;
      addState[i] = k;
      queryState[i] = k;
    } else if (score > stateScore[prevState]) {
      const k = m++;
      stateScore[k] = score;
      stateTime[k] = i;
      playerState.set(player, k);
      removeState[i] = prevState;
      addState[i] = k;
      queryState[i] = k;
    } else {
      removeState[i] = -1;
      addState[i] = -1;
      queryState[i] = prevState;
    }
  }

  const order = new Int32Array(m);
  for (let k = 0; k < m; k++) {
    order[k] = k;
  }

  order.sort((a, b) => {
    const sa = stateScore[a];
    const sb = stateScore[b];
    if (sa !== sb) {
      return sa > sb ? -1 : 1;
    }
    return stateTime[a] - stateTime[b];
  });

  const pos = new Int32Array(m);
  for (let p = 0; p < m; p++) {
    pos[order[p]] = p + 1;
  }

  const bit = new Int32Array(m + 1);
  const result = new Array<number>(n);

  for (let i = 0; i < n; i++) {
    const rem = removeState[i];
    if (rem !== -1) {
      for (let x = pos[rem]; x <= m; x += x & -x) {
        bit[x] -= 1;
      }
    }

    const add = addState[i];
    if (add !== -1) {
      for (let x = pos[add]; x <= m; x += x & -x) {
        bit[x] += 1;
      }
    }

    let rank = 0;
    for (let x = pos[queryState[i]]; x > 0; x -= x & -x) {
      rank += bit[x];
    }
    result[i] = rank;
  }

  return result;
}

package main

import "sort"

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type pstNode struct {
	left  int32
	right int32
	count int32
	sum   int64
}

func BudgetPurchases(prices []int, queries []Tuple1) []Tuple2 {
	if len(queries) == 0 {
		return []Tuple2{}
	}
	n := len(prices)
	if n == 0 {
		return make([]Tuple2, len(queries))
	}

	sorted := make([]int, n)
	copy(sorted, prices)
	sort.Ints(sorted)

	unique := sorted[:0]
	for _, p := range sorted {
		if len(unique) == 0 || unique[len(unique)-1] != p {
			unique = append(unique, p)
		}
	}
	u := len(unique)

	nodes := make([]pstNode, 1, 1+n*19)
	roots := make([]int32, n+1)

	for i, p := range prices {
		rank := sort.SearchInts(unique, p)
		prev := roots[i]
		newRoot := int32(len(nodes))
		nodes = append(nodes, nodes[prev])
		curr := newRoot
		l, r := 0, u-1
		val := int64(p)
		for l < r {
			nodes[curr].count++
			nodes[curr].sum += val
			mid := (l + r) >> 1
			if rank <= mid {
				nextNew := int32(len(nodes))
				nodes = append(nodes, nodes[nodes[curr].left])
				nodes[curr].left = nextNew
				curr = nextNew
				r = mid
			} else {
				nextNew := int32(len(nodes))
				nodes = append(nodes, nodes[nodes[curr].right])
				nodes[curr].right = nextNew
				curr = nextNew
				l = mid + 1
			}
		}
		nodes[curr].count++
		nodes[curr].sum += val
		roots[i+1] = newRoot
	}

	ans := make([]Tuple2, len(queries))
	for i, q := range queries {
		budget := int64(q.F2)
		if budget <= 0 {
			continue
		}
		lNode := roots[q.F0]
		rNode := roots[q.F1+1]
		var totalCount int
		var totalSum int64
		l, r := 0, u-1
		for l < r {
			if budget == 0 || nodes[rNode].count == nodes[lNode].count {
				break
			}
			mid := (l + r) >> 1
			rLeft := nodes[rNode].left
			lLeft := nodes[lNode].left
			leftCount := nodes[rLeft].count - nodes[lLeft].count
			leftSum := nodes[rLeft].sum - nodes[lLeft].sum
			if leftSum <= budget {
				totalCount += int(leftCount)
				totalSum += leftSum
				budget -= leftSum
				lNode = nodes[lNode].right
				rNode = nodes[rNode].right
				l = mid + 1
			} else {
				lNode = lLeft
				rNode = rLeft
				r = mid
			}
		}
		if l == r && budget > 0 {
			nodeCount := int(nodes[rNode].count - nodes[lNode].count)
			if nodeCount > 0 {
				val := int64(unique[l])
				take := int(budget / val)
				if take > nodeCount {
					take = nodeCount
				}
				totalCount += take
				totalSum += int64(take) * val
			}
		}
		ans[i] = Tuple2{F0: totalCount, F1: int(totalSum)}
	}

	return ans
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2) {}

    public record Tuple2(long f0, long f1) {}

    public static List<Tuple2> budgetPurchases(List<Long> prices, List<Tuple1> queries) {
        if (queries.isEmpty()) {
            return new ArrayList<>();
        }

        int n = prices.size();
        long[] p = new long[n];
        long[] sorted = new long[n];
        for (int i = 0; i < n; i++) {
            long v = prices.get(i);
            p[i] = v;
            sorted[i] = v;
        }

        Arrays.sort(sorted);
        long[] val = new long[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                val[m++] = sorted[i];
            }
        }

        int levels = (m <= 1) ? 1 : (33 - Integer.numberOfLeadingZeros(m - 1));
        int maxNodes = n * (levels + 1) + 2;

        int[] left = new int[maxNodes];
        int[] right = new int[maxNodes];
        int[] cnt = new int[maxNodes];
        long[] sum = new long[maxNodes];
        int[] roots = new int[n + 1];
        int nodeCnt = 0;

        for (int i = 0; i < n; i++) {
            long price = p[i];
            int idx = Arrays.binarySearch(val, 0, m, price);
            int newRoot = ++nodeCnt;
            roots[i + 1] = newRoot;

            int curNew = newRoot;
            int curOld = roots[i];
            int lo = 0;
            int hi = m - 1;
            while (lo < hi) {
                cnt[curNew] = cnt[curOld] + 1;
                sum[curNew] = sum[curOld] + price;
                int mid = (lo + hi) >>> 1;
                if (idx <= mid) {
                    right[curNew] = right[curOld];
                    int nxt = ++nodeCnt;
                    left[curNew] = nxt;
                    curNew = nxt;
                    curOld = left[curOld];
                    hi = mid;
                } else {
                    left[curNew] = left[curOld];
                    int nxt = ++nodeCnt;
                    right[curNew] = nxt;
                    curNew = nxt;
                    curOld = right[curOld];
                    lo = mid + 1;
                }
            }
            cnt[curNew] = cnt[curOld] + 1;
            sum[curNew] = sum[curOld] + price;
        }

        List<Tuple2> ans = new ArrayList<>(queries.size());
        for (int qi = 0, qn = queries.size(); qi < qn; qi++) {
            Tuple1 q = queries.get(qi);
            int l = (int) q.f0();
            int r = (int) q.f1();
            long rem = q.f2();

            if (rem <= 0) {
                ans.add(new Tuple2(0L, 0L));
                continue;
            }

            int L = roots[l];
            int R = roots[r + 1];
            long totalSum = sum[R] - sum[L];
            if (totalSum <= rem) {
                ans.add(new Tuple2(cnt[R] - cnt[L], totalSum));
                continue;
            }

            long bought = 0;
            long spent = 0;
            int lo = 0;
            int hi = m - 1;
            while (lo < hi && rem > 0) {
                int mid = (lo + hi) >>> 1;
                int ll = left[L];
                int rl = left[R];
                long leftSum = sum[rl] - sum[ll];
                if (leftSum <= rem) {
                    bought += cnt[rl] - cnt[ll];
                    spent += leftSum;
                    rem -= leftSum;
                    L = right[L];
                    R = right[R];
                    lo = mid + 1;
                } else {
                    L = ll;
                    R = rl;
                    hi = mid;
                }
            }

            if (lo == hi && rem > 0) {
                long c = cnt[R] - cnt[L];
                if (c > 0) {
                    long price = val[lo];
                    long k = Math.min(c, rem / price);
                    bought += k;
                    spent += k * price;
                }
            }

            ans.add(new Tuple2(bought, spent));
        }

        return ans;
    }
}

#include <algorithm>
#include <cstddef>
#include <tuple>
#include <vector>

std::vector<std::tuple<long long, long long>> budget_purchases(
    const std::vector<long long>& prices,
    const std::vector<std::tuple<long long, long long, long long>>& queries) {
    if (queries.empty()) {
        return {};
    }

    int n = static_cast<int>(prices.size());

    std::vector<long long> vals = prices;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int U = static_cast<int>(vals.size());

    struct Node {
        int left;
        int right;
        int cnt;
        long long sum;
    };

    std::vector<Node> nodes;
    nodes.reserve(static_cast<std::size_t>(n) * 19 + 1);
    nodes.push_back({0, 0, 0, 0});

    std::vector<int> roots(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        long long val = prices[i];
        int pos = static_cast<int>(std::lower_bound(vals.begin(), vals.end(), val) - vals.begin());
        int prev = roots[i];
        int root = static_cast<int>(nodes.size());
        int curr = root;
        int L = 0;
        int R = U - 1;
        while (true) {
            Node node = nodes[prev];
            node.cnt += 1;
            node.sum += val;
            nodes.push_back(node);
            if (L == R) {
                break;
            }
            int mid = L + (R - L) / 2;
            int next_idx = static_cast<int>(nodes.size());
            if (pos <= mid) {
                nodes[curr].left = next_idx;
                prev = nodes[prev].left;
                R = mid;
            } else {
                nodes[curr].right = next_idx;
                prev = nodes[prev].right;
                L = mid + 1;
            }
            curr = next_idx;
        }
        roots[i + 1] = root;
    }

    std::vector<std::tuple<long long, long long>> result;
    result.reserve(queries.size());

    for (const auto& [l, r, budget] : queries) {
        int vl = roots[static_cast<int>(l)];
        int vr = roots[static_cast<int>(r) + 1];
        int L = 0;
        int R = U - 1;
        long long rem = budget;
        long long ans_cnt = 0;
        long long ans_sum = 0;

        while (L < R) {
            if (vl == vr || rem == 0) {
                break;
            }
            int mid = L + (R - L) / 2;
            int l_vl = nodes[vl].left;
            int l_vr = nodes[vr].left;
            int left_cnt = nodes[l_vr].cnt - nodes[l_vl].cnt;
            long long left_sum = nodes[l_vr].sum - nodes[l_vl].sum;

            if (left_sum <= rem) {
                ans_cnt += left_cnt;
                ans_sum += left_sum;
                rem -= left_sum;
                vl = nodes[vl].right;
                vr = nodes[vr].right;
                L = mid + 1;
            } else {
                vl = l_vl;
                vr = l_vr;
                R = mid;
            }
        }

        if (L == R && vl != vr && rem > 0) {
            int leaf_cnt = nodes[vr].cnt - nodes[vl].cnt;
            if (leaf_cnt > 0) {
                long long price = vals[L];
                long long take = std::min<long long>(leaf_cnt, rem / price);
                ans_cnt += take;
                ans_sum += take * price;
            }
        }

        result.emplace_back(ans_cnt, ans_sum);
    }

    return result;
}

export function budgetPurchases(
  prices: number[],
  queries: [number, number, number][],
): [number, number][] {
  const qLen = queries.length;
  if (qLen === 0) {
    return [];
  }

  const n = prices.length;
  const sorted = Int32Array.from(prices).sort();

  const unique = new Int32Array(n);
  let m = 0;
  for (let i = 0; i < n; i++) {
    if (i === 0 || sorted[i] !== sorted[i - 1]) {
      unique[m++] = sorted[i];
    }
  }

  let levels = 1;
  while ((1 << levels) < m) {
    levels++;
  }
  const maxNodes = n * (levels + 2) + 5;

  const left = new Int32Array(maxNodes);
  const right = new Int32Array(maxNodes);
  const cnt = new Int32Array(maxNodes);
  const sum = new Float64Array(maxNodes);
  const roots = new Int32Array(n + 1);

  let nodeCount = 1;

  for (let i = 0; i < n; i++) {
    const val = prices[i];
    let lo = 0;
    let hi = m - 1;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (unique[mid] < val) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    const pos = lo;

    const newRoot = nodeCount++;
    roots[i + 1] = newRoot;

    let u = roots[i];
    let v = newRoot;
    lo = 0;
    hi = m - 1;
    while (lo < hi) {
      cnt[v] = cnt[u] + 1;
      sum[v] = sum[u] + val;
      const mid = (lo + hi) >>> 1;
      const child = nodeCount++;
      if (pos <= mid) {
        left[v] = child;
        right[v] = right[u];
        u = left[u];
        v = child;
        hi = mid;
      } else {
        left[v] = left[u];
        right[v] = child;
        u = right[u];
        v = child;
        lo = mid + 1;
      }
    }
    cnt[v] = cnt[u] + 1;
    sum[v] = sum[u] + val;
  }

  const ans: [number, number][] = new Array(qLen);

  for (let qi = 0; qi < qLen; qi++) {
    const q = queries[qi];
    const l = q[0];
    const r = q[1];
    const budget = q[2];

    let u = roots[l];
    let v = roots[r + 1];

    const totalSum = sum[v] - sum[u];
    if (totalSum <= budget) {
      ans[qi] = [cnt[v] - cnt[u], totalSum];
      continue;
    }

    let count = 0;
    let spent = 0;
    let rem = budget;
    let lo = 0;
    let hi = m - 1;

    while (lo < hi && rem > 0 && u !== v) {
      const mid = (lo + hi) >>> 1;
      const lu = left[u];
      const lv = left[v];
      const ls = sum[lv] - sum[lu];
      if (ls <= rem) {
        count += cnt[lv] - cnt[lu];
        spent += ls;
        rem -= ls;
        u = right[u];
        v = right[v];
        lo = mid + 1;
      } else {
        u = lu;
        v = lv;
        hi = mid;
      }
    }

    if (lo === hi && rem > 0 && u !== v) {
      const c = cnt[v] - cnt[u];
      if (c > 0) {
        const s = sum[v] - sum[u];
        if (s <= rem) {
          count += c;
          spent += s;
        } else {
          const val = unique[lo];
          let take = Math.floor(rem / val);
          if (take * val > rem) {
            take--;
          }
          if ((take + 1) * val <= rem) {
            take++;
          }
          count += take;
          spent += take * val;
        }
      }
    }

    ans[qi] = [count, spent];
  }

  return ans;
}

package main

type Tuple1 struct {
	F0 int
	F1 int
}

type heapItem struct {
	target int
	idx    int32
}

type dfsFrame struct {
	node      int32
	nextChild int32
}

func CountRecords(levels []int, margin int, queries []Tuple1) []int {
	if len(queries) == 0 {
		return []int{}
	}

	n := len(levels)
	firstChild := make([]int32, n+1)
	for i := range firstChild {
		firstChild[i] = -1
	}
	nextSib := make([]int32, n)

	h := make([]heapItem, 0, n)
	popHeap := func() int32 {
		idx := h[0].idx
		last := h[len(h)-1]
		h = h[:len(h)-1]
		if m := len(h); m > 0 {
			i := 0
			for {
				c := 2*i + 1
				if c >= m {
					break
				}
				if c+1 < m && h[c+1].target < h[c].target {
					c++
				}
				if last.target <= h[c].target {
					break
				}
				h[i] = h[c]
				i = c
			}
			h[i] = last
		}
		return idx
	}

	for j := 0; j < n; j++ {
		val := levels[j]
		for len(h) > 0 && h[0].target <= val {
			idx := popHeap()
			nextSib[idx] = firstChild[j]
			firstChild[j] = idx
		}
		h = append(h, heapItem{target: val + margin, idx: int32(j)})
		i := len(h) - 1
		item := h[i]
		for i > 0 {
			p := (i - 1) >> 1
			if h[p].target <= item.target {
				break
			}
			h[i] = h[p]
			i = p
		}
		h[i] = item
	}
	for len(h) > 0 {
		idx := popHeap()
		nextSib[idx] = firstChild[n]
		firstChild[n] = idx
	}

	firstQ := make([]int32, n)
	for i := range firstQ {
		firstQ[i] = -1
	}
	nextQ := make([]int32, len(queries))
	for qi, q := range queries {
		l := q.F0
		nextQ[qi] = firstQ[l]
		firstQ[l] = int32(qi)
	}

	ans := make([]int, len(queries))
	path := make([]int32, 0, 256)
	stack := make([]dfsFrame, 0, 256)

	path = append(path, int32(n))
	stack = append(stack, dfsFrame{node: int32(n), nextChild: firstChild[n]})

	for len(stack) > 0 {
		top := &stack[len(stack)-1]
		c := top.nextChild
		if c == -1 {
			stack = stack[:len(stack)-1]
			path = path[:len(path)-1]
			continue
		}
		top.nextChild = nextSib[c]

		path = append(path, c)
		for qi := firstQ[c]; qi != -1; qi = nextQ[qi] {
			r := int32(queries[qi].F1)
			lo, hi := 0, len(path)-1
			for lo+1 < hi {
				mid := int(uint(lo+hi) >> 1)
				if path[mid] > r {
					lo = mid
				} else {
					hi = mid
				}
			}
			ans[qi] = len(path) - 1 - lo
		}
		stack = append(stack, dfsFrame{node: c, nextChild: firstChild[c]})
	}

	return ans
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1) {}

    public static List<Long> countRecords(List<Long> levels, long margin, List<Tuple1> queries) {
        if (queries.isEmpty()) {
            return new ArrayList<>();
        }

        int n = levels.size();
        long[] lvl = new long[n];
        for (int i = 0; i < n; i++) {
            lvl[i] = levels.get(i);
        }

        int[] next = new int[n + 1];
        next[n] = n;

        long[] heapVal = new long[n + 1];
        int[] heapIdx = new int[n + 1];
        int sz = 0;

        for (int j = 0; j < n; j++) {
            long curLvl = lvl[j];
            while (sz > 0 && heapVal[1] <= curLvl) {
                next[heapIdx[1]] = j;
                long v = heapVal[sz];
                int idxLast = heapIdx[sz];
                sz--;
                if (sz > 0) {
                    int p = 1;
                    while (true) {
                        int left = p << 1;
                        if (left > sz) {
                            break;
                        }
                        int smallest = left;
                        int right = left + 1;
                        if (right <= sz && heapVal[right] < heapVal[left]) {
                            smallest = right;
                        }
                        if (v <= heapVal[smallest]) {
                            break;
                        }
                        heapVal[p] = heapVal[smallest];
                        heapIdx[p] = heapIdx[smallest];
                        p = smallest;
                    }
                    heapVal[p] = v;
                    heapIdx[p] = idxLast;
                }
            }

            long target = curLvl + margin;
            sz++;
            int p = sz;
            while (p > 1) {
                int parent = p >>> 1;
                if (heapVal[parent] <= target) {
                    break;
                }
                heapVal[p] = heapVal[parent];
                heapIdx[p] = heapIdx[parent];
                p = parent;
            }
            heapVal[p] = target;
            heapIdx[p] = j;
        }

        for (int k = 1; k <= sz; k++) {
            next[heapIdx[k]] = n;
        }

        final int LOG = 18;
        int[][] up = new int[LOG][];
        up[0] = next;
        for (int k = 1; k < LOG; k++) {
            int[] prev = up[k - 1];
            int[] cur = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                cur[i] = prev[prev[i]];
            }
            up[k] = cur;
        }

        List<Long> res = new ArrayList<>(queries.size());
        for (Tuple1 q : queries) {
            int curr = (int) q.f0();
            int r = (int) q.f1();
            long ans = 1;
            for (int k = LOG - 1; k >= 0; k--) {
                int nxt = up[k][curr];
                if (nxt <= r) {
                    ans += 1L << k;
                    curr = nxt;
                }
            }
            res.add(ans);
        }

        return res;
    }
}

#include <tuple>
#include <vector>

std::vector<long long> count_records(
    const std::vector<long long>& levels,
    long long margin,
    const std::vector<std::tuple<long long, long long>>& queries) {
    if (queries.empty()) {
        return {};
    }

    const int n = static_cast<int>(levels.size());
    std::vector<int> nxt(n + 1, n);
    std::vector<int> st;
    st.reserve(n);

    for (int i = n - 1; i >= 0; --i) {
        long long target = levels[i] + margin;
        int lo = 0;
        int hi = static_cast<int>(st.size()) - 1;
        int found = n;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (levels[st[mid]] >= target) {
                found = st[mid];
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        nxt[i] = found;

        while (!st.empty() && levels[st.back()] <= levels[i]) {
            st.pop_back();
        }
        st.push_back(i);
    }

    int K = 1;
    while ((1 << K) <= n) {
        ++K;
    }

    const int stride = n + 1;
    std::vector<int> up(static_cast<std::size_t>(K) * stride, n);
    for (int i = 0; i <= n; ++i) {
        up[i] = nxt[i];
    }
    for (int k = 1; k < K; ++k) {
        const int* prev = &up[static_cast<std::size_t>(k - 1) * stride];
        int* curr = &up[static_cast<std::size_t>(k) * stride];
        for (int i = 0; i <= n; ++i) {
            curr[i] = prev[prev[i]];
        }
    }

    std::vector<long long> result;
    result.reserve(queries.size());
    for (const auto& [l_ll, r_ll] : queries) {
        int u = static_cast<int>(l_ll);
        const int r = static_cast<int>(r_ll);
        long long count = 1;
        for (int k = K - 1; k >= 0; --k) {
            int jump = up[static_cast<std::size_t>(k) * stride + u];
            if (jump <= r) {
                u = jump;
                count += (1LL << k);
            }
        }
        result.push_back(count);
    }

    return result;
}

export function countRecords(
  levels: number[],
  margin: number,
  queries: [number, number][],
): number[] {
  const qLen = queries.length;
  if (qLen === 0) {
    return [];
  }

  const n = levels.length;
  const next = new Int32Array(n + 1);
  next[n] = n;

  // Min-heap of active positions (val, idx) awaiting their next record.
  const heapVal = new Float64Array(n);
  const heapIdx = new Int32Array(n);
  let heapSize = 0;

  for (let j = 0; j < n; j++) {
    const val = levels[j];
    const threshold = val - margin;

    while (heapSize > 0 && heapVal[0] <= threshold) {
      next[heapIdx[0]] = j;
      heapSize--;
      if (heapSize > 0) {
        const lastVal = heapVal[heapSize];
        const lastIdx = heapIdx[heapSize];
        let pos = 0;
        const half = heapSize >> 1;
        while (pos < half) {
          let child = (pos << 1) + 1;
          const right = child + 1;
          if (right < heapSize && heapVal[right] < heapVal[child]) {
            child = right;
          }
          if (lastVal <= heapVal[child]) {
            break;
          }
          heapVal[pos] = heapVal[child];
          heapIdx[pos] = heapIdx[child];
          pos = child;
        }
        heapVal[pos] = lastVal;
        heapIdx[pos] = lastIdx;
      }
    }

    let pos = heapSize++;
    while (pos > 0) {
      const parent = (pos - 1) >> 1;
      if (heapVal[parent] <= val) {
        break;
      }
      heapVal[pos] = heapVal[parent];
      heapIdx[pos] = heapIdx[parent];
      pos = parent;
    }
    heapVal[pos] = val;
    heapIdx[pos] = j;
  }

  for (let i = 0; i < heapSize; i++) {
    next[heapIdx[i]] = n;
  }

  let maxLog = 1;
  while (1 << maxLog <= n) {
    maxLog++;
  }

  const up: Int32Array[] = new Array(maxLog);
  up[0] = next;
  for (let k = 1; k < maxLog; k++) {
    const prev = up[k - 1];
    const cur = new Int32Array(n + 1);
    for (let i = 0; i <= n; i++) {
      cur[i] = prev[prev[i]];
    }
    up[k] = cur;
  }

  const result = new Array<number>(qLen);
  for (let qi = 0; qi < qLen; qi++) {
    const query = queries[qi];
    let curr = query[0];
    const r = query[1];
    let count = 1;

    for (let k = maxLog - 1; k >= 0; k--) {
      const jumped = up[k][curr];
      if (jumped <= r) {
        curr = jumped;
        count += 1 << k;
      }
    }

    result[qi] = count;
  }

  return result;
}

package main

import (
	"errors"
	"math/big"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
}

func Amortize(principal string, annual_rate_pct string, months int) ([]Tuple1, error) {
	if months < 1 || months > 1200 {
		return nil, errors.New("months must be between 1 and 1200")
	}

	pCents, err := parsePrincipal(principal)
	if err != nil {
		return nil, err
	}

	rateScaled, err := parseRateScaled(annual_rate_pct)
	if err != nil {
		return nil, err
	}

	var num, den int64
	if rateScaled == 0 {
		num = 0
		den = 1
	} else {
		const baseDen int64 = 1_200_000_000
		g := gcd64(rateScaled, baseDen)
		num = rateScaled / g
		den = baseDen / g
	}

	pay := new(big.Int)
	if num == 0 {
		nBig := big.NewInt(int64(months))
		rem := new(big.Int)
		pay.QuoRem(pCents, nBig, rem)
		if rem.Sign() > 0 {
			pay.Add(pay, big.NewInt(1))
		}
	} else {
		nBig := big.NewInt(int64(months))
		dBig := big.NewInt(den)
		dPlusNum := big.NewInt(den + num)

		dPow := new(big.Int).Exp(dBig, nBig, nil)
		dPlusNumPow := new(big.Int).Exp(dPlusNum, nBig, nil)
		diff := new(big.Int).Sub(dPlusNumPow, dPow)

		numerator := new(big.Int).Mul(pCents, big.NewInt(num))
		numerator.Mul(numerator, dPlusNumPow)

		denominator := new(big.Int).Mul(dBig, diff)

		rem := new(big.Int)
		pay.QuoRem(numerator, denominator, rem)
		if rem.Sign() > 0 {
			pay.Add(pay, big.NewInt(1))
		}
	}

	bal := new(big.Int).Set(pCents)
	payStr := formatCents(pay)
	rows := make([]Tuple1, 0, months)

	prod := new(big.Int)
	q := new(big.Int)
	r := new(big.Int)
	twoR := new(big.Int)
	balPlusInt := new(big.Int)
	numBig := big.NewInt(num)
	denBig := big.NewInt(den)
	one := big.NewInt(1)

	for t := 1; t <= months; t++ {
		if num == 0 {
			q.SetInt64(0)
		} else {
			prod.Mul(bal, numBig)
			q.QuoRem(prod, denBig, r)
			twoR.Lsh(r, 1)
			cmp := twoR.Cmp(denBig)
			if cmp > 0 || (cmp == 0 && q.Bit(0) == 1) {
				q.Add(q, one)
			}
		}

		intStr := formatCents(q)
		balPlusInt.Add(bal, q)

		if t == months || balPlusInt.Cmp(pay) <= 0 {
			rows = append(rows, Tuple1{
				F0: formatCents(balPlusInt),
				F1: intStr,
				F2: "0.00",
			})
			break
		}

		bal.Sub(balPlusInt, pay)
		rows = append(rows, Tuple1{
			F0: payStr,
			F1: intStr,
			F2: formatCents(bal),
		})
	}

	return rows, nil
}

func parsePrincipal(s string) (*big.Int, error) {
	if len(s) == 0 {
		return nil, errors.New("principal cannot be empty")
	}
	dotIdx := -1
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			if dotIdx != -1 {
				return nil, errors.New("multiple decimal points in principal")
			}
			dotIdx = i
		} else if c < '0' || c > '9' {
			return nil, errors.New("invalid character in principal")
		}
	}

	var intPart, fracPart string
	if dotIdx == -1 {
		intPart = s
		fracPart = "00"
	} else {
		intPart = s[:dotIdx]
		if len(intPart) == 0 {
			return nil, errors.New("missing integer part in principal")
		}
		frac := s[dotIdx+1:]
		if len(frac) == 1 {
			fracPart = frac + "0"
		} else if len(frac) == 2 {
			fracPart = frac
		} else {
			return nil, errors.New("invalid fractional part in principal")
		}
	}

	cents, ok := new(big.Int).SetString(intPart+fracPart, 10)
	if !ok || cents.Sign() <= 0 {
		return nil, errors.New("principal must be > 0")
	}
	return cents, nil
}

func parseRateScaled(s string) (int64, error) {
	if len(s) == 0 {
		return 0, errors.New("annual_rate_pct cannot be empty")
	}
	dotIdx := -1
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			if dotIdx != -1 {
				return 0, errors.New("multiple decimal points in annual_rate_pct")
			}
			dotIdx = i
		} else if c < '0' || c > '9' {
			return 0, errors.New("invalid character in annual_rate_pct")
		}
	}

	var intPart, fracPart string
	if dotIdx == -1 {
		intPart = s
	} else {
		intPart = s[:dotIdx]
		if len(intPart) == 0 {
			return 0, errors.New("missing integer part in annual_rate_pct")
		}
		fracPart = s[dotIdx+1:]
		if len(fracPart) < 1 || len(fracPart) > 6 {
			return 0, errors.New("invalid fractional part in annual_rate_pct")
		}
	}

	i := 0
	for i < len(intPart) && intPart[i] == '0' {
		i++
	}
	trimmedInt := intPart[i:]
	if len(trimmedInt) > 3 {
		return 0, errors.New("annual_rate_pct must be <= 100")
	}

	var intVal int64
	for j := 0; j < len(trimmedInt); j++ {
		intVal = intVal*10 + int64(trimmedInt[j]-'0')
	}
	if intVal > 100 {
		return 0, errors.New("annual_rate_pct must be <= 100")
	}

	var fracVal int64
	for j := 0; j < 6; j++ {
		var d int64
		if j < len(fracPart) {
			d = int64(fracPart[j] - '0')
		}
		fracVal = fracVal*10 + d
	}

	scaled := intVal*1_000_000 + fracVal
	if scaled > 100_000_000 {
		return 0, errors.New("annual_rate_pct must be <= 100")
	}
	return scaled, nil
}

func gcd64(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func formatCents(cents *big.Int) string {
	s := cents.String()
	switch len(s) {
	case 1:
		return "0.0" + s
	case 2:
		return "0." + s
	default:
		return s[:len(s)-2] + "." + s[len(s)-2:]
	}
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2) {}

    public static List<Tuple1> amortize(String principal, String annual_rate_pct, long months) {
        if (months < 1 || months > 1200) {
            throw new IllegalArgumentException("months must be between 1 and 1200");
        }

        BigInteger principalCents = parsePrincipalCents(principal);
        BigInteger[] rateFrac = parseAnnualRatePct(annual_rate_pct);
        // Monthly rate m = p / q in lowest terms
        BigInteger mNum = rateFrac[0];
        BigInteger mDen = rateFrac[1].multiply(BigInteger.valueOf(1200));
        if (mNum.signum() == 0) {
            mDen = BigInteger.ONE;
        } else {
            BigInteger g = mNum.gcd(mDen);
            mNum = mNum.divide(g);
            mDen = mDen.divide(g);
        }

        int n = (int) months;
        BigInteger payCents;
        if (mNum.signum() == 0) {
            BigInteger bn = BigInteger.valueOf(n);
            payCents = ceilDiv(principalCents, bn);
        } else {
            BigInteger r = mDen.add(mNum);
            BigInteger rPow = r.pow(n);
            BigInteger qPow = mDen.pow(n);
            BigInteger num = principalCents.multiply(mNum).multiply(rPow);
            BigInteger den = mDen.multiply(rPow.subtract(qPow));
            payCents = ceilDiv(num, den);
        }

        List<Tuple1> schedule = new ArrayList<>();
        BigInteger balCents = principalCents;

        for (int t = 1; t <= n; t++) {
            BigInteger interestCents = mNum.signum() == 0
                    ? BigInteger.ZERO
                    : roundHalfEven(balCents.multiply(mNum), mDen);

            BigInteger totalOwed = balCents.add(interestCents);
            if (t == n || totalOwed.compareTo(payCents) <= 0) {
                schedule.add(new Tuple1(
                        formatCents(totalOwed),
                        formatCents(interestCents),
                        "0.00"
                ));
                break;
            } else {
                balCents = totalOwed.subtract(payCents);
                schedule.add(new Tuple1(
                        formatCents(payCents),
                        formatCents(interestCents),
                        formatCents(balCents)
                ));
            }
        }

        return schedule;
    }

    private static BigInteger parsePrincipalCents(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Invalid principal");
        }
        int dotIdx = s.indexOf('.');
        String intPart;
        String fracPart;
        if (dotIdx == -1) {
            intPart = s;
            fracPart = "";
        } else {
            intPart = s.substring(0, dotIdx);
            fracPart = s.substring(dotIdx + 1);
            if (fracPart.length() < 1 || fracPart.length() > 2) {
                throw new IllegalArgumentException("Invalid principal fractional part");
            }
        }
        if (!isAsciiDigits(intPart) || (!fracPart.isEmpty() && !isAsciiDigits(fracPart))) {
            throw new IllegalArgumentException("Invalid principal characters");
        }

        String paddedFrac = fracPart.length() == 0 ? "00" : (fracPart.length() == 1 ? fracPart + "0" : fracPart);
        BigInteger cents = new BigInteger(intPart + paddedFrac);
        if (cents.signum() <= 0) {
            throw new IllegalArgumentException("Principal must be > 0");
        }
        return cents;
    }

    private static BigInteger[] parseAnnualRatePct(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Invalid annual_rate_pct");
        }
        int dotIdx = s.indexOf('.');
        String intPart;
        String fracPart;
        if (dotIdx == -1) {
            intPart = s;
            fracPart = "";
        } else {
            intPart = s.substring(0, dotIdx);
            fracPart = s.substring(dotIdx + 1);
            if (fracPart.length() < 1 || fracPart.length() > 6) {
                throw new IllegalArgumentException("Invalid annual_rate_pct fractional part");
            }
        }
        if (!isAsciiDigits(intPart) || (!fracPart.isEmpty() && !isAsciiDigits(fracPart))) {
            throw new IllegalArgumentException("Invalid annual_rate_pct characters");
        }

        BigInteger num = new BigInteger(intPart + fracPart);
        BigInteger den = BigInteger.TEN.pow(fracPart.length());
        if (num.compareTo(den.multiply(BigInteger.valueOf(100))) > 0) {
            throw new IllegalArgumentException("annual_rate_pct must be <= 100");
        }
        return new BigInteger[]{num, den};
    }

    private static boolean isAsciiDigits(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static BigInteger ceilDiv(BigInteger num, BigInteger den) {
        return num.add(den).subtract(BigInteger.ONE).divide(den);
    }

    private static BigInteger roundHalfEven(BigInteger num, BigInteger den) {
        BigInteger[] qr = num.divideAndRemainder(den);
        BigInteger q = qr[0];
        BigInteger r = qr[1];
        int cmp = r.shiftLeft(1).compareTo(den);
        if (cmp > 0 || (cmp == 0 && q.testBit(0))) {
            return q.add(BigInteger.ONE);
        }
        return q;
    }

    private static String formatCents(BigInteger cents) {
        String s = cents.toString();
        int len = s.length();
        if (len == 1) {
            return "0.0" + s;
        } else if (len == 2) {
            return "0." + s;
        } else {
            return s.substring(0, len - 2) + "." + s.substring(len - 2);
        }
    }
}

#include <algorithm>
#include <cstdint>
#include <numeric>
#include <stdexcept>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

namespace {

constexpr uint64_t kBase = 1000000000ULL;

struct BigInt {
    std::vector<uint32_t> d;

    BigInt() = default;
    explicit BigInt(uint64_t v) {
        while (v > 0) {
            d.push_back(static_cast<uint32_t>(v % kBase));
            v /= kBase;
        }
    }

    bool is_zero() const { return d.empty(); }
    bool is_odd() const { return !d.empty() && (d[0] & 1U) != 0; }

    void trim() {
        while (!d.empty() && d.back() == 0) {
            d.pop_back();
        }
    }

    static BigInt from_decimal(const std::string& s) {
        size_t pos = s.find_first_not_of('0');
        if (pos == std::string::npos) {
            return BigInt(0);
        }
        BigInt res;
        size_t i = s.size();
        while (i > pos) {
            size_t start = (i >= pos + 9) ? (i - 9) : pos;
            uint32_t val = 0;
            for (size_t k = start; k < i; ++k) {
                val = val * 10U + static_cast<uint32_t>(s[k] - '0');
            }
            res.d.push_back(val);
            i = start;
        }
        res.trim();
        return res;
    }

    std::string to_decimal() const {
        if (d.empty()) {
            return "0";
        }
        std::string res = std::to_string(d.back());
        for (size_t idx = d.size() - 1; idx > 0; --idx) {
            std::string part = std::to_string(d[idx - 1]);
            res.append(9 - part.size(), '0');
            res.append(part);
        }
        return res;
    }

    static int cmp(const BigInt& a, const BigInt& b) {
        if (a.d.size() != b.d.size()) {
            return a.d.size() < b.d.size() ? -1 : 1;
        }
        for (size_t i = a.d.size(); i > 0; --i) {
            if (a.d[i - 1] != b.d[i - 1]) {
                return a.d[i - 1] < b.d[i - 1] ? -1 : 1;
            }
        }
        return 0;
    }

    friend bool operator<(const BigInt& a, const BigInt& b) { return cmp(a, b) < 0; }
    friend bool operator<=(const BigInt& a, const BigInt& b) { return cmp(a, b) <= 0; }
    friend bool operator==(const BigInt& a, const BigInt& b) { return cmp(a, b) == 0; }

    static BigInt add(const BigInt& a, const BigInt& b) {
        size_t n = std::max(a.d.size(), b.d.size());
        BigInt res;
        res.d.resize(n);
        uint64_t carry = 0;
        for (size_t i = 0; i < n; ++i) {
            uint64_t cur = carry + (i < a.d.size() ? a.d[i] : 0ULL) +
                           (i < b.d.size() ? b.d[i] : 0ULL);
            res.d[i] = static_cast<uint32_t>(cur % kBase);
            carry = cur / kBase;
        }
        if (carry > 0) {
            res.d.push_back(static_cast<uint32_t>(carry));
        }
        return res;
    }

    static BigInt sub(const BigInt& a, const BigInt& b) {
        BigInt res;
        res.d.resize(a.d.size());
        int64_t borrow = 0;
        for (size_t i = 0; i < a.d.size(); ++i) {
            int64_t cur = static_cast<int64_t>(a.d[i]) -
                          (i < b.d.size() ? static_cast<int64_t>(b.d[i]) : 0LL) - borrow;
            if (cur < 0) {
                cur += static_cast<int64_t>(kBase);
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.d[i] = static_cast<uint32_t>(cur);
        }
        res.trim();
        return res;
    }

    static BigInt mul(const BigInt& a, const BigInt& b) {
        if (a.is_zero() || b.is_zero()) {
            return BigInt(0);
        }
        BigInt res;
        res.d.assign(a.d.size() + b.d.size(), 0);
        for (size_t i = 0; i < a.d.size(); ++i) {
            uint64_t carry = 0;
            uint64_t ai = a.d[i];
            for (size_t j = 0; j < b.d.size(); ++j) {
                uint64_t cur = res.d[i + j] + ai * b.d[j] + carry;
                res.d[i + j] = static_cast<uint32_t>(cur % kBase);
                carry = cur / kBase;
            }
            res.d[i + b.d.size()] += static_cast<uint32_t>(carry);
        }
        res.trim();
        return res;
    }

    static void mul_small_into(const BigInt& a, uint64_t v, BigInt& out) {
        if (v == 0 || a.is_zero()) {
            out.d.clear();
            return;
        }
        out.d.resize(a.d.size());
        uint64_t carry = 0;
        for (size_t i = 0; i < a.d.size(); ++i) {
            uint64_t cur = static_cast<uint64_t>(a.d[i]) * v + carry;
            out.d[i] = static_cast<uint32_t>(cur % kBase);
            carry = cur / kBase;
        }
        while (carry > 0) {
            out.d.push_back(static_cast<uint32_t>(carry % kBase));
            carry /= kBase;
        }
        out.trim();
    }

    static BigInt mul_small(const BigInt& a, uint64_t v) {
        BigInt out;
        mul_small_into(a, v, out);
        return out;
    }

    static std::pair<BigInt, uint64_t> divmod_small(const BigInt& a, uint64_t divisor) {
        if (a.is_zero()) {
            return {BigInt(0), 0};
        }
        BigInt q;
        q.d.resize(a.d.size());
        uint64_t rem = 0;
        for (size_t i = a.d.size(); i > 0; --i) {
            uint64_t cur = rem * kBase + a.d[i - 1];
            q.d[i - 1] = static_cast<uint32_t>(cur / divisor);
            rem = cur % divisor;
        }
        q.trim();
        return {std::move(q), rem};
    }

    static BigInt pow(BigInt base, long long exp) {
        BigInt res(1);
        while (exp > 0) {
            if ((exp & 1LL) != 0) {
                res = mul(res, base);
            }
            exp >>= 1;
            if (exp > 0) {
                base = mul(base, base);
            }
        }
        return res;
    }

    static std::pair<BigInt, BigInt> divmod(const BigInt& a, const BigInt& b) {
        if (a < b) {
            return {BigInt(0), a};
        }
        if (b.d.size() == 1) {
            auto [q, r] = divmod_small(a, b.d[0]);
            return {std::move(q), BigInt(r)};
        }
        size_t m = a.d.size();
        size_t k = b.d.size();
        BigInt rem;
        rem.d.assign(a.d.begin() + static_cast<std::ptrdiff_t>(m - (k - 1)), a.d.end());
        rem.trim();
        BigInt q;
        q.d.assign(m - k + 1, 0);
        BigInt prod;
        for (size_t i = m - k + 1; i > 0; --i) {
            size_t idx = i - 1;
            if (!rem.d.empty()) {
                rem.d.insert(rem.d.begin(), a.d[idx]);
            } else if (a.d[idx] != 0) {
                rem.d.push_back(a.d[idx]);
            }
            if (rem < b) {
                q.d[idx] = 0;
                continue;
            }
            uint32_t lo = 1;
            uint32_t hi = static_cast<uint32_t>(kBase - 1);
            uint32_t best = 1;
            while (lo <= hi) {
                uint32_t mid = lo + (hi - lo) / 2;
                mul_small_into(b, mid, prod);
                if (prod <= rem) {
                    best = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            q.d[idx] = best;
            mul_small_into(b, best, prod);
            rem = sub(rem, prod);
        }
        q.trim();
        rem.trim();
        return {std::move(q), std::move(rem)};
    }
};

bool is_ascii_digits(const std::string& s) {
    for (char c : s) {
        if (c < '0' || c > '9') {
            return false;
        }
    }
    return true;
}

BigInt parse_principal_cents(const std::string& principal) {
    if (principal.empty()) {
        throw std::invalid_argument("empty principal");
    }
    size_t dot = principal.find('.');
    std::string cents_str;
    if (dot == std::string::npos) {
        if (!is_ascii_digits(principal)) {
            throw std::invalid_argument("invalid principal");
        }
        cents_str = principal + "00";
    } else {
        std::string int_part = principal.substr(0, dot);
        std::string frac_part = principal.substr(dot + 1);
        if (int_part.empty() || (frac_part.size() != 1 && frac_part.size() != 2)) {
            throw std::invalid_argument("invalid principal format");
        }
        if (!is_ascii_digits(int_part) || !is_ascii_digits(frac_part)) {
            throw std::invalid_argument("invalid principal digits");
        }
        cents_str = int_part + frac_part;
        if (frac_part.size() == 1) {
            cents_str.push_back('0');
        }
    }
    BigInt p_cents = BigInt::from_decimal(cents_str);
    if (p_cents.is_zero()) {
        throw std::invalid_argument("principal must be positive");
    }
    return p_cents;
}

std::pair<uint64_t, uint64_t> parse_monthly_rate(const std::string& annual_rate_pct) {
    if (annual_rate_pct.empty()) {
        throw std::invalid_argument("empty annual_rate_pct");
    }
    size_t dot = annual_rate_pct.find('.');
    std::string int_part;
    std::string frac_part;
    if (dot == std::string::npos) {
        if (!is_ascii_digits(annual_rate_pct)) {
            throw std::invalid_argument("invalid annual_rate_pct");
        }
        int_part = annual_rate_pct;
    } else {
        int_part = annual_rate_pct.substr(0, dot);
        frac_part = annual_rate_pct.substr(dot + 1);
        if (int_part.empty() || frac_part.empty() || frac_part.size() > 6) {
            throw std::invalid_argument("invalid annual_rate_pct format");
        }
        if (!is_ascii_digits(int_part) || !is_ascii_digits(frac_part)) {
            throw std::invalid_argument("invalid annual_rate_pct digits");
        }
    }

    uint64_t int_val = 0;
    size_t first_nz = int_part.find_first_not_of('0');
    if (first_nz != std::string::npos) {
        std::string trimmed = int_part.substr(first_nz);
        if (trimmed.size() > 3) {
            throw std::invalid_argument("annual_rate_pct > 100");
        }
        int_val = std::stoull(trimmed);
        if (int_val > 100) {
            throw std::invalid_argument("annual_rate_pct > 100");
        }
    }

    frac_part.append(6 - frac_part.size(), '0');
    uint64_t frac_val = std::stoull(frac_part);
    if (int_val == 100 && frac_val > 0) {
        throw std::invalid_argument("annual_rate_pct > 100");
    }

    uint64_t r_scaled = int_val * 1000000ULL + frac_val;
    if (r_scaled == 0) {
        return {0ULL, 1ULL};
    }
    constexpr uint64_t kDenom = 1200000000ULL;
    uint64_t g = std::gcd(r_scaled, kDenom);
    return {r_scaled / g, kDenom / g};
}

std::string format_cents(const BigInt& cents) {
    std::string s = cents.to_decimal();
    if (s.size() == 1) {
        return "0.0" + s;
    }
    if (s.size() == 2) {
        return "0." + s;
    }
    return s.substr(0, s.size() - 2) + "." + s.substr(s.size() - 2);
}

}  // namespace

std::vector<std::tuple<std::string, std::string, std::string>> amortize(
    const std::string& principal,
    const std::string& annual_rate_pct,
    long long months) {
    if (months < 1 || months > 1200) {
        throw std::invalid_argument("months out of range");
    }

    BigInt p_cents = parse_principal_cents(principal);
    auto [num_m, den_m] = parse_monthly_rate(annual_rate_pct);

    BigInt pay_cents;
    if (num_m == 0) {
        uint64_t n = static_cast<uint64_t>(months);
        auto [q, r] = BigInt::divmod_small(p_cents, n);
        pay_cents = (r != 0) ? BigInt::add(q, BigInt(1)) : std::move(q);
    } else {
        BigInt a_pow = BigInt::pow(BigInt(den_m + num_m), months);
        BigInt b_pow = BigInt::pow(BigInt(den_m), months);
        BigInt numerator = BigInt::mul(BigInt::mul_small(p_cents, num_m), a_pow);
        BigInt denominator = BigInt::mul_small(BigInt::sub(a_pow, b_pow), den_m);
        auto [q, r] = BigInt::divmod(numerator, denominator);
        pay_cents = (!r.is_zero()) ? BigInt::add(q, BigInt(1)) : std::move(q);
    }

    std::vector<std::tuple<std::string, std::string, std::string>> schedule;
    schedule.reserve(static_cast<size_t>(months));

    BigInt bal = p_cents;
    const BigInt one(1);
    const BigInt zero(0);
    const std::string pay_str = format_cents(pay_cents);

    for (long long t = 1; t <= months; ++t) {
        BigInt interest;
        if (num_m != 0) {
            BigInt prod = BigInt::mul_small(bal, num_m);
            auto [q, r] = BigInt::divmod_small(prod, den_m);
            uint64_t two_r = 2ULL * r;
            if (two_r > den_m || (two_r == den_m && q.is_odd())) {
                interest = BigInt::add(q, one);
            } else {
                interest = std::move(q);
            }
        }

        BigInt total_due = BigInt::add(bal, interest);
        if (t == months || total_due <= pay_cents) {
            schedule.emplace_back(
                format_cents(total_due),
                format_cents(interest),
                format_cents(zero));
            break;
        } else {
            bal = BigInt::sub(total_due, pay_cents);
            schedule.emplace_back(
                pay_str,
                format_cents(interest),
                format_cents(bal));
        }
    }

    return schedule;
}

function gcd(a: bigint, b: bigint): bigint {
  while (b !== 0n) {
    const t = a % b;
    a = b;
    b = t;
  }
  return a;
}

function formatCents(cents: bigint): string {
  const dollars = cents / 100n;
  const rem = cents % 100n;
  return `${dollars}.${rem.toString().padStart(2, '0')}`;
}

export function amortize(
  principal: string,
  annual_rate_pct: string,
  months: number,
): [string, string, string][] {
  if (typeof principal !== 'string' || !/^[0-9]+(?:\.[0-9]{1,2})?$/.test(principal)) {
    throw new Error('Invalid principal format');
  }
  if (typeof annual_rate_pct !== 'string' || !/^[0-9]+(?:\.[0-9]{1,6})?$/.test(annual_rate_pct)) {
    throw new Error('Invalid annual_rate_pct format');
  }
  if (typeof months !== 'number' || !Number.isInteger(months) || months < 1 || months > 1200) {
    throw new Error('Invalid months');
  }

  const pParts = principal.split('.');
  const pInt = pParts[0];
  const pFrac = (pParts[1] ?? '').padEnd(2, '0');
  const pCents = BigInt(pInt + pFrac);
  if (pCents <= 0n) {
    throw new Error('Principal must be > 0');
  }

  const rParts = annual_rate_pct.split('.');
  const rInt = rParts[0];
  const rFrac = (rParts[1] ?? '').padEnd(6, '0');
  const rateScaled = BigInt(rInt + rFrac);
  if (rateScaled > 100_000_000n) {
    throw new Error('Annual rate percentage must be <= 100');
  }

  // Monthly rate m = r / v in lowest terms
  const rawDen = 1_200_000_000n;
  const g = gcd(rateScaled, rawDen);
  const r = rateScaled / g;
  const v = rawDen / g;

  const nBig = BigInt(months);
  let payCents: bigint;

  if (r === 0n) {
    payCents = (pCents + nBig - 1n) / nBig;
  } else {
    const u = v + r;
    const uPow = u ** nBig;
    const vPow = v ** nBig;
    const num = pCents * r * uPow;
    const den = v * (uPow - vPow);
    payCents = (num + den - 1n) / den;
  }

  const schedule: [string, string, string][] = [];
  let bal = pCents;

  for (let t = 1; t <= months; t++) {
    const intNum = bal * r;
    const q = intNum / v;
    const rem = intNum % v;
    const twiceRem = 2n * rem;

    let interest: bigint;
    if (twiceRem > v) {
      interest = q + 1n;
    } else if (twiceRem < v) {
      interest = q;
    } else {
      interest = q % 2n === 0n ? q : q + 1n;
    }

    if (t === months || bal + interest <= payCents) {
      const finalPay = bal + interest;
      schedule.push([formatCents(finalPay), formatCents(interest), '0.00']);
      break;
    }

    bal = bal - (payCents - interest);
    schedule.push([formatCents(payCents), formatCents(interest), formatCents(bal)]);
  }

  return schedule;
}

import functools
import itertools

_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


@functools.lru_cache(maxsize=None)
def _get_chunk_info(base: int) -> tuple[int, int, tuple[str, ...]]:
    digits = _DIGITS[:base]
    c = 1
    B = base
    table = list(digits)
    while B * base <= 65536:
        c += 1
        B *= base
        table = [a + b for a in table for b in digits]
    return c, B, tuple(table)


def _format_int(n: int, base: int) -> str:
    if n == 0:
        return "0"
    digits = _DIGITS
    out: list[str] = []
    _divmod = divmod
    append = out.append
    while n:
        n, r = _divmod(n, base)
        append(digits[r])
    out.reverse()
    return "".join(out)


def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0:
        raise ValueError("q must not be zero")
    if not (2 <= base <= 36):
        raise ValueError("base must be in 2..36")
    if k < 0:
        raise ValueError("k must be non-negative")

    if p == 0:
        return "0"

    neg = (p < 0) ^ (q < 0)
    ap = -p if p < 0 else p
    aq = -q if q < 0 else q

    int_part, rem = divmod(ap, aq)

    if rem == 0:
        s = _format_int(int_part, base)
        return "-" + s if neg else s

    if k == 0:
        two_rem = rem << 1
        if two_rem > aq or (two_rem == aq and (int_part & 1)):
            int_part += 1
        if int_part == 0:
            return "0"
        s = _format_int(int_part, base)
        return "-" + s if neg else s

    # k > 0 and rem > 0: determine remainder and parity of Q mod 2 via mod 2*aq
    two_aq = aq << 1
    x = (rem * pow(base, k, two_aq)) % two_aq
    q_odd = x >= aq
    r_rem = x - aq if q_odd else x
    two_r = r_rem << 1
    if two_r > aq:
        round_up = True
    elif two_r < aq:
        round_up = False
    else:
        n_odd = ((int_part & 1) & (base & 1)) ^ int(q_odd)
        round_up = bool(n_odd)

    if k < 500:
        c = 1
        B = base
        table: tuple[str, ...] | str = _DIGITS[:base]
    else:
        c, B, table = _get_chunk_info(base)

    num_full, rem_digits = divmod(k, c)
    if rem_digits:
        last_width = rem_digits
        B_last = base ** rem_digits
        orig_len = num_full + 1
    else:
        last_width = c
        B_last = B
        orig_len = num_full

    chunk_vals: list[int] = []
    append = chunk_vals.append
    _divmod = divmod
    for _ in range(num_full):
        d, rem = _divmod(rem * B, aq)
        append(d)
        if rem == 0:
            break

    if rem_digits and rem != 0:
        d, rem = _divmod(rem * B_last, aq)
        append(d)

    if round_up:
        carry = 1
        idx = len(chunk_vals) - 1
        mod = B_last
        while idx >= 0 and carry:
            v = chunk_vals[idx] + 1
            if v == mod:
                chunk_vals[idx] = 0
                idx -= 1
                mod = B
            else:
                chunk_vals[idx] = v
                carry = 0
        if carry:
            int_part += 1

    while chunk_vals and chunk_vals[-1] == 0:
        chunk_vals.pop()

    if not chunk_vals:
        if int_part == 0:
            return "0"
        s = _format_int(int_part, base)
        return "-" + s if neg else s

    w = last_width if len(chunk_vals) == orig_len else c
    v = chunk_vals[-1]
    digits = _DIGITS
    last_chars: list[str] = []
    for _ in range(w):
        v, r = _divmod(v, base)
        last_chars.append(digits[r])
    last_chars.reverse()
    last_str = "".join(last_chars).rstrip("0")

    int_str = _format_int(int_part, base)
    if len(chunk_vals) > 1:
        prefix_frac = "".join(
            map(table.__getitem__, itertools.islice(chunk_vals, len(chunk_vals) - 1))
        )
        frac_str = prefix_frac + last_str
    else:
        frac_str = last_str

    res = f"{int_str}.{frac_str}"
    return "-" + res if neg else res

package main

import (
	"errors"
	"math"
	"math/bits"
	"strconv"
)

const baseDigits = "0123456789abcdefghijklmnopqrstuvwxyz"

func absUint64(x int) uint64 {
	if x < 0 {
		return ^uint64(x) + 1
	}
	return uint64(x)
}

func FormatBase(p int, q int, base int, k int) (string, error) {
	if q == 0 {
		return "", errors.New("q must be non-zero")
	}
	if base < 2 || base > 36 {
		return "", errors.New("base must be in 2..36")
	}
	if k < 0 {
		return "", errors.New("k must be non-negative")
	}
	if p == 0 {
		return "0", nil
	}

	neg := (p < 0) != (q < 0)
	P := absUint64(p)
	Q := absUint64(q)

	intPart := P / Q
	rem := P % Q

	if rem == 0 {
		s := strconv.FormatUint(intPart, base)
		if neg {
			return "-" + s, nil
		}
		return s, nil
	}

	if k == 0 {
		twoRem := rem << 1
		if twoRem > Q || (twoRem == Q && (intPart&1) == 1) {
			intPart++
		}
		if intPart == 0 {
			return "0", nil
		}
		s := strconv.FormatUint(intPart, base)
		if neg {
			return "-" + s, nil
		}
		return s, nil
	}

	digits := make([]byte, k)
	effLen := k
	ubase := uint64(base)
	maxSafeQ := math.MaxUint64 / ubase
	parity := intPart & 1

	if Q <= maxSafeQ {
		for i := 0; i < k; i++ {
			prod := rem * ubase
			d := prod / Q
			rem = prod % Q
			digits[i] = byte(d)
			parity ^= d & 1
			if rem == 0 {
				effLen = i + 1
				break
			}
		}
	} else {
		for i := 0; i < k; i++ {
			hi, lo := bits.Mul64(rem, ubase)
			d, newRem := bits.Div64(hi, lo, Q)
			rem = newRem
			digits[i] = byte(d)
			parity ^= d & 1
			if rem == 0 {
				effLen = i + 1
				break
			}
		}
	}

	if rem != 0 {
		twoRem := rem << 1
		var roundUp bool
		if twoRem > Q {
			roundUp = true
		} else if twoRem == Q {
			if base&1 == 0 {
				roundUp = (digits[k-1] & 1) == 1
			} else {
				roundUp = parity == 1
			}
		}

		if roundUp {
			carry := uint64(1)
			for i := k - 1; i >= 0 && carry > 0; i-- {
				val := uint64(digits[i]) + carry
				if val >= ubase {
					digits[i] = 0
				} else {
					digits[i] = byte(val)
					carry = 0
				}
			}
			if carry > 0 {
				intPart++
			}
		}
	}

	lastNonZero := effLen - 1
	for lastNonZero >= 0 && digits[lastNonZero] == 0 {
		lastNonZero--
	}

	if lastNonZero < 0 {
		if intPart == 0 {
			return "0", nil
		}
		s := strconv.FormatUint(intPart, base)
		if neg {
			return "-" + s, nil
		}
		return s, nil
	}

	intStr := strconv.FormatUint(intPart, base)
	fracLen := lastNonZero + 1
	totalLen := len(intStr) + 1 + fracLen
	if neg {
		totalLen++
	}

	out := make([]byte, totalLen)
	pos := 0
	if neg {
		out[pos] = '-'
		pos++
	}
	copy(out[pos:], intStr)
	pos += len(intStr)
	out[pos] = '.'
	pos++
	for i := 0; i < fracLen; i++ {
		out[pos+i] = baseDigits[digits[i]]
	}

	return string(out), nil
}

import java.util.*;

public final class Solution {
    public static String formatBase(long p, long q, long base, long k) {
        if (q == 0 || base < 2 || base > 36 || k < 0) {
            throw new IllegalArgumentException();
        }
        if (p == 0) {
            return "0";
        }

        boolean negative = (p < 0) ^ (q < 0);
        long P = p < 0 ? -p : p;
        long Q = q < 0 ? -q : q;

        long intPart = Long.divideUnsigned(P, Q);
        long rem = Long.remainderUnsigned(P, Q);

        int b = (int) base;
        int chunkLen = 1;
        long chunkBaseLong = b;
        while (chunkBaseLong * b <= 1_000_000_000L) {
            chunkBaseLong *= b;
            chunkLen++;
        }
        int chunkBase = (int) chunkBaseLong;

        byte[] digits = new byte[(int) Math.min(k, 4096L)];
        long pos = 0;
        int oddParity = (int) (intPart & 1L);

        while (pos < k && rem != 0) {
            long remSteps = k - pos;
            int steps = remSteps >= chunkLen ? chunkLen : (int) remSteps;
            int curBase;
            if (steps == chunkLen) {
                curBase = chunkBase;
            } else {
                curBase = 1;
                for (int i = 0; i < steps; i++) {
                    curBase *= b;
                }
            }

            int d;
            if (Q == Long.MIN_VALUE) {
                long prodLo = rem * curBase;
                long prodHi = Math.multiplyHigh(rem, (long) curBase);
                d = (int) ((prodHi << 1) | (prodLo >>> 63));
                rem = prodLo & Long.MAX_VALUE;
            } else if (Q <= Long.MAX_VALUE / curBase) {
                long prod = rem * curBase;
                d = (int) (prod / Q);
                rem = prod % Q;
            } else {
                long prodLo = rem * curBase;
                long prodHi = Math.multiplyHigh(rem, (long) curBase);
                d = (int) (((double) rem * (double) curBase) / (double) Q);
                if (d >= curBase) {
                    d = curBase - 1;
                }
                long dqLo = (long) d * Q;
                long dqHi = Math.multiplyHigh((long) d, Q);
                while (dqHi > prodHi || (dqHi == prodHi && Long.compareUnsigned(dqLo, prodLo) > 0)) {
                    d--;
                    long oldLo = dqLo;
                    dqLo -= Q;
                    if (Long.compareUnsigned(oldLo, Q) < 0) {
                        dqHi--;
                    }
                }
                long rLo = prodLo - dqLo;
                long rHi = prodHi - dqHi - (Long.compareUnsigned(prodLo, dqLo) < 0 ? 1L : 0L);
                while (rHi > 0 || Long.compareUnsigned(rLo, Q) >= 0) {
                    d++;
                    long oldLo = rLo;
                    rLo -= Q;
                    if (Long.compareUnsigned(oldLo, Q) < 0) {
                        rHi--;
                    }
                }
                rem = rLo;
            }

            if (pos + steps > digits.length) {
                long newCap = Math.min(k, Math.max((long) digits.length * 2L, pos + steps));
                digits = Arrays.copyOf(digits, (int) newCap);
            }

            int tmp = d;
            int baseIdx = (int) pos;
            for (int j = steps - 1; j >= 0; j--) {
                int qTmp = tmp / b;
                digits[baseIdx + j] = (byte) (tmp - qTmp * b);
                tmp = qTmp;
            }

            if ((b & 1) != 0) {
                oddParity ^= (d & 1);
            }
            pos += steps;
        }

        int len = (int) pos;
        int cmp = Long.compareUnsigned(rem << 1, Q);
        boolean roundUp = false;
        if (cmp > 0) {
            roundUp = true;
        } else if (cmp == 0) {
            boolean isOdd;
            if (k == 0) {
                isOdd = (intPart & 1L) != 0;
            } else if ((b & 1) == 0) {
                isOdd = (digits[len - 1] & 1) != 0;
            } else {
                isOdd = oddParity != 0;
            }
            roundUp = isOdd;
        }

        if (roundUp) {
            int i = len - 1;
            while (i >= 0) {
                int v = digits[i] + 1;
                if (v < b) {
                    digits[i] = (byte) v;
                    break;
                }
                digits[i] = 0;
                i--;
            }
            if (i < 0) {
                intPart++;
            }
        }

        while (len > 0 && digits[len - 1] == 0) {
            len--;
        }

        if (intPart == 0 && len == 0) {
            return "0";
        }

        String intStr = Long.toUnsignedString(intPart, b);
        if (len == 0) {
            return negative ? "-" + intStr : intStr;
        }

        char[] out = new char[(negative ? 1 : 0) + intStr.length() + 1 + len];
        int idx = 0;
        if (negative) {
            out[idx++] = '-';
        }
        intStr.getChars(0, intStr.length(), out, idx);
        idx += intStr.length();
        out[idx++] = '.';
        for (int j = 0; j < len; j++) {
            int d = digits[j];
            out[idx++] = (char) (d < 10 ? '0' + d : 'a' + (d - 10));
        }
        return new String(out);
    }
}

#include <algorithm>
#include <cstddef>
#include <limits>
#include <stdexcept>
#include <string>

std::string format_base(long long p, long long q, long long base, long long k) {
    if (q == 0 || base < 2 || base > 36 || k < 0) {
        throw std::invalid_argument("Invalid arguments to format_base");
    }

    if (p == 0) {
        return "0";
    }

    const bool neg = (p < 0) ^ (q < 0);
    const unsigned long long up = (p < 0)
        ? (0ULL - static_cast<unsigned long long>(p))
        : static_cast<unsigned long long>(p);
    const unsigned long long uq = (q < 0)
        ? (0ULL - static_cast<unsigned long long>(q))
        : static_cast<unsigned long long>(q);
    const unsigned long long ubase = static_cast<unsigned long long>(base);

    unsigned long long int_part = up / uq;
    unsigned long long rem = up % uq;

    unsigned int q_parity = static_cast<unsigned int>(int_part & 1ULL);
    const unsigned int base_parity = static_cast<unsigned int>(ubase & 1ULL);

    std::string frac_digits;
    if (k > 0 && rem != 0) {
        const unsigned long long fast_limit =
            std::numeric_limits<unsigned long long>::max() / ubase;

        if (uq <= fast_limit) {
            for (long long i = 0; i < k && rem != 0; ++i) {
                const unsigned long long num = rem * ubase;
                const unsigned long long d = num / uq;
                rem = num % uq;
                q_parity = (q_parity & base_parity) ^ static_cast<unsigned int>(d & 1ULL);
                frac_digits.push_back(static_cast<char>(d));
            }
        } else {
#ifdef __SIZEOF_INT128__
            const unsigned __int128 uq128 = static_cast<unsigned __int128>(uq);
            const unsigned __int128 ubase128 = static_cast<unsigned __int128>(ubase);
            for (long long i = 0; i < k && rem != 0; ++i) {
                const unsigned __int128 num = static_cast<unsigned __int128>(rem) * ubase128;
                const unsigned long long d = static_cast<unsigned long long>(num / uq128);
                rem = static_cast<unsigned long long>(num % uq128);
                q_parity = (q_parity & base_parity) ^ static_cast<unsigned int>(d & 1ULL);
                frac_digits.push_back(static_cast<char>(d));
            }
#else
            for (long long i = 0; i < k && rem != 0; ++i) {
                unsigned long long q_acc = 0;
                unsigned long long r_acc = 0;
                unsigned long long cur_q = 0;
                unsigned long long cur_r = rem;
                for (unsigned long long b = ubase; b > 0; b >>= 1) {
                    if (b & 1ULL) {
                        q_acc += cur_q;
                        if (r_acc >= uq - cur_r) {
                            r_acc -= (uq - cur_r);
                            q_acc += 1;
                        } else {
                            r_acc += cur_r;
                        }
                    }
                    if (b > 1) {
                        cur_q <<= 1;
                        if (cur_r >= uq - cur_r) {
                            cur_r -= (uq - cur_r);
                            cur_q += 1;
                        } else {
                            cur_r <<= 1;
                        }
                    }
                }
                const unsigned long long d = q_acc;
                rem = r_acc;
                q_parity = (q_parity & base_parity) ^ static_cast<unsigned int>(d & 1ULL);
                frac_digits.push_back(static_cast<char>(d));
            }
#endif
        }
    }

    if (rem != 0) {
        const unsigned long long half_cmp = uq - rem;
        const bool round_up = (rem > half_cmp) || (rem == half_cmp && q_parity == 1U);
        if (round_up) {
            bool carry = true;
            for (std::size_t idx = frac_digits.size(); idx > 0 && carry; --idx) {
                unsigned long long d = static_cast<unsigned char>(frac_digits[idx - 1]) + 1ULL;
                if (d == ubase) {
                    frac_digits[idx - 1] = 0;
                } else {
                    frac_digits[idx - 1] = static_cast<char>(d);
                    carry = false;
                }
            }
            if (carry) {
                int_part += 1;
            }
        }
    }

    while (!frac_digits.empty() && frac_digits.back() == 0) {
        frac_digits.pop_back();
    }

    if (int_part == 0 && frac_digits.empty()) {
        return "0";
    }

    auto to_digit_char = [](unsigned long long v) -> char {
        return static_cast<char>(v < 10 ? ('0' + v) : ('a' + (v - 10)));
    };

    std::string result;
    if (neg) {
        result.push_back('-');
    }

    if (int_part == 0) {
        result.push_back('0');
    } else {
        std::string int_str;
        while (int_part > 0) {
            int_str.push_back(to_digit_char(int_part % ubase));
            int_part /= ubase;
        }
        std::reverse(int_str.begin(), int_str.end());
        result += int_str;
    }

    if (!frac_digits.empty()) {
        result.push_back('.');
        const std::size_t old_size = result.size();
        result.resize(old_size + frac_digits.size());
        for (std::size_t i = 0; i < frac_digits.size(); ++i) {
            result[old_size + i] = to_digit_char(static_cast<unsigned char>(frac_digits[i]));
        }
    }

    return result;
}

const MAX_SAFE_NUM_B = Math.floor(Number.MAX_SAFE_INTEGER / 36);
const MAX_SAFE_BIG_B = BigInt(MAX_SAFE_NUM_B);

const DIGIT_CODES = new Uint8Array(36);
for (let i = 0; i < 10; i++) {
  DIGIT_CODES[i] = 48 + i;
}
for (let i = 10; i < 36; i++) {
  DIGIT_CODES[i] = 87 + i;
}

export function formatBase(p: number, q: number, base: number, k: number): string {
  if (
    !Number.isInteger(p) ||
    !Number.isInteger(q) ||
    !Number.isInteger(base) ||
    !Number.isInteger(k) ||
    q === 0 ||
    base < 2 ||
    base > 36 ||
    k < 0
  ) {
    throw new Error("Invalid arguments");
  }

  const isNeg = (p < 0) !== (q < 0);
  const bp = BigInt(p);
  const bq = BigInt(q);
  const absP = bp < 0n ? -bp : bp;
  const absQ = bq < 0n ? -bq : bq;

  let intPart = absP / absQ;
  let remBig = absP % absQ;

  const digits = new Uint8Array(k);
  let len = 0;
  let parity = Number(intPart & 1n);
  let roundUp = false;

  if (absQ <= MAX_SAFE_BIG_B) {
    const bNum = Number(absQ);
    let remNum = Number(remBig);

    for (let i = 0; i < k; i++) {
      if (remNum === 0) {
        break;
      }
      const prod = remNum * base;
      let d = Math.floor(prod / bNum);
      if (d * bNum > prod) {
        d--;
      }
      remNum = prod - d * bNum;
      digits[i] = d;
      parity ^= d;
      len = i + 1;
    }

    if (len === k && remNum !== 0) {
      const twoRem = 2 * remNum;
      if (twoRem > bNum) {
        roundUp = true;
      } else if (twoRem === bNum) {
        if (base % 2 === 0) {
          roundUp = k === 0 ? (intPart & 1n) === 1n : (digits[k - 1] & 1) === 1;
        } else {
          roundUp = (parity & 1) === 1;
        }
      }
    }
  } else {
    const baseBig = BigInt(base);

    for (let i = 0; i < k; i++) {
      if (remBig === 0n) {
        break;
      }
      const prod = remBig * baseBig;
      const dBig = prod / absQ;
      remBig = prod - dBig * absQ;
      const d = Number(dBig);
      digits[i] = d;
      parity ^= d;
      len = i + 1;
    }

    if (len === k && remBig !== 0n) {
      const twoRem = remBig * 2n;
      if (twoRem > absQ) {
        roundUp = true;
      } else if (twoRem === absQ) {
        if (base % 2 === 0) {
          roundUp = k === 0 ? (intPart & 1n) === 1n : (digits[k - 1] & 1) === 1;
        } else {
          roundUp = (parity & 1) === 1;
        }
      }
    }
  }

  if (roundUp) {
    let i = k - 1;
    while (i >= 0) {
      const v = digits[i] + 1;
      if (v < base) {
        digits[i] = v;
        break;
      }
      digits[i] = 0;
      i--;
    }
    if (i < 0) {
      intPart += 1n;
    }
  }

  let lastNonZero = len - 1;
  while (lastNonZero >= 0 && digits[lastNonZero] === 0) {
    lastNonZero--;
  }

  if (intPart === 0n && lastNonZero < 0) {
    return "0";
  }

  const sign = isNeg ? "-" : "";
  const intStr = intPart.toString(base);

  if (lastNonZero < 0) {
    return sign + intStr;
  }

  for (let i = 0; i <= lastNonZero; i++) {
    digits[i] = DIGIT_CODES[digits[i]];
  }

  const CHUNK = 8192;
  let fracStr = "";
  for (let i = 0; i <= lastNonZero; i += CHUNK) {
    const end = i + CHUNK <= lastNonZero + 1 ? i + CHUNK : lastNonZero + 1;
    fracStr += String.fromCharCode.apply(null, digits.subarray(i, end) as unknown as number[]);
  }

  return sign + intStr + "." + fracStr;
}

import re

_LITERAL_RE = re.compile(
    r"([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?"
)


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    if not isinstance(x, str):
        raise ValueError("x must be a string")
    if max_num < 0 or max_den < 1:
        raise ValueError("max_num must be >= 0 and max_den must be >= 1")

    m = _LITERAL_RE.fullmatch(x)
    if m is None:
        raise ValueError(f"Invalid decimal literal: {x!r}")

    sign_str, int_part, frac1, frac2, exp_str = m.groups()
    neg = sign_str == "-"
    int_part = int_part or ""
    frac_part = frac1 if frac1 is not None else (frac2 or "")
    exp = int(exp_str) if exp_str is not None else 0

    digits_str = (int_part + frac_part).lstrip("0")
    if not digits_str or max_num == 0:
        return "0/1"

    stripped = digits_str.rstrip("0")
    scale = exp - len(frac_part) + (len(digits_str) - len(stripped))
    digits_str = stripped

    if scale >= 0:
        if 3 * scale >= max_num.bit_length():
            return f"{'-' if neg else ''}{max_num}/1"
        p_x = int(digits_str) * (10 ** scale)
        num = min(p_x, max_num)
        return f"{'-' if neg else ''}{num}/1"

    neg_scale = -scale
    if len(digits_str) < neg_scale:
        if 3 * (neg_scale - len(digits_str)) >= (2 * max_den).bit_length():
            return "0/1"

    p_x = int(digits_str)
    q_x = 10 ** neg_scale

    if p_x >= max_num * q_x:
        return f"{'-' if neg else ''}{max_num}/1"

    # Stern-Brocot / Farey interval [a1/b1, a2/b2] bracketing p_x/q_x,
    # invariant: a2*b1 - a1*b2 == 1, err_L = b1*p_x - a1*q_x, err_R = a2*q_x - b2*p_x.
    a1, b1 = 0, 1
    a2, b2 = 1, 0
    err_L = p_x
    err_R = q_x

    while a1 + a2 <= max_num and b1 + b2 <= max_den:
        if err_R <= err_L:
            k = err_L // err_R
            if a2 > 0:
                k = min(k, (max_num - a1) // a2)
            if b2 > 0:
                k = min(k, (max_den - b1) // b2)
            a1 += k * a2
            b1 += k * b2
            err_L -= k * err_R
            if err_L == 0:
                return f"{'-' if neg else ''}{a1}/{b1}"
        else:
            k = err_R // err_L
            if a1 > 0:
                k = min(k, (max_num - a2) // a1)
            if b1 > 0:
                k = min(k, (max_den - b2) // b1)
            a2 += k * a1
            b2 += k * b1
            err_R -= k * err_L
            if err_R == 0:
                return f"{'-' if neg else ''}{a2}/{b2}"

    if b2 == 0:
        num, den = a1, b1
    else:
        left_dist = err_L * b2
        right_dist = err_R * b1
        if left_dist < right_dist:
            num, den = a1, b1
        elif right_dist < left_dist:
            num, den = a2, b2
        elif b2 < b1:
            num, den = a2, b2
        else:
            num, den = a1, b1

    if num == 0:
        return "0/1"
    return f"{'-' if neg else ''}{num}/{den}"

package main

import (
	"errors"
	"math/big"
	"strconv"
)

func ClosestFraction(x string, max_num int, max_den int) (string, error) {
	if max_num < 0 || max_den < 1 {
		return "", errors.New("invalid bounds")
	}
	maxNum := int64(max_num)
	maxDen := int64(max_den)

	n := len(x)
	i := 0

	neg := false
	if i < n && (x[i] == '+' || x[i] == '-') {
		neg = (x[i] == '-')
		i++
	}

	beforeStart := i
	for i < n && x[i] >= '0' && x[i] <= '9' {
		i++
	}
	beforeEnd := i

	afterStart, afterEnd := i, i
	if i < n && x[i] == '.' {
		i++
		afterStart = i
		for i < n && x[i] >= '0' && x[i] <= '9' {
			i++
		}
		afterEnd = i
	}

	if beforeEnd == beforeStart && afterEnd == afterStart {
		return "", errors.New("invalid decimal literal")
	}

	const expCap int64 = 1_000_000_000_000
	var expVal int64
	if i < n && (x[i] == 'e' || x[i] == 'E') {
		i++
		expNeg := false
		if i < n && (x[i] == '+' || x[i] == '-') {
			expNeg = (x[i] == '-')
			i++
		}
		expDigitsStart := i
		for i < n && x[i] >= '0' && x[i] <= '9' {
			if expVal < expCap {
				expVal = expVal*10 + int64(x[i]-'0')
				if expVal > expCap {
					expVal = expCap
				}
			}
			i++
		}
		if i == expDigitsStart {
			return "", errors.New("invalid exponent")
		}
		if expNeg {
			expVal = -expVal
		}
	}

	if i != n {
		return "", errors.New("unexpected trailing characters")
	}

	if maxNum == 0 {
		return "0/1", nil
	}

	buf := make([]byte, 0, (beforeEnd-beforeStart)+(afterEnd-afterStart))
	buf = append(buf, x[beforeStart:beforeEnd]...)
	buf = append(buf, x[afterStart:afterEnd]...)
	dotShift := afterEnd - afterStart

	lead := 0
	for lead < len(buf) && buf[lead] == '0' {
		lead++
	}
	if lead == len(buf) {
		return "0/1", nil
	}
	buf = buf[lead:]

	trail := len(buf)
	for trail > 0 && buf[trail-1] == '0' {
		trail--
		dotShift--
	}
	buf = buf[:trail]

	exp := expVal - int64(dotShift)
	lDig := int64(len(buf))

	if lDig-1+exp >= 19 {
		return formatFrac(neg, maxNum, 1), nil
	}
	if lDig+exp <= -20 {
		return "0/1", nil
	}

	p, _ := new(big.Int).SetString(string(buf), 10)
	var q *big.Int
	if exp >= 0 {
		pow10 := new(big.Int).Exp(big.NewInt(10), big.NewInt(exp), nil)
		p.Mul(p, pow10)
		q = big.NewInt(1)
	} else {
		q = new(big.Int).Exp(big.NewInt(10), big.NewInt(-exp), nil)
	}

	// Check if x_abs >= maxNum
	maxNumQ := new(big.Int).Mul(big.NewInt(maxNum), q)
	if p.Cmp(maxNumQ) >= 0 {
		return formatFrac(neg, maxNum, 1), nil
	}

	// Stern-Brocot / Euclidean search with bounds:
	// L = a1/b1 = 0/1, R = a2/b2 = 1/0
	var a1, b1 int64 = 0, 1
	var a2, b2 int64 = 1, 0

	dL := new(big.Int).Set(p) // b1*P - a1*Q
	dR := new(big.Int).Set(q) // a2*Q - b2*P

	quot := new(big.Int)
	rem := new(big.Int)
	tmp := new(big.Int)
	bigBound := new(big.Int)

	for {
		if a1+a2 > maxNum || b1+b2 > maxDen {
			break
		}
		cmp := dL.Cmp(dR)
		if cmp == 0 {
			return formatFrac(neg, a1+a2, b1+b2), nil
		}
		if cmp > 0 {
			kBound := (maxNum - a1) / a2
			if b2 > 0 {
				kDen := (maxDen - b1) / b2
				if kDen < kBound {
					kBound = kDen
				}
			}
			quot.QuoRem(dL, dR, rem)
			bigBound.SetInt64(kBound)
			var k int64
			if quot.Cmp(bigBound) >= 0 {
				k = kBound
				tmp.Mul(bigBound, dR)
				dL.Sub(dL, tmp)
			} else {
				k = quot.Int64()
				dL.Set(rem)
			}
			a1 += k * a2
			b1 += k * b2
			if dL.Sign() == 0 {
				return formatFrac(neg, a1, b1), nil
			}
		} else {
			kBound := (maxDen - b2) / b1
			if a1 > 0 {
				kNum := (maxNum - a2) / a1
				if kNum < kBound {
					kBound = kNum
				}
			}
			quot.QuoRem(dR, dL, rem)
			bigBound.SetInt64(kBound)
			var k int64
			if quot.Cmp(bigBound) >= 0 {
				k = kBound
				tmp.Mul(bigBound, dL)
				dR.Sub(dR, tmp)
			} else {
				k = quot.Int64()
				dR.Set(rem)
			}
			a2 += k * a1
			b2 += k * b1
			if dR.Sign() == 0 {
				return formatFrac(neg, a2, b2), nil
			}
		}
	}

	lhs := new(big.Int).Mul(dL, big.NewInt(b2))
	rhs := new(big.Int).Mul(dR, big.NewInt(b1))
	cmp := lhs.Cmp(rhs)
	if cmp < 0 {
		return formatFrac(neg, a1, b1), nil
	} else if cmp > 0 {
		return formatFrac(neg, a2, b2), nil
	}

	if b1 <= b2 {
		return formatFrac(neg, a1, b1), nil
	}
	return formatFrac(neg, a2, b2), nil
}

func formatFrac(neg bool, a, b int64) string {
	if a == 0 {
		return "0/1"
	}
	if neg {
		return "-" + strconv.FormatInt(a, 10) + "/" + strconv.FormatInt(b, 10)
	}
	return strconv.FormatInt(a, 10) + "/" + strconv.FormatInt(b, 10)
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    public static String closestFraction(String x, long max_num, long max_den) {
        if (x == null || max_num < 0 || max_den < 1) {
            throw new IllegalArgumentException();
        }

        int n = x.length();
        int i = 0;

        boolean neg = false;
        if (i < n && (x.charAt(i) == '+' || x.charAt(i) == '-')) {
            neg = (x.charAt(i) == '-');
            i++;
        }

        int intStart = i;
        while (i < n && isAsciiDigit(x.charAt(i))) {
            i++;
        }
        int intEnd = i;
        boolean hasIntDigits = (intEnd > intStart);

        int fracStart = i;
        int fracEnd = i;
        if (i < n && x.charAt(i) == '.') {
            i++;
            fracStart = i;
            while (i < n && isAsciiDigit(x.charAt(i))) {
                i++;
            }
            fracEnd = i;
        }
        boolean hasFracDigits = (fracEnd > fracStart);

        if (!hasIntDigits && !hasFracDigits) {
            throw new IllegalArgumentException();
        }

        long exp = 0;
        if (i < n && (x.charAt(i) == 'e' || x.charAt(i) == 'E')) {
            i++;
            boolean expNeg = false;
            if (i < n && (x.charAt(i) == '+' || x.charAt(i) == '-')) {
                expNeg = (x.charAt(i) == '-');
                i++;
            }
            int expStart = i;
            long val = 0;
            while (i < n && isAsciiDigit(x.charAt(i))) {
                if (val < 1_000_000_000L) {
                    val = val * 10 + (x.charAt(i) - '0');
                }
                i++;
            }
            if (i == expStart) {
                throw new IllegalArgumentException();
            }
            exp = expNeg ? -val : val;
        }

        if (i != n) {
            throw new IllegalArgumentException();
        }

        if (max_num == 0) {
            return "0/1";
        }

        StringBuilder sb = new StringBuilder((intEnd - intStart) + (fracEnd - fracStart));
        sb.append(x, intStart, intEnd);
        sb.append(x, fracStart, fracEnd);

        int len = sb.length();
        int firstNonZero = 0;
        while (firstNonZero < len && sb.charAt(firstNonZero) == '0') {
            firstNonZero++;
        }
        if (firstNonZero == len) {
            return "0/1";
        }

        int lastNonZero = len - 1;
        while (lastNonZero > firstNonZero && sb.charAt(lastNonZero) == '0') {
            lastNonZero--;
        }

        int trailingZeros = (len - 1) - lastNonZero;
        long fracLen = fracEnd - fracStart;
        long netExp = exp - fracLen + trailingZeros;
        String digitsStr = sb.substring(firstNonZero, lastNonZero + 1);
        int d = digitsStr.length();

        if (d - 1 + netExp >= 20L) {
            return (neg ? "-" : "") + max_num + "/1";
        }
        if (d + netExp <= -21L) {
            return "0/1";
        }

        BigInteger p = new BigInteger(digitsStr);
        BigInteger q;
        if (netExp >= 0) {
            p = p.multiply(BigInteger.TEN.pow((int) netExp));
            q = BigInteger.ONE;
        } else {
            q = BigInteger.TEN.pow((int) -netExp);
        }

        BigInteger maxNumBig = BigInteger.valueOf(max_num);
        if (p.compareTo(maxNumBig.multiply(q)) >= 0) {
            return (neg ? "-" : "") + max_num + "/1";
        }

        BigInteger[] divRem = p.divideAndRemainder(q);
        long q0 = divRem[0].longValue();
        BigInteger rem = divRem[1];

        if (rem.signum() == 0) {
            if (q0 == 0) {
                return "0/1";
            }
            return (neg ? "-" : "") + q0 + "/1";
        }

        long aL = q0;
        long bL = 1L;
        long aR = q0 + 1L;
        long bR = 1L;

        BigInteger rL = rem;
        BigInteger rR = q.subtract(rem);

        long ansA;
        long ansB;

        while (true) {
            if (aL > max_num - aR || bL > max_den - bR) {
                BigInteger dL = rL.multiply(BigInteger.valueOf(bR));
                BigInteger dR = rR.multiply(BigInteger.valueOf(bL));
                int cmp = dL.compareTo(dR);
                if (cmp < 0) {
                    ansA = aL;
                    ansB = bL;
                } else if (cmp > 0) {
                    ansA = aR;
                    ansB = bR;
                } else if (bL < bR) {
                    ansA = aL;
                    ansB = bL;
                } else if (bR < bL) {
                    ansA = aR;
                    ansB = bR;
                } else {
                    ansA = aL;
                    ansB = bL;
                }
                break;
            }

            int cmp = rL.compareTo(rR);
            if (cmp == 0) {
                ansA = aL + aR;
                ansB = bL + bR;
                break;
            } else if (cmp > 0) {
                long kBound = Math.min((max_num - aL) / aR, (max_den - bL) / bR);
                BigInteger kX = rL.divide(rR);
                long k = kX.compareTo(BigInteger.valueOf(kBound)) <= 0 ? kX.longValue() : kBound;
                aL += k * aR;
                bL += k * bR;
                rL = rL.subtract(rR.multiply(BigInteger.valueOf(k)));
                if (rL.signum() == 0) {
                    ansA = aL;
                    ansB = bL;
                    break;
                }
            } else {
                long kDen = (max_den - bR) / bL;
                long kBound = (aL == 0) ? kDen : Math.min(kDen, (max_num - aR) / aL);
                BigInteger kX = rR.divide(rL);
                long k = kX.compareTo(BigInteger.valueOf(kBound)) <= 0 ? kX.longValue() : kBound;
                aR += k * aL;
                bR += k * bL;
                rR = rR.subtract(rL.multiply(BigInteger.valueOf(k)));
                if (rR.signum() == 0) {
                    ansA = aR;
                    ansB = bR;
                    break;
                }
            }
        }

        if (ansA == 0) {
            return "0/1";
        }
        return (neg ? "-" : "") + ansA + "/" + ansB;
    }

    private static boolean isAsciiDigit(char c) {
        return c >= '0' && c <= '9';
    }
}

#include <algorithm>
#include <cstdint>
#include <stdexcept>
#include <string>
