namespace {

struct BigInt {
    static constexpr uint32_t BASE = 1000000000U;
    std::vector<uint32_t> limbs;

    void trim() {
        while (!limbs.empty() && limbs.back() == 0) {
            limbs.pop_back();
        }
    }

    bool is_zero() const {
        return limbs.empty();
    }

    static BigInt from_u64(uint64_t v) {
        BigInt r;
        while (v > 0) {
            r.limbs.push_back(static_cast<uint32_t>(v % BASE));
            v /= BASE;
        }
        return r;
    }

    static BigInt from_string(const std::string& s) {
        BigInt r;
        size_t n = s.size();
        for (size_t end = n; end > 0;) {
            size_t start = (end >= 9) ? (end - 9) : 0;
            uint32_t val = 0;
            for (size_t i = start; i < end; ++i) {
                val = val * 10 + static_cast<uint32_t>(s[i] - '0');
            }
            r.limbs.push_back(val);
            end = start;
        }
        r.trim();
        return r;
    }

    static BigInt pow10(size_t e) {
        BigInt r;
        r.limbs.assign(e / 9, 0);
        uint32_t p = 1;
        for (size_t i = 0; i < e % 9; ++i) {
            p *= 10;
        }
        r.limbs.push_back(p);
        return r;
    }

    uint64_t to_u64() const {
        uint64_t res = 0;
        for (size_t i = limbs.size(); i-- > 0;) {
            res = res * BASE + limbs[i];
        }
        return res;
    }

    int cmp(const BigInt& o) const {
        if (limbs.size() != o.limbs.size()) {
            return limbs.size() < o.limbs.size() ? -1 : 1;
        }
        for (size_t i = limbs.size(); i-- > 0;) {
            if (limbs[i] != o.limbs[i]) {
                return limbs[i] < o.limbs[i] ? -1 : 1;
            }
        }
        return 0;
    }

    bool operator<(const BigInt& o) const { return cmp(o) < 0; }
    bool operator<=(const BigInt& o) const { return cmp(o) <= 0; }
    bool operator>(const BigInt& o) const { return cmp(o) > 0; }
    bool operator>=(const BigInt& o) const { return cmp(o) >= 0; }

    BigInt& operator-=(const BigInt& o) {
        uint64_t borrow = 0;
        for (size_t i = 0; i < o.limbs.size() || borrow > 0; ++i) {
            uint64_t sub = (i < o.limbs.size() ? o.limbs[i] : 0ULL) + borrow;
            if (limbs[i] >= sub) {
                limbs[i] -= static_cast<uint32_t>(sub);
                borrow = 0;
            } else {
                limbs[i] += BASE - static_cast<uint32_t>(sub);
                borrow = 1;
            }
        }
        trim();
        return *this;
    }

    BigInt operator*(const BigInt& o) const {
        if (is_zero() || o.is_zero()) {
            return BigInt();
        }
        BigInt res;
        res.limbs.assign(limbs.size() + o.limbs.size(), 0);
        for (size_t i = 0; i < limbs.size(); ++i) {
            uint64_t carry = 0;
            uint64_t ai = limbs[i];
            for (size_t j = 0; j < o.limbs.size(); ++j) {
                uint64_t cur = res.limbs[i + j] + ai * o.limbs[j] + carry;
                res.limbs[i + j] = static_cast<uint32_t>(cur % BASE);
                carry = cur / BASE;
            }
            res.limbs[i + o.limbs.size()] += static_cast<uint32_t>(carry);
        }
        res.trim();
        return res;
    }

    static BigInt div(const BigInt& A, const BigInt& B) {
        if (A < B) {
            return BigInt();
        }
        if (B.limbs.size() == 1) {
            uint64_t d = B.limbs[0];
            BigInt q;
            q.limbs.resize(A.limbs.size(), 0);
            uint64_t rem = 0;
            for (size_t i = A.limbs.size(); i-- > 0;) {
                uint64_t cur = rem * BASE + A.limbs[i];
                q.limbs[i] = static_cast<uint32_t>(cur / d);
                rem = cur % d;
            }
            q.trim();
            return q;
        }

        uint32_t d = BASE / (B.limbs.back() + 1);
        BigInt R = (d == 1) ? A : A * from_u64(d);
        BigInt Bn = (d == 1) ? B : B * from_u64(d);
        size_t m = Bn.limbs.size();
        size_t rn = R.limbs.size();
        R.limbs.push_back(0);

        BigInt q;
        q.limbs.assign(rn - m + 1, 0);
        for (size_t i = rn - m + 1; i-- > 0;) {
            uint64_t r2 = static_cast<uint64_t>(R.limbs[i + m]) * BASE + R.limbs[i + m - 1];
            uint64_t q_est = r2 / Bn.limbs[m - 1];
            if (q_est >= BASE) {
                q_est = BASE - 1;
            }
            if (q_est > 0) {
                uint64_t borrow = 0;
                for (size_t j = 0; j < m; ++j) {
                    uint64_t prod = q_est * Bn.limbs[j] + borrow;
                    uint32_t sub = static_cast<uint32_t>(prod % BASE);
                    borrow = prod / BASE;
                    if (R.limbs[i + j] >= sub) {
                        R.limbs[i + j] -= sub;
                    } else {
                        R.limbs[i + j] += BASE - sub;
                        borrow += 1;
                    }
                }
                int64_t top = static_cast<int64_t>(R.limbs[i + m]) - static_cast<int64_t>(borrow);
                while (top < 0) {
                    --q_est;
                    uint64_t carry = 0;
                    for (size_t j = 0; j < m; ++j) {
                        uint64_t sum = static_cast<uint64_t>(R.limbs[i + j]) + Bn.limbs[j] + carry;
                        R.limbs[i + j] = static_cast<uint32_t>(sum % BASE);
                        carry = sum / BASE;
                    }
                    top += static_cast<int64_t>(carry);
                }
                R.limbs[i + m] = static_cast<uint32_t>(top);
            }
            q.limbs[i] = static_cast<uint32_t>(q_est);
        }
        q.trim();
        return q;
    }
};

std::string format_fraction(int sign, long long num, long long den) {
    if (num == 0) {
        return "0/1";
    }
    std::string res;
    if (sign < 0) {
        res.push_back('-');
    }
    res += std::to_string(num);
    res.push_back('/');
    res += std::to_string(den);
    return res;
}

