std::string closest_fraction(const std::string& x, long long max_num, long long max_den) {
    if (max_num < 0 || max_den < 1) {
        throw std::invalid_argument("Invalid fraction bounds");
    }

    const size_t n = x.size();
    size_t i = 0;

    int sign = 1;
    if (i < n && (x[i] == '+' || x[i] == '-')) {
        if (x[i] == '-') {
            sign = -1;
        }
        ++i;
    }

    size_t int_start = i;
    while (i < n && x[i] >= '0' && x[i] <= '9') {
        ++i;
    }
    size_t int_len = i - int_start;

    size_t frac_start = i;
    size_t frac_len = 0;
    if (i < n && x[i] == '.') {
        ++i;
        frac_start = i;
        while (i < n && x[i] >= '0' && x[i] <= '9') {
            ++i;
        }
        frac_len = i - frac_start;
    }

    if (int_len == 0 && frac_len == 0) {
        throw std::invalid_argument("Invalid decimal literal");
    }

    long long exp_val = 0;
    if (i < n && (x[i] == 'e' || x[i] == 'E')) {
        ++i;
        int exp_sign = 1;
        if (i < n && (x[i] == '+' || x[i] == '-')) {
            if (x[i] == '-') {
                exp_sign = -1;
            }
            ++i;
        }
        size_t exp_start = i;
        while (i < n && x[i] >= '0' && x[i] <= '9') {
            if (exp_val < 1000000000LL) {
                exp_val = exp_val * 10 + (x[i] - '0');
            }
            ++i;
        }
        if (i == exp_start) {
            throw std::invalid_argument("Invalid exponent in decimal literal");
        }
        exp_val *= exp_sign;
    }

    if (i != n) {
        throw std::invalid_argument("Invalid trailing characters in decimal literal");
    }

    if (max_num == 0) {
        return "0/1";
    }

    std::string digits;
    digits.reserve(int_len + frac_len);
    for (size_t k = int_start; k < int_start + int_len; ++k) {
        if (!digits.empty() || x[k] != '0') {
            digits.push_back(x[k]);
        }
    }
    for (size_t k = frac_start; k < frac_start + frac_len; ++k) {
        if (!digits.empty() || x[k] != '0') {
            digits.push_back(x[k]);
        }
    }

    if (digits.empty()) {
        return "0/1";
    }

    long long exp10 = exp_val - static_cast<long long>(frac_len);
    while (!digits.empty() && digits.back() == '0') {
        digits.pop_back();
        ++exp10;
    }

    long long len = static_cast<long long>(digits.size());
    if (len - 1 + exp10 >= 19) {
        return format_fraction(sign, max_num, 1);
    }
    if (len + exp10 <= -19) {
        return "0/1";
    }

    if (exp10 >= 0) {
        unsigned long long val = 0;
        for (char c : digits) {
            val = val * 10 + static_cast<unsigned long long>(c - '0');
        }
        for (long long k = 0; k < exp10; ++k) {
            val *= 10;
        }
        if (val >= static_cast<unsigned long long>(max_num)) {
            return format_fraction(sign, max_num, 1);
        }
        return format_fraction(sign, static_cast<long long>(val), 1);
    }

    BigInt N = BigInt::from_string(digits);
    BigInt D = BigInt::pow10(static_cast<size_t>(-exp10));

    if (N >= BigInt::from_u64(static_cast<uint64_t>(max_num)) * D) {
        return format_fraction(sign, max_num, 1);
    }
    if (N * BigInt::from_u64(2ULL * static_cast<uint64_t>(max_den)) <= D) {
        return "0/1";
    }

    long long a = 0, b = 1;
    long long c = 1, d = 0;
    BigInt remL = N;
    BigInt remR = D;

    while (a + c <= max_num && b + d <= max_den) {
        if (remL >= remR) {
            long long k_max = (max_num - a) / c;
            if (d > 0) {
                k_max = std::min(k_max, (max_den - b) / d);
            }
            BigInt q = BigInt::div(remL, remR);
            long long k = (q >= BigInt::from_u64(static_cast<uint64_t>(k_max)))
                              ? k_max
                              : static_cast<long long>(q.to_u64());
            a += k * c;
            b += k * d;
            remL -= remR * BigInt::from_u64(static_cast<uint64_t>(k));
            if (remL.is_zero()) {
                return format_fraction(sign, a, b);
            }
        } else {
            long long k_max = (max_den - d) / b;
            if (a > 0) {
                k_max = std::min(k_max, (max_num - c) / a);
            }
            BigInt q = BigInt::div(remR, remL);
            long long k = (q >= BigInt::from_u64(static_cast<uint64_t>(k_max)))
                              ? k_max
                              : static_cast<long long>(q.to_u64());
            c += k * a;
            d += k * b;
            remR -= remL * BigInt::from_u64(static_cast<uint64_t>(k));
            if (remR.is_zero()) {
                return format_fraction(sign, c, d);
            }
        }
    }

    BigInt distL = remL * BigInt::from_u64(static_cast<uint64_t>(d));
    BigInt distR = remR * BigInt::from_u64(static_cast<uint64_t>(b));
    int cmp = distL.cmp(distR);
    if (cmp < 0 || (cmp == 0 && b <= d)) {
        return format_fraction(sign, a, b);
    }
    return format_fraction(sign, c, d);
}

export function closestFraction(x: string, max_num: number, max_den: number): string {
  if (
    typeof x !== "string" ||
    typeof max_num !== "number" ||
    typeof max_den !== "number" ||
    !Number.isInteger(max_num) ||
    !Number.isInteger(max_den) ||
    max_num < 0 ||
    max_den < 1
  ) {
    throw new Error("Invalid arguments");
  }

  const match = /^([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?$/.exec(x);
  if (!match) {
    throw new Error("Invalid decimal literal");
  }

  const neg = match[1] === "-";
  const intPart = match[2] ?? "";
  const fracPart = match[3] ?? match[4] ?? "";
  const rawDigits = intPart + fracPart;

  if (/^0+$/.test(rawDigits) || max_num === 0) {
    return "0/1";
  }

  const exp = match[5] !== undefined ? BigInt(match[5]) : 0n;
  let exp10 = exp - BigInt(fracPart.length);

  const trimmedLeading = rawDigits.replace(/^0+/, "");
  const trimmed = trimmedLeading.replace(/0+$/, "");
  exp10 += BigInt(trimmedLeading.length - trimmed.length);

  let P = BigInt(trimmed);
  let Q = 1n;
  if (exp10 >= 0n) {
    P *= 10n ** exp10;
  } else {
    Q = 10n ** -exp10;
  }

  const M = BigInt(max_num);
  const N = BigInt(max_den);

  let a = 0n;
  let b = 1n;
  let c = 1n;
  let d = 0n;

  let u = P;
  let v = Q;

  while (a + c <= M && b + d <= N) {
    if (u === v) {
      const num = a + c;
      const den = b + d;
      return `${neg && num > 0n ? "-" : ""}${num}/${den}`;
    }

    if (u > v) {
      const kVal = u / v;
      let kBound = (M - a) / c;
      if (d > 0n) {
        const kDen = (N - b) / d;
        if (kDen < kBound) kBound = kDen;
      }
      const k = kVal < kBound ? kVal : kBound;
      a += k * c;
      b += k * d;
      u -= k * v;
      if (u === 0n) {
        return `${neg && a > 0n ? "-" : ""}${a}/${b}`;
      }
    } else {
      const kVal = v / u;
      let kBound = (N - d) / b;
      if (a > 0n) {
        const kNum = (M - c) / a;
        if (kNum < kBound) kBound = kNum;
      }
      const k = kVal < kBound ? kVal : kBound;
      c += k * a;
      d += k * b;
      v -= k * u;
      if (v === 0n) {
        return `${neg && c > 0n ? "-" : ""}${c}/${d}`;
      }
    }
  }

  let bestNum: bigint;
  let bestDen: bigint;

  if (d === 0n) {
    bestNum = a;
    bestDen = b;
  } else {
    const leftDiff = u * d;
    const rightDiff = v * b;
    if (leftDiff < rightDiff) {
      bestNum = a;
      bestDen = b;
    } else if (rightDiff < leftDiff) {
      bestNum = c;
      bestDen = d;
    } else if (b <= d) {
      bestNum = a;
      bestDen = b;
    } else {
      bestNum = c;
      bestDen = d;
    }
  }

  return `${neg && bestNum > 0n ? "-" : ""}${bestNum}/${bestDen}`;
}

_FIVE_25 = 5**25
_INF_LIMIT = 65520 * (1 << 25)


def decimal_to_half_bits(s: str) -> int:
    if not isinstance(s, str) or not s or not s.isascii():
        raise ValueError("Invalid decimal literal")

    n = len(s)
    idx = 0
    sign_bit = 0
    c0 = s[0]
    if c0 == "-":
        sign_bit = 0x8000
        idx = 1
    elif c0 == "+":
        idx = 1

    if idx >= n:
        raise ValueError("Invalid decimal literal")

    e_pos = s.find("e", idx)
    if e_pos == -1:
        e_pos = s.find("E", idx)

    if e_pos != -1:
        mantissa_end = e_pos
        exp_start = e_pos + 1
        if exp_start >= n:
            raise ValueError("Invalid decimal literal")
        ec = s[exp_start]
        if ec == "-":
            exp_neg = True
            exp_start += 1
        elif ec == "+":
            exp_neg = False
            exp_start += 1
        else:
            exp_neg = False
        if exp_start >= n:
            raise ValueError("Invalid decimal literal")
        exp_digits = s[exp_start:]
        if not exp_digits.isdigit():
            raise ValueError("Invalid decimal literal")
    else:
        mantissa_end = n
        exp_neg = False
        exp_digits = ""

    dot_pos = s.find(".", idx, mantissa_end)
    if dot_pos == -1:
        int_part = s[idx:mantissa_end]
        frac_part = ""
        if not int_part or not int_part.isdigit():
            raise ValueError("Invalid decimal literal")
    else:
        int_part = s[idx:dot_pos]
        frac_part = s[dot_pos + 1 : mantissa_end]
        if not int_part and not frac_part:
            raise ValueError("Invalid decimal literal")
        if int_part and not int_part.isdigit():
            raise ValueError("Invalid decimal literal")
        if frac_part and not frac_part.isdigit():
            raise ValueError("Invalid decimal literal")

    int_nz = int_part.lstrip("0")
    frac_nz = frac_part.rstrip("0")

    if not int_nz and not frac_nz:
        return sign_bit

    exp_digits = exp_digits.lstrip("0")
    if not exp_digits:
        exp_val = 0
    elif len(exp_digits) > 9:
        return sign_bit if exp_neg else (sign_bit | 0x7C00)
    else:
        exp_val = int(exp_digits)
        if exp_neg:
            exp_val = -exp_val

    if not frac_nz:
        sig = int_nz.rstrip("0")
        p = exp_val + (len(int_nz) - len(sig))
    elif not int_nz:
        sig = frac_nz.lstrip("0")
        p = exp_val - len(frac_nz)
    else:
        sig = int_nz + frac_nz
        p = exp_val - len(frac_nz)

    d_len = len(sig)
    mag = d_len + p - 1
    if mag >= 5:
        return sign_bit | 0x7C00
    if mag <= -9:
        return sign_bit

    if p >= -25:
        v_int = int(sig) * (10 ** (p + 25))
        has_extra = False
    else:
        cut = mag + 26
        v_int = int(sig[:cut])
        has_extra = True

    q, rem = divmod(v_int, _FIVE_25)
    if q >= _INF_LIMIT:
        return sign_bit | 0x7C00

    is_exact = (rem == 0) and not has_extra
    shift = q.bit_length() - 11
    if shift < 1:
        shift = 1

    m = q >> shift
    pat = ((shift - 1) << 10) + m
    half = 1 << (shift - 1)
    low = q & ((1 << shift) - 1)
    if low > half or (low == half and (not is_exact or (pat & 1))):
        pat += 1

    return sign_bit | pat

package main

