func DecimalToHalfBits(s string) (int, error) {
	n := len(s)
	if n == 0 {
		return 0, errors.New("invalid decimal literal")
	}

	i := 0
	signBit := 0
	if s[i] == '-' {
		signBit = 0x8000
		i++
	} else if s[i] == '+' {
		i++
	}

	intStart := i
	for i < n && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	intEnd := i

	fracStart, fracEnd := i, i
	if i < n && s[i] == '.' {
		i++
		fracStart = i
		for i < n && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		fracEnd = i
	}

	if (intEnd-intStart)+(fracEnd-fracStart) == 0 {
		return 0, errors.New("invalid decimal literal")
	}

	expNeg := false
	var expVal int64
	capExp := int64(n) + 1000
	if i < n && (s[i] == 'e' || s[i] == 'E') {
		i++
		if i < n && (s[i] == '+' || s[i] == '-') {
			if s[i] == '-' {
				expNeg = true
			}
			i++
		}
		expStart := i
		for i < n && s[i] >= '0' && s[i] <= '9' {
			if expVal < capExp {
				expVal = expVal*10 + int64(s[i]-'0')
			}
			i++
		}
		if i == expStart {
			return 0, errors.New("invalid decimal literal")
		}
	}

	if i != n {
		return 0, errors.New("invalid decimal literal")
	}

	intPart := s[intStart:intEnd]
	fracPart := s[fracStart:fracEnd]

	var leadPlace int64
	var s1, s2 string
	found := false

	for k := 0; k < len(intPart); k++ {
		if intPart[k] != '0' {
			leadPlace = int64(len(intPart) - 1 - k)
			s1 = intPart[k:]
			s2 = fracPart
			found = true
			break
		}
	}
	if !found {
		for k := 0; k < len(fracPart); k++ {
			if fracPart[k] != '0' {
				leadPlace = int64(-1 - k)
				s1 = fracPart[k:]
				found = true
				break
			}
		}
	}

	if !found {
		return signBit, nil
	}

	signedExp := expVal
	if expNeg {
		signedExp = -expVal
	}
	leadExp10 := leadPlace + signedExp

	if leadExp10 >= 5 {
		return signBit | 0x7C00, nil
	}
	if leadExp10 <= -9 {
		return signBit, nil
	}

	var hi, lo uint64
	p := leadExp10
	sticky := false

	addDigit := func(d uint64) {
		c1, newLo := bits.Mul64(lo, 10)
		newLo, c2 := bits.Add64(newLo, d, 0)
		hi = hi*10 + c1 + c2
		lo = newLo
	}

	idx := 0
	for ; idx < len(s1) && p >= -25; idx++ {
		addDigit(uint64(s1[idx] - '0'))
		p--
	}
	if idx < len(s1) {
		for ; idx < len(s1); idx++ {
			if s1[idx] != '0' {
				sticky = true
				break
			}
		}
		if !sticky {
			for j := 0; j < len(s2); j++ {
				if s2[j] != '0' {
					sticky = true
					break
				}
			}
		}
	} else {
		j := 0
		for ; j < len(s2) && p >= -25; j++ {
			addDigit(uint64(s2[j] - '0'))
			p--
		}
		for ; j < len(s2); j++ {
			if s2[j] != '0' {
				sticky = true
				break
			}
		}
	}

	for p >= -25 {
		addDigit(0)
		p--
	}

	const five25 uint64 = 298023223876953125
	q, r := bits.Div64(hi, lo, five25)
	hasFrac := r != 0 || sticky

	const overflowQ uint64 = 65520 << 25
	if q >= overflowQ {
		return signBit | 0x7C00, nil
	}

	if q < 2048 {
		f := q >> 1
		if q&1 == 1 {
			if hasFrac || f&1 == 1 {
				f++
			}
		}
		return signBit | int(f), nil
	}

	msb := bits.Len64(q) - 1
	e := msb - 10
	shift := uint(e - 1)
	halfUnits := q >> shift
	remBits := q & ((uint64(1) << shift) - 1)

	u := halfUnits - 2048
	f := u >> 1
	if u&1 == 1 {
		if remBits != 0 || hasFrac || f&1 == 1 {
			f++
		}
	}

	return signBit | ((e << 10) + int(f)), nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    private static final BigInteger DEN = BigInteger.valueOf(2980232238769531250L); // 5^25 * 10
    private static final long INF_THRESHOLD_Q = 4095L << 29; // 65520 * 2^25

    public static long decimalToHalfBits(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Empty or null literal");
        }

        int n = s.length();
        int i = 0;

        boolean neg = false;
        char c = s.charAt(i);
        if (c == '-') {
            neg = true;
            i++;
        } else if (c == '+') {
            i++;
        }

        int intStart = i;
        while (i < n) {
            c = s.charAt(i);
            if (c >= '0' && c <= '9') {
                i++;
            } else {
                break;
            }
        }
        int intEnd = i;

        int fracStart = i;
        int fracEnd = i;
        if (i < n && s.charAt(i) == '.') {
            i++;
            fracStart = i;
            while (i < n) {
                c = s.charAt(i);
                if (c >= '0' && c <= '9') {
                    i++;
                } else {
                    break;
                }
            }
            fracEnd = i;
        }

        if ((intEnd - intStart) + (fracEnd - fracStart) == 0) {
            throw new IllegalArgumentException("Missing mantissa digits");
        }

        boolean hasExp = false;
        boolean expNeg = false;
        int expStart = 0;
        int expEnd = 0;
        if (i < n && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
            hasExp = true;
            i++;
            if (i < n) {
                c = s.charAt(i);
                if (c == '-') {
                    expNeg = true;
                    i++;
                } else if (c == '+') {
                    i++;
                }
            }
            expStart = i;
            while (i < n) {
                c = s.charAt(i);
                if (c >= '0' && c <= '9') {
                    i++;
                } else {
                    break;
                }
            }
            expEnd = i;
            if (expEnd == expStart) {
                throw new IllegalArgumentException("Missing exponent digits");
            }
        }

        if (i != n) {
            throw new IllegalArgumentException("Invalid trailing characters");
        }

        int firstNzIdx = -1;
        long mantissaExp = 0;
        for (int j = intStart; j < intEnd; j++) {
            if (s.charAt(j) != '0') {
                firstNzIdx = j;
                mantissaExp = intEnd - 1 - j;
                break;
            }
        }
        if (firstNzIdx == -1) {
            for (int j = fracStart; j < fracEnd; j++) {
                if (s.charAt(j) != '0') {
                    firstNzIdx = j;
                    mantissaExp = -(long) (j - fracStart + 1);
                    break;
                }
            }
        }
        if (firstNzIdx == -1) {
            return neg ? 0x8000L : 0L;
        }

        long expVal = 0;
        if (hasExp) {
            int j = expStart;
            while (j < expEnd && s.charAt(j) == '0') {
                j++;
            }
            if (expEnd - j > 9) {
                if (expNeg) {
                    return neg ? 0x8000L : 0L;
                } else {
                    return neg ? 0xFC00L : 0x7C00L;
                }
            }
            while (j < expEnd) {
                expVal = expVal * 10 + (s.charAt(j) - '0');
                j++;
            }
            if (expNeg) {
                expVal = -expVal;
            }
        }

        long exp10 = mantissaExp + expVal;
        if (exp10 >= 5) {
            return neg ? 0xFC00L : 0x7C00L;
        }
        if (exp10 <= -9) {
            return neg ? 0x8000L : 0L;
        }

        // Exact digits down to 10^-25 plus a sticky digit at 10^-26.
        int len = (int) exp10 + 27;
        char[] buf = new char[len];
        Arrays.fill(buf, '0');

        int out = 0;
        boolean sticky = false;
        int p = firstNzIdx;
        if (firstNzIdx < intEnd) {
            while (p < intEnd) {
                char d = s.charAt(p++);
                if (out < len - 1) {
                    buf[out++] = d;
                } else if (d != '0') {
                    sticky = true;
                    break;
                }
            }
            p = fracStart;
        }
        if (!sticky) {
            while (p < fracEnd) {
                char d = s.charAt(p++);
                if (out < len - 1) {
                    buf[out++] = d;
                } else if (d != '0') {
                    sticky = true;
                    break;
                }
            }
        }
        if (sticky) {
            buf[len - 1] = '1';
        }

        BigInteger num = new BigInteger(new String(buf));
        BigInteger[] qr = num.divideAndRemainder(DEN);
        long q = qr[0].longValue();
        long r = qr[1].longValue();

        if (q >= INF_THRESHOLD_Q) {
            return neg ? 0xFC00L : 0x7C00L;
        }

        long bits;
        if (q < 2048L) {
            long m = q >>> 1;
            long remQ = q & 1L;
            if (remQ == 1L && (r > 0L || (m & 1L) == 1L)) {
                m++;
            }
            bits = m;
        } else {
            int b = 63 - Long.numberOfLeadingZeros(q);
            int e = b - 10;
            long m = q >>> e;
            long remQ = q & ((1L << e) - 1L);
            long halfQ = 1L << (e - 1);
            if (remQ > halfQ || (remQ == halfQ && (r > 0L || (m & 1L) == 1L))) {
                m++;
            }
            bits = ((long) e << 10) + (m - 1024L);
        }

        return neg ? (0x8000L | bits) : bits;
    }
}

#include <algorithm>
#include <compare>
