namespace {

struct u128 {
    std::uint64_t hi = 0;
    std::uint64_t lo = 0;

    bool operator==(const u128&) const = default;

    std::strong_ordering operator<=>(const u128& o) const {
        if (hi != o.hi) {
            return hi <=> o.hi;
        }
        return lo <=> o.lo;
    }

    static u128 mul64(std::uint64_t a, std::uint64_t b) {
        std::uint64_t a0 = static_cast<std::uint32_t>(a);
        std::uint64_t a1 = a >> 32;
        std::uint64_t b0 = static_cast<std::uint32_t>(b);
        std::uint64_t b1 = b >> 32;

        std::uint64_t p00 = a0 * b0;
        std::uint64_t p01 = a0 * b1;
        std::uint64_t p10 = a1 * b0;
        std::uint64_t p11 = a1 * b1;

        std::uint64_t mid = (p00 >> 32) + static_cast<std::uint32_t>(p01) +
                            static_cast<std::uint32_t>(p10);
        std::uint64_t res_lo = (p00 & 0xFFFFFFFFULL) | (mid << 32);
        std::uint64_t res_hi = p11 + (p01 >> 32) + (p10 >> 32) + (mid >> 32);
        return {res_hi, res_lo};
    }

    void mul10_add(std::uint32_t d) {
        std::uint64_t lo2 = lo << 1;
        std::uint64_t hi2 = (hi << 1) | (lo >> 63);
        std::uint64_t lo8 = lo << 3;
        std::uint64_t hi8 = (hi << 3) | (lo >> 61);

        std::uint64_t new_lo = lo8 + lo2;
        std::uint64_t carry = (new_lo < lo8) ? 1ULL : 0ULL;
        std::uint64_t new_hi = hi8 + hi2 + carry;

        std::uint64_t final_lo = new_lo + d;
        if (final_lo < new_lo) {
            ++new_hi;
        }
        hi = new_hi;
        lo = final_lo;
    }
};

std::uint64_t half_val_25(long long k) {
    if (k == 0x7C00) {
        return 1ULL << 41;
    }
    long long e = k >> 10;
    long long f = k & 0x3FF;
    if (e == 0) {
        return static_cast<std::uint64_t>(2 * f);
    }
    return static_cast<std::uint64_t>(1024 + f) << e;
}

}  // namespace

long long decimal_to_half_bits(const std::string& s) {
    const std::size_t n = s.size();
    if (n == 0) {
        throw std::invalid_argument("empty decimal literal");
    }

    std::size_t i = 0;
    long long sign_bit = 0;
    if (s[i] == '+') {
        ++i;
    } else if (s[i] == '-') {
        sign_bit = 1;
        ++i;
    }

    const std::size_t int_start = i;
    while (i < n && s[i] >= '0' && s[i] <= '9') {
        ++i;
    }
    const std::size_t int_end = i;

    std::size_t frac_start = i;
    std::size_t frac_end = i;
    if (i < n && s[i] == '.') {
        ++i;
        frac_start = i;
        while (i < n && s[i] >= '0' && s[i] <= '9') {
            ++i;
        }
        frac_end = i;
    }

    if (int_start == int_end && frac_start == frac_end) {
        throw std::invalid_argument("invalid mantissa");
    }

    long long exp_val = 0;
    const long long exp_cap = static_cast<long long>(n) + 1000LL;
    if (i < n && (s[i] == 'e' || s[i] == 'E')) {
        ++i;
        bool exp_neg = false;
        if (i < n && (s[i] == '+' || s[i] == '-')) {
            exp_neg = (s[i] == '-');
            ++i;
        }
        const std::size_t exp_digits_start = i;
        while (i < n && s[i] >= '0' && s[i] <= '9') {
            if (exp_val < exp_cap) {
                exp_val = exp_val * 10 + (s[i] - '0');
                if (exp_val > exp_cap) {
                    exp_val = exp_cap;
                }
            }
            ++i;
        }
        if (i == exp_digits_start) {
            throw std::invalid_argument("invalid exponent");
        }
        if (exp_neg) {
            exp_val = -exp_val;
        }
    }

    if (i != n) {
        throw std::invalid_argument("trailing characters in literal");
    }

    const std::size_t int_len = int_end - int_start;
    const std::size_t frac_len = frac_end - frac_start;
    const std::size_t total_digits = int_len + frac_len;

    auto digit_at = [&](std::size_t idx) -> char {
        if (idx < int_len) {
            return s[int_start + idx];
        }
        return s[frac_start + (idx - int_len)];
    };

    std::size_t first_nz = total_digits;
    for (std::size_t p = int_start; p < int_end; ++p) {
        if (s[p] != '0') {
            first_nz = p - int_start;
            break;
        }
    }
    if (first_nz == total_digits) {
        for (std::size_t p = frac_start; p < frac_end; ++p) {
            if (s[p] != '0') {
                first_nz = int_len + (p - frac_start);
                break;
            }
        }
    }

    if (first_nz == total_digits) {
        return sign_bit << 15;
    }

    const long long e10 =
        static_cast<long long>(int_len) - 1 - static_cast<long long>(first_nz) + exp_val;

    if (e10 >= 5) {
        return (sign_bit << 15) | 0x7C00;
    }
    if (e10 <= -9) {
        return sign_bit << 15;
    }

    const std::size_t num_scaled_digits = static_cast<std::size_t>(e10 + 26);
    u128 scaled_val{0, 0};
    for (std::size_t offset = 0; offset < num_scaled_digits; ++offset) {
        std::size_t idx = first_nz + offset;
        std::uint32_t d =
            (idx < total_digits) ? static_cast<std::uint32_t>(digit_at(idx) - '0') : 0U;
        scaled_val.mul10_add(d);
    }

    bool has_rem = false;
    for (std::size_t idx = first_nz + num_scaled_digits; idx < total_digits; ++idx) {
        if (digit_at(idx) != '0') {
            has_rem = true;
            break;
        }
    }

    constexpr std::uint64_t FIVE_POW_25 = 298023223876953125ULL;
    long long lo = 0;
    long long hi = 0x7C00;
    while (lo < hi) {
        long long mid = lo + (hi - lo + 1) / 2;
        u128 cand = u128::mul64(half_val_25(mid), FIVE_POW_25);
        if (cand <= scaled_val) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }

    long long ans = 0;
    if (lo == 0x7C00) {
        ans = 0x7C00;
    } else {
        std::uint64_t mid_25 = (half_val_25(lo) + half_val_25(lo + 1)) / 2;
        u128 mid_val = u128::mul64(mid_25, FIVE_POW_25);
        if (scaled_val < mid_val) {
            ans = lo;
        } else if (scaled_val > mid_val) {
            ans = lo + 1;
        } else if (has_rem) {
            ans = lo + 1;
        } else {
            ans = (lo & 1) ? (lo + 1) : lo;
        }
    }

    return (sign_bit << 15) | ans;
}

const UNIT = 298023223876953125n; // 5^25
const MAX_Q = 2198486368256n; // 65520 * 2^25

const POW10: bigint[] = [];
{
  let v = 1n;
  for (let k = 0; k <= 30; k++) {
    POW10.push(v);
    v *= 10n;
  }
}

export function decimalToHalfBits(s: string): number {
  if (typeof s !== "string") {
    throw new Error("Expected a string");
  }

  const n = s.length;
  if (n === 0) {
    throw new Error("Invalid decimal literal: empty string");
  }

  let i = 0;
  let negative = false;
  const c0 = s.charCodeAt(0);
  if (c0 === 45 /* '-' */) {
    negative = true;
    i = 1;
  } else if (c0 === 43 /* '+' */) {
    i = 1;
  }
  const signBit = negative ? 0x8000 : 0;

  const intStart = i;
  while (i < n) {
    const c = s.charCodeAt(i);
    if (c < 48 || c > 57) break;
    i++;
  }
  const intEnd = i;

  let fracStart = i;
  let fracEnd = i;
  if (i < n && s.charCodeAt(i) === 46 /* '.' */) {
    i++;
    fracStart = i;
    while (i < n) {
      const c = s.charCodeAt(i);
      if (c < 48 || c > 57) break;
      i++;
    }
    fracEnd = i;
  }

  if (intEnd === intStart && fracEnd === fracStart) {
    throw new Error("Invalid decimal literal: missing mantissa digits");
  }

  let exp = 0;
  if (i < n) {
    const ce = s.charCodeAt(i);
    if (ce !== 101 /* 'e' */ && ce !== 69 /* 'E' */) {
      throw new Error("Invalid character in decimal literal");
    }
    i++;

    let expNeg = false;
    if (i < n) {
      const cs = s.charCodeAt(i);
      if (cs === 45 /* '-' */) {
        expNeg = true;
        i++;
      } else if (cs === 43 /* '+' */) {
        i++;
      }
    }

    if (i >= n) {
      throw new Error("Invalid decimal literal: missing exponent digits");
    }

    const expCap = n + 100;
    while (i < n) {
      const c = s.charCodeAt(i);
      if (c < 48 || c > 57) {
        throw new Error("Invalid character in exponent");
      }
      if (exp < expCap) {
        exp = exp * 10 + (c - 48);
      }
      i++;
    }
    if (expNeg) {
      exp = -exp;
    }
  }

  let firstIdx = -1;
  let baseExp = 0;
  for (let j = intStart; j < intEnd; j++) {
    if (s.charCodeAt(j) !== 48 /* '0' */) {
      firstIdx = j;
      baseExp = intEnd - 1 - j;
      break;
    }
  }
  if (firstIdx === -1) {
    for (let j = fracStart; j < fracEnd; j++) {
      if (s.charCodeAt(j) !== 48 /* '0' */) {
        firstIdx = j;
        baseExp = -(j - fracStart + 1);
        break;
      }
    }
  }

  if (firstIdx === -1) {
    return signBit;
  }

  const p = baseExp + exp;
  if (p > 4) {
    return signBit | 0x7c00;
  }
  if (p < -8) {
    return signBit;
  }

  const need = p + 26; // between 18 and 30 inclusive
  let taken = 0;
  let scaledInt = 0n;
  let hasSticky = false;

  if (firstIdx < intEnd) {
    let j = firstIdx;
    while (j < intEnd && taken < need) {
      scaledInt = scaledInt * 10n + BigInt(s.charCodeAt(j) - 48);
      taken++;
      j++;
    }
    while (j < intEnd) {
      if (s.charCodeAt(j) !== 48) {
        hasSticky = true;
        break;
      }
      j++;
    }

    j = fracStart;
    while (j < fracEnd && taken < need) {
      scaledInt = scaledInt * 10n + BigInt(s.charCodeAt(j) - 48);
      taken++;
      j++;
    }
    if (!hasSticky) {
      while (j < fracEnd) {
        if (s.charCodeAt(j) !== 48) {
          hasSticky = true;
          break;
        }
        j++;
      }
    }
  } else {
    let j = firstIdx;
    while (j < fracEnd && taken < need) {
      scaledInt = scaledInt * 10n + BigInt(s.charCodeAt(j) - 48);
      taken++;
      j++;
    }
    while (j < fracEnd) {
      if (s.charCodeAt(j) !== 48) {
        hasSticky = true;
        break;
      }
      j++;
    }
  }

  if (taken < need) {
    scaledInt *= POW10[need - taken];
  }

  const q = scaledInt / UNIT;
  if (q >= MAX_Q) {
    return signBit | 0x7c00;
  }

  const r = scaledInt % UNIT;
  const exact = r === 0n && !hasSticky;

  if (q === 0n || (q === 1n && exact)) {
    return signBit;
  }

  const qn = Number(q);
  let E: number;
  if (qn < 2048) {
    E = 1;
  } else {
    const hi = Math.floor(qn / 4294967296);
    const bitLen = hi !== 0 ? 64 - Math.clz32(hi) : 32 - Math.clz32(qn);
    E = bitLen - 11;
  }

  const sig = Number(q >> BigInt(E));
  const half = 1n << BigInt(E - 1);
  const rem = q & ((1n << BigInt(E)) - 1n);

  let pattern = ((E - 1) << 10) + sig;
  if (rem > half || (rem === half && (!exact || (sig & 1) === 1))) {
    pattern++;
  }

  return signBit | pattern;
}

from collections import OrderedDict
import heapq


def run_cache(capacity, ops):
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, seq]; least recently used first
    exp_heap = []          # min-heap of (expires_at, seq, key)
    out = []
    last_t = None
    seq = 0

    heappush = heapq.heappush
    heappop = heapq.heappop

    def purge(t):
        while exp_heap and exp_heap[0][0] <= t:
            _, entry_seq, k = heappop(exp_heap)
            entry = store.get(k)
            if entry is not None and entry[1] == entry_seq:
                del store[k]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            purge(t)
            seq += 1
            if ttl is not None:
                heappush(exp_heap, (t + ttl, seq, key))
            entry = store.get(key)
            if entry is not None:
                entry[0] = value
                entry[1] = seq
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = [value, seq]

        elif kind == "get":
            key = op[2]
            purge(t)
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            purge(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

