import (
	"container/heap"
	"fmt"
	"sort"
)

type Tuple1 struct {
	F0 string
	F1 int
	F2 int
	F3 int
	F4 *int
}

type Tuple2 struct {
	F0 string
	F1 int
	F2 int
}

type Tuple3 struct {
	F0 []Tuple2
	F1 []string
}

type jobHeap []Tuple1

func (h jobHeap) Len() int { return len(h) }

func (h jobHeap) Less(i, j int) bool {
	if h[i].F3 != h[j].F3 {
		return h[i].F3 > h[j].F3
	}
	if h[i].F1 != h[j].F1 {
		return h[i].F1 < h[j].F1
	}
	return h[i].F0 < h[j].F0
}

func (h jobHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *jobHeap) Push(x any) {
	*h = append(*h, x.(Tuple1))
}

func (h *jobHeap) Pop() any {
	old := *h
	n := len(old)
	item := old[n-1]
	*h = old[:n-1]
	return item
}

func Schedule(jobs []Tuple1) (Tuple3, error) {
	seen := make(map[string]struct{}, len(jobs))
	for _, job := range jobs {
		if _, exists := seen[job.F0]; exists {
			return Tuple3{}, fmt.Errorf("duplicate job id %q", job.F0)
		}
		seen[job.F0] = struct{}{}
		if job.F1 < 0 {
			return Tuple3{}, fmt.Errorf("job %q has a negative release time", job.F0)
		}
		if job.F2 < 1 {
			return Tuple3{}, fmt.Errorf("job %q has a non-positive duration", job.F0)
		}
	}

	sorted := make([]Tuple1, len(jobs))
	copy(sorted, jobs)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].F1 < sorted[j].F1
	})

	runs := []Tuple2{}
	dropped := []string{}
	ready := &jobHeap{}
	clock := 0
	nxt := 0
	n := len(sorted)

	for nxt < n || ready.Len() > 0 {
		for nxt < n && sorted[nxt].F1 <= clock {
			heap.Push(ready, sorted[nxt])
			nxt++
		}
		if ready.Len() == 0 {
			clock = sorted[nxt].F1
			continue
		}

		best := heap.Pop(ready).(Tuple1)
		if best.F4 != nil && clock+best.F2 > *best.F4 {
			dropped = append(dropped, best.F0)
			continue
		}
		runs = append(runs, Tuple2{
			F0: best.F0,
			F1: clock,
			F2: clock + best.F2,
		})
		clock += best.F2
	}

	return Tuple3{F0: runs, F1: dropped}, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1, long f2, long f3, Long f4) {}

    public record Tuple2(String f0, long f1, long f2) {}

    public record Tuple3(List<Tuple2> f0, List<String> f1) {}

    public static Tuple3 schedule(List<Tuple1> jobs) {
        if (jobs == null) {
            throw new IllegalArgumentException("jobs must not be null");
        }

        Set<String> seen = HashSet.newHashSet(jobs.size());
        for (Tuple1 job : jobs) {
            if (job == null || job.f0() == null) {
                throw new IllegalArgumentException("each job must be a valid 5-tuple with non-null job_id");
            }
            String jobId = job.f0();
            if (!seen.add(jobId)) {
                throw new IllegalArgumentException("duplicate job id: " + jobId);
            }
            if (job.f1() < 0) {
                throw new IllegalArgumentException("job " + jobId + " has a negative release time");
            }
            if (job.f2() < 1) {
                throw new IllegalArgumentException("job " + jobId + " has a non-positive duration");
            }
        }

        Tuple1[] sorted = jobs.toArray(new Tuple1[0]);
        Arrays.sort(sorted, Comparator.comparingLong(Tuple1::f1));

        Comparator<Tuple1> rankComparator = (a, b) -> {
            int cmp = Long.compare(b.f3(), a.f3());
            if (cmp != 0) {
                return cmp;
            }
            cmp = Long.compare(a.f1(), b.f1());
            if (cmp != 0) {
                return cmp;
            }
            return a.f0().compareTo(b.f0());
        };

        PriorityQueue<Tuple1> ready = new PriorityQueue<>(Math.max(1, sorted.length), rankComparator);
        List<Tuple2> runs = new ArrayList<>();
        List<String> dropped = new ArrayList<>();

        long clock = 0;
        int nxt = 0;
        int n = sorted.length;

        while (nxt < n || !ready.isEmpty()) {
            if (ready.isEmpty() && sorted[nxt].f1() > clock) {
                clock = sorted[nxt].f1();
            }
            while (nxt < n && sorted[nxt].f1() <= clock) {
                ready.add(sorted[nxt]);
                nxt++;
            }

            Tuple1 best = ready.poll();
            long duration = best.f2();
            Long deadline = best.f4();
            if (deadline != null && (deadline < clock || duration > deadline - clock)) {
                dropped.add(best.f0());
                continue;
            }

            long end = clock + duration;
            runs.add(new Tuple2(best.f0(), clock, end));
            clock = end;
        }

        return new Tuple3(runs, dropped);
    }
}

#include <algorithm>
