std::tuple<std::vector<std::tuple<std::string, long long, long long>>, std::vector<std::string>>
schedule(const std::vector<std::tuple<std::string, long long, long long, long long, std::optional<long long>>>& jobs) {
    std::unordered_set<std::string_view> seen;
    seen.reserve(jobs.size());
    for (const auto& job : jobs) {
        const auto& [job_id, release, duration, priority, deadline] = job;
        (void)priority;
        (void)deadline;
        if (!seen.insert(job_id).second) {
            throw std::invalid_argument("duplicate job id");
        }
        if (release < 0) {
            throw std::invalid_argument("negative release time");
        }
        if (duration < 1) {
            throw std::invalid_argument("non-positive duration");
        }
    }

    struct ReleaseEntry {
        long long release;
        std::size_t idx;
    };

    std::vector<ReleaseEntry> order;
    order.reserve(jobs.size());
    for (std::size_t i = 0; i < jobs.size(); ++i) {
        order.push_back({std::get<1>(jobs[i]), i});
    }
    std::sort(order.begin(), order.end(), [](const ReleaseEntry& a, const ReleaseEntry& b) {
        return a.release < b.release;
    });

    struct ReadyEntry {
        long long priority;
        long long release;
        std::string_view id;
        std::size_t idx;
    };

    struct ReadyCmp {
        bool operator()(const ReadyEntry& a, const ReadyEntry& b) const {
            if (a.priority != b.priority) {
                return a.priority < b.priority;
            }
            if (a.release != b.release) {
                return a.release > b.release;
            }
            return a.id > b.id;
        }
    };

    std::vector<ReadyEntry> pq_container;
    pq_container.reserve(jobs.size());
    std::priority_queue<ReadyEntry, std::vector<ReadyEntry>, ReadyCmp> pq(ReadyCmp{}, std::move(pq_container));

    std::vector<std::tuple<std::string, long long, long long>> runs;
    std::vector<std::string> dropped;

    long long clock = 0;
    std::size_t nxt = 0;
    const std::size_t n = order.size();

    while (nxt < n || !pq.empty()) {
        if (pq.empty() && order[nxt].release > clock) {
            clock = order[nxt].release;
        }
        while (nxt < n && order[nxt].release <= clock) {
            const std::size_t idx = order[nxt].idx;
            const auto& job = jobs[idx];
            pq.push({std::get<3>(job), std::get<1>(job), std::get<0>(job), idx});
            ++nxt;
        }

        const std::size_t idx = pq.top().idx;
        pq.pop();

        const auto& [job_id, release, duration, priority, deadline] = jobs[idx];
        (void)release;
        (void)priority;
        if (deadline.has_value() && (*deadline < clock || duration > *deadline - clock)) {
            dropped.push_back(job_id);
            continue;
        }
        runs.emplace_back(job_id, clock, clock + duration);
        clock += duration;
    }

    return {std::move(runs), std::move(dropped)};
}

type Job = [string, number, number, number, number | null];

function isBetter(a: Job, b: Job): boolean {
  if (a[3] !== b[3]) return a[3] > b[3];
  if (a[1] !== b[1]) return a[1] < b[1];
  return a[0] < b[0];
}

function heapPush(heap: Job[], job: Job): void {
  let idx = heap.length;
  heap.push(job);
  while (idx > 0) {
    const parent = (idx - 1) >> 1;
    if (!isBetter(heap[idx], heap[parent])) break;
    const tmp = heap[idx];
    heap[idx] = heap[parent];
    heap[parent] = tmp;
    idx = parent;
  }
}

function heapPop(heap: Job[]): Job {
  const top = heap[0];
  const last = heap.pop()!;
  const len = heap.length;
  if (len > 0) {
    heap[0] = last;
    let idx = 0;
    while (true) {
      const left = (idx << 1) + 1;
      if (left >= len) break;
      const right = left + 1;
      let best = left;
      if (right < len && isBetter(heap[right], heap[left])) {
        best = right;
      }
      if (!isBetter(heap[best], heap[idx])) break;
      const tmp = heap[idx];
      heap[idx] = heap[best];
      heap[best] = tmp;
      idx = best;
    }
  }
  return top;
}

export function schedule(
  jobs: ([string, number, number, number, number | null])[],
): [[string, number, number][], string[]] {
  const seen = new Set<string>();
  for (let i = 0; i < jobs.length; i++) {
    const job = jobs[i];
    if (!Array.isArray(job) || job.length !== 5) {
      throw new Error("each job must be a 5-tuple");
    }
    const [jobId, release, duration] = job;
    if (seen.has(jobId)) {
      throw new Error(`duplicate job id ${JSON.stringify(jobId)}`);
    }
    seen.add(jobId);
    if (release < 0) {
      throw new Error(`job ${JSON.stringify(jobId)} has a negative release time`);
    }
    if (duration < 1) {
      throw new Error(`job ${JSON.stringify(jobId)} has a non-positive duration`);
    }
  }

  const sorted = jobs.slice().sort((a, b) => (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));

  const runs: [string, number, number][] = [];
  const dropped: string[] = [];
  const ready: Job[] = [];
  let clock = 0;
  let nxt = 0;

  while (nxt < sorted.length || ready.length > 0) {
    if (ready.length === 0 && sorted[nxt][1] > clock) {
      clock = sorted[nxt][1];
    }
    while (nxt < sorted.length && sorted[nxt][1] <= clock) {
      heapPush(ready, sorted[nxt]);
      nxt++;
    }

    const best = heapPop(ready);
    const [jobId, , duration, , deadline] = best;
    if (deadline !== null && clock + duration > deadline) {
      dropped.push(jobId);
      continue;
    }
    runs.push([jobId, clock, clock + duration]);
    clock += duration;
  }

  return [runs, dropped];
}

import heapq


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []       # max-heap via negation: the smaller half, its top is the median
    high = []      # min-heap: the larger half
    delayed = {}   # value -> pending lazy deletions (positive count)
    low_size = 0   # live (not yet deleted) element count in low
    high_size = 0  # live (not yet deleted) element count in high
    out = []

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap:
            val = sign * heap[0]
            cnt = delayed.get(val)
            if not cnt:
                break
            if cnt == 1:
                del delayed[val]
            else:
                delayed[val] = cnt - 1
            heapq.heappop(heap)

    def rebalance():
        nonlocal low_size, high_size
        # invariant: low_size == high_size or low_size == high_size + 1
        if low_size > high_size + 1:
            heapq.heappush(high, -heapq.heappop(low))
            low_size -= 1
            high_size += 1
            prune(low, -1)
        elif low_size < high_size:
            heapq.heappush(low, -heapq.heappop(high))
            high_size -= 1
            low_size += 1
            prune(high, 1)

    def add(x):
        nonlocal low_size, high_size
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            low_size += 1
        else:
            heapq.heappush(high, x)
            high_size += 1
        rebalance()

    def remove(x):
        nonlocal low_size, high_size
        delayed[x] = delayed.get(x, 0) + 1
        if x <= -low[0]:
            low_size -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            high_size -= 1
            if x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k:
            old = readings[i - k]
            if old is not None:
                remove(old)
        out.append(-low[0] if low_size else None)

    return out

package main

import "errors"

func WindowMedians(readings []*int, k int) ([]*int, error) {
	if k < 1 {
		return nil, errors.New("k must be a positive int")
	}

	n := len(readings)
	out := make([]*int, n)
	if n == 0 {
		return out, nil
	}
	vals := make([]int, n)

	var low []int  // max-heap: smaller half, low[0] is the median
	var high []int // min-heap: larger half
	delayed := make(map[int]int)
	lowSize, highSize := 0, 0

	pruneLow := func() {
		for len(low) > 0 {
			top := low[0]
			c := delayed[top]
			if c == 0 {
				break
			}
			if c == 1 {
				delete(delayed, top)
			} else {
				delayed[top] = c - 1
			}
			low, _ = maxPop(low)
		}
	}

	pruneHigh := func() {
		for len(high) > 0 {
			top := high[0]
			c := delayed[top]
			if c == 0 {
				break
			}
			if c == 1 {
				delete(delayed, top)
			} else {
				delayed[top] = c - 1
			}
			high, _ = minPop(high)
		}
	}

	rebalance := func() {
		if lowSize > highSize+1 {
			var v int
			low, v = maxPop(low)
			high = minPush(high, v)
			lowSize--
			highSize++
			pruneLow()
		} else if lowSize < highSize {
			var v int
			high, v = minPop(high)
			low = maxPush(low, v)
			highSize--
			lowSize++
			pruneHigh()
		}
	}

	add := func(x int) {
		if lowSize == 0 || x <= low[0] {
			low = maxPush(low, x)
			lowSize++
		} else {
			high = minPush(high, x)
			highSize++
		}
		rebalance()
	}

	remove := func(x int) {
		delayed[x]++
		if lowSize > 0 && x <= low[0] {
			lowSize--
			if x == low[0] {
				pruneLow()
			}
		} else {
			highSize--
			if len(high) > 0 && x == high[0] {
				pruneHigh()
			}
		}
		rebalance()
	}

	for i, x := range readings {
		if x != nil {
			add(*x)
		}
		if i >= k && readings[i-k] != nil {
			remove(*readings[i-k])
		}
		if lowSize > 0 {
			vals[i] = low[0]
			out[i] = &vals[i]
		}
	}

	return out, nil
}

func maxPush(h []int, x int) []int {
	h = append(h, x)
	i := len(h) - 1
	for i > 0 {
		p := (i - 1) / 2
		if h[p] >= h[i] {
			break
		}
		h[p], h[i] = h[i], h[p]
		i = p
	}
	return h
}

func maxPop(h []int) ([]int, int) {
	top := h[0]
	n := len(h) - 1
	h[0] = h[n]
	h = h[:n]
	i := 0
	for {
		l := 2*i + 1
		if l >= n {
			break
		}
		best := l
		r := l + 1
		if r < n && h[r] > h[l] {
			best = r
		}
		if h[i] >= h[best] {
			break
		}
		h[i], h[best] = h[best], h[i]
		i = best
	}
	return h, top
}

func minPush(h []int, x int) []int {
	h = append(h, x)
	i := len(h) - 1
	for i > 0 {
		p := (i - 1) / 2
		if h[p] <= h[i] {
			break
		}
		h[p], h[i] = h[i], h[p]
		i = p
	}
	return h
}

func minPop(h []int) ([]int, int) {
	top := h[0]
	n := len(h) - 1
	h[0] = h[n]
	h = h[:n]
	i := 0
	for {
		l := 2*i + 1
		if l >= n {
			break
		}
		best := l
		r := l + 1
		if r < n && h[r] < h[l] {
			best = r
		}
		if h[i] <= h[best] {
			break
		}
		h[i], h[best] = h[best], h[i]
		i = best
	}
	return h, top
}

import java.util.*;

public final class Solution {

    private static final class MedianTracker {
        private final TreeMap<Long, Long> low = new TreeMap<>();
        private final TreeMap<Long, Long> high = new TreeMap<>();
        private long lowSize = 0;
        private long highSize = 0;

        void add(long x) {
            if (lowSize == 0 || x <= low.lastKey()) {
                increment(low, x);
                lowSize++;
            } else {
                increment(high, x);
                highSize++;
            }
            rebalance();
        }

        void remove(long x) {
            if (lowSize > 0 && x <= low.lastKey()) {
                decrement(low, x);
                lowSize--;
            } else {
                decrement(high, x);
                highSize--;
            }
            rebalance();
        }

        Long median() {
            return lowSize > 0 ? low.lastKey() : null;
        }

        private void rebalance() {
            if (lowSize > highSize + 1) {
                long val = low.lastKey();
                decrement(low, val);
                lowSize--;
                increment(high, val);
                highSize++;
            } else if (lowSize < highSize) {
                long val = high.firstKey();
                decrement(high, val);
                highSize--;
                increment(low, val);
                lowSize++;
            }
        }

        private static void increment(TreeMap<Long, Long> map, long key) {
            Long count = map.get(key);
            map.put(key, count == null ? 1L : count + 1L);
        }

        private static void decrement(TreeMap<Long, Long> map, long key) {
            long count = map.get(key);
            if (count == 1L) {
                map.remove(key);
            } else {
                map.put(key, count - 1L);
            }
        }
    }

    public static List<Long> windowMedians(List<Long> readings, long k) {
        if (k < 1) {
            throw new IllegalArgumentException("k must be a positive int");
        }
        if (readings == null) {
            throw new IllegalArgumentException("readings must not be null");
        }

        List<Long> out = new ArrayList<>(readings.size());
        MedianTracker tracker = new MedianTracker();
        Iterator<Long> head = readings.iterator();
        Iterator<Long> tail = readings.iterator();

        for (long i = 0; head.hasNext(); i++) {
            Long x = head.next();
            if (x != null) {
                tracker.add(x);
            }
            if (i >= k) {
                Long old = tail.next();
                if (old != null) {
                    tracker.remove(old);
                }
            }
            out.add(tracker.median());
        }

        return out;
    }
}

#include <cstddef>
