namespace {

struct SplitMix64Hash {
    std::size_t operator()(long long key) const noexcept {
        std::uint64_t x = static_cast<std::uint64_t>(key);
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        x = x ^ (x >> 31);
        return static_cast<std::size_t>(x);
    }
};

}  // namespace

std::vector<std::optional<long long>> window_medians(
    const std::vector<std::optional<long long>>& readings, long long k) {
    if (k < 1) {
        throw std::invalid_argument("k must be a positive int");
    }

    std::priority_queue<long long> low;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> high;
    std::unordered_map<long long, std::size_t, SplitMix64Hash> delayed;
    std::size_t low_size = 0;
    std::size_t high_size = 0;

    std::vector<std::optional<long long>> out;
    out.reserve(readings.size());

    auto prune_low = [&]() {
        while (!low.empty()) {
            auto it = delayed.find(low.top());
            if (it != delayed.end() && it->second > 0) {
                if (--(it->second) == 0) {
                    delayed.erase(it);
                }
                low.pop();
            } else {
                break;
            }
        }
    };

    auto prune_high = [&]() {
        while (!high.empty()) {
            auto it = delayed.find(high.top());
            if (it != delayed.end() && it->second > 0) {
                if (--(it->second) == 0) {
                    delayed.erase(it);
                }
                high.pop();
            } else {
                break;
            }
        }
    };

    auto rebalance = [&]() {
        if (low_size > high_size + 1) {
            high.push(low.top());
            low.pop();
            --low_size;
            ++high_size;
            prune_low();
        } else if (low_size < high_size) {
            low.push(high.top());
            high.pop();
            --high_size;
            ++low_size;
            prune_high();
        }
    };

    auto add = [&](long long x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
            ++low_size;
        } else {
            high.push(x);
            ++high_size;
        }
        rebalance();
    };

    auto remove = [&](long long x) {
        ++delayed[x];
        if (x <= low.top()) {
            --low_size;
            if (x == low.top()) {
                prune_low();
            }
        } else {
            --high_size;
            if (x == high.top()) {
                prune_high();
            }
        }
        rebalance();
    };

    const unsigned long long uk = static_cast<unsigned long long>(k);
    for (std::size_t i = 0; i < readings.size(); ++i) {
        if (readings[i].has_value()) {
            add(*readings[i]);
        }
        if (static_cast<unsigned long long>(i) >= uk) {
            const std::size_t old_idx = i - static_cast<std::size_t>(uk);
            if (readings[old_idx].has_value()) {
                remove(*readings[old_idx]);
            }
        }
        if (low_size > 0) {
            out.push_back(low.top());
        } else {
            out.push_back(std::nullopt);
        }
    }

    return out;
}

class Heap {
  data: number[] = [];
  isMax: boolean;

  constructor(isMax: boolean) {
    this.isMax = isMax;
  }

  get length(): number {
    return this.data.length;
  }

  peek(): number {
    return this.data[0];
  }

  push(val: number): void {
    const data = this.data;
    data.push(val);
    let idx = data.length - 1;
    if (this.isMax) {
      while (idx > 0) {
        const parent = (idx - 1) >>> 1;
        if (data[parent] >= val) break;
        data[idx] = data[parent];
        idx = parent;
      }
    } else {
      while (idx > 0) {
        const parent = (idx - 1) >>> 1;
        if (data[parent] <= val) break;
        data[idx] = data[parent];
        idx = parent;
      }
    }
    data[idx] = val;
  }

  pop(): number {
    const data = this.data;
    const top = data[0];
    const last = data.pop()!;
    const n = data.length;
    if (n > 0) {
      let idx = 0;
      const half = n >>> 1;
      if (this.isMax) {
        while (idx < half) {
          let best = idx * 2 + 1;
          const right = best + 1;
          if (right < n && data[right] > data[best]) {
            best = right;
          }
          if (last >= data[best]) break;
          data[idx] = data[best];
          idx = best;
        }
      } else {
        while (idx < half) {
          let best = idx * 2 + 1;
          const right = best + 1;
          if (right < n && data[right] < data[best]) {
            best = right;
          }
          if (last <= data[best]) break;
          data[idx] = data[best];
          idx = best;
        }
      }
      data[idx] = last;
    }
    return top;
  }
}

export function windowMedians(readings: (number | null)[], k: number): (number | null)[] {
  if (!Number.isInteger(k) || k < 1) {
    throw new Error("k must be a positive integer");
  }

  const low = new Heap(true);   // max-heap: smaller half, top is median
  const high = new Heap(false); // min-heap: larger half
  const delayed = new Map<number, number>();
  let lowSize = 0;
  let highSize = 0;
  const out: (number | null)[] = new Array(readings.length);

  function prune(heap: Heap): void {
    while (heap.length > 0) {
      const top = heap.peek();
      const count = delayed.get(top);
      if (count !== undefined && count > 0) {
        if (count === 1) {
          delayed.delete(top);
        } else {
          delayed.set(top, count - 1);
        }
        heap.pop();
      } else {
        break;
      }
    }
  }

  function rebalance(): void {
    if (lowSize > highSize + 1) {
      high.push(low.pop());
      lowSize -= 1;
      highSize += 1;
      prune(low);
    } else if (lowSize < highSize) {
      low.push(high.pop());
      highSize -= 1;
      lowSize += 1;
      prune(high);
    }
  }

  function add(x: number): void {
    if (low.length === 0 || x <= low.peek()) {
      low.push(x);
      lowSize += 1;
    } else {
      high.push(x);
      highSize += 1;
    }
    rebalance();
  }

  function remove(x: number): void {
    delayed.set(x, (delayed.get(x) ?? 0) + 1);
    if (x <= low.peek()) {
      lowSize -= 1;
      if (x === low.peek()) {
        prune(low);
      }
    } else {
      highSize -= 1;
      if (x === high.peek()) {
        prune(high);
      }
    }
    rebalance();
  }

  for (let i = 0; i < readings.length; i++) {
    const x = readings[i];
    if (x !== null) {
      add(x);
    }
    if (i >= k) {
      const outgoing = readings[i - k];
      if (outgoing !== null) {
        remove(outgoing);
      }
    }
    out[i] = lowSize > 0 ? low.peek() : null;
  }

  return out;
}

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            if end == -1:
                break
            i = end + 1
            line += 1
            col = 1
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    j = k
                    while j < n and _is_digit(src[j]):
                        j += 1
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
